/* @rottay/design-system - bithire vertical bundle */
/* Generated by build-vertical-css.mjs */
/* Structure: first-party fonts + base tokens + modern engine + bithire tenant (unlayered, wins by specificity) */

/* === First-party vertical font packs === */
/**
 * Font pack: humanist-text (Public Sans).
 *
 * Opt-in subpath: @rottay/design-system/fonts/humanist-text.css. It also ships
 * with the first-party BitHire vertical bundle. Public Sans is a variable humanist sans
 * (OFL-1.1); the latin-subset variable file carries the 400-600 range this pack
 * advertises. The custom property is defined UNCONDITIONALLY so the
 * already-validated var(--ds-font-pack-humanist-text) channel resolves when this
 * css is present.
 */

@font-face {
  font-family: 'Public Sans';
  font-style: normal;
  font-weight: 400 600;
  font-display: swap;
  src: url('./fonts/public-sans-latin-variable.woff2') format('woff2');
}

:root {
  --ds-font-pack-humanist-text: 'Public Sans', ui-sans-serif, system-ui, -apple-system, sans-serif;
}

/**
 * Font pack: grotesk-display (Space Grotesk).
 *
 * Opt-in subpath: @rottay/design-system/fonts/grotesk-display.css. It also ships
 * with the first-party BitHire vertical bundle. Space Grotesk is a variable grotesque
 * (OFL-1.1); the latin-subset variable file carries the 400-700 range this pack
 * advertises. The custom property is defined UNCONDITIONALLY so the
 * already-validated var(--ds-font-pack-grotesk-display) channel resolves when
 * this css is present.
 */

@font-face {
  font-family: 'Space Grotesk';
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url('./fonts/space-grotesk-latin-variable.woff2') format('woff2');
}

:root {
  --ds-font-pack-grotesk-display: 'Space Grotesk', ui-sans-serif, system-ui, -apple-system, sans-serif;
}

/**
 * Font pack: plex-mono (IBM Plex Mono).
 *
 * Opt-in subpath: @rottay/design-system/fonts/plex-mono.css. It also ships with
 * the first-party BitHire vertical bundle. IBM Plex Mono ships as static latin-subset
 * instances (OFL-1.1), one file per weight. The custom property is defined
 * UNCONDITIONALLY so the already-validated var(--ds-font-pack-plex-mono) channel
 * resolves when this css is present.
 */

@font-face {
  font-family: 'IBM Plex Mono';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('./fonts/ibm-plex-mono-latin-400.woff2') format('woff2');
}

@font-face {
  font-family: 'IBM Plex Mono';
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url('./fonts/ibm-plex-mono-latin-600.woff2') format('woff2');
}

:root {
  --ds-font-pack-plex-mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, monospace;
}


/**
 * Rottay Design System - Tenant-free base CSS
 *
 * Contains everything from index.css except compiled tenant paint.
 * Used by build-vertical-css.mjs to create per-vertical dist bundles
 * that include only one tenant's CSS.
 *
 * The canonical named-layer order is declared below. Compiled tenant paint is
 * intentionally unlayered and omitted here; each vertical bundle appends one
 * authoritative tenant artifact after this tenant-free base.
 *
 * @version 1.0.0
 */

/*
 * Cross-framework cascade contract.
 *
 * Consumer Tailwind owns the top-level `theme`, `base`, `components`, and
 * `utilities` layers. The Modern engine's bundled Tailwind artifact is
 * separately nested under `rottay-framework`: it is a DS implementation
 * dependency, not consumer chrome. First-party tokens and skins therefore win
 * over the bundled framework by layer ownership, while product components and
 * utilities remain intentionally above the bounded DS skins.
 */
@layer theme, base, rottay-framework, rottay-reset, rottay-tokens, rottay-motion, rottay-components, rottay-engines, rottay-personality, rottay-responsive, components, utilities;

/* Layer 0: antd reset */
@import "antd/dist/reset.css" layer(rottay-reset);

/* Layer 1: DS foundation + default theme */
@layer rottay-tokens {
/**
 * Base Tokens Index - Rottay Design System
 *
 * Supplemental semantic token layer for the DS-prefixed runtime.
 * Import this file to get the extended spacing, border, shadow, typography,
 * and z-index aliases that sit on top of the canonical theme palettes.
 */

/**
 * Base Spacing Tokens - Rottay Design System
 *
 * Spacing scale based on 4px grid for consistency.
 * All spacing values are multiples of 4px.
 */

:root {
  /* ========================================================================
     SPACING SCALE - 4px Grid System
     Used for margins, paddings, gaps, and any dimensional spacing.

     Each public --ds-spacing-* step is a calc() over its literal times the
     bounded --ds-density-effective-scale. That effective channel composes the
     structural var(--ds-density-scale, 1), tenant appearance
     var(--ds-density-mode-factor, 1), and optional subtree posture
     var(--ds-density-local-factor, 1). This is the spacing analogue of the
     font-size ramp's var(--ds-type-scale, 1). When the density axis is
     absent the fallback 1 makes every step resolve to its literal byte-for-byte
     (calc(1rem * 1) computes to 1rem). A root-level appearance factor or tenant
     structural scale therefore affects this global ramp. A descendant
     data-density boundary cannot recompute an inherited custom property by
     changing only one of its inputs; foundation/base/density.css redeclares the
     effective ramp and aliases on that boundary for true subtree locality.
     --ds-spacing-0 stays literal 0 (scaling zero is a no-op).

     NOTE: themes/default.css redefines the common steps (0-64) and wins the
     rottay-tokens cascade (imported later); it must carry the same calc wrap
     over its own literals for density to reach those steps — the steps only
     defined here (7, 9, 11, 14, 28, 36, 44, 52, 56, 60, 72, 80, 96) already
     scale from this file. The fluid ramp below is a separate opt-in axis and is
     intentionally NOT density-wrapped.
     ======================================================================== */
  --ds-density-global-effective-scale: clamp(
    0.5,
    calc(var(--ds-density-scale, 1) * var(--ds-density-mode-factor, 1)),
    3
  );
  --ds-density-effective-scale: clamp(
    0.5,
    calc(
      var(--ds-density-global-effective-scale, 1) *
      var(--ds-density-local-factor, 1)
    ),
    3
  );
  --ds-spacing-0: 0;
  --ds-spacing-1: calc(0.25rem * var(--ds-density-effective-scale, 1));   /* 4px */
  --ds-spacing-2: calc(0.5rem * var(--ds-density-effective-scale, 1));    /* 8px */
  --ds-spacing-3: calc(0.75rem * var(--ds-density-effective-scale, 1));   /* 12px */
  --ds-spacing-4: calc(1rem * var(--ds-density-effective-scale, 1));      /* 16px */
  --ds-spacing-5: calc(1.25rem * var(--ds-density-effective-scale, 1));   /* 20px */
  --ds-spacing-6: calc(1.5rem * var(--ds-density-effective-scale, 1));    /* 24px */
  --ds-spacing-7: calc(1.75rem * var(--ds-density-effective-scale, 1));   /* 28px */
  --ds-spacing-8: calc(2rem * var(--ds-density-effective-scale, 1));      /* 32px */
  --ds-spacing-9: calc(2.25rem * var(--ds-density-effective-scale, 1));   /* 36px */
  --ds-spacing-10: calc(2.5rem * var(--ds-density-effective-scale, 1));   /* 40px */
  --ds-spacing-11: calc(2.75rem * var(--ds-density-effective-scale, 1));  /* 44px */
  --ds-spacing-12: calc(3rem * var(--ds-density-effective-scale, 1));     /* 48px */
  --ds-spacing-14: calc(3.5rem * var(--ds-density-effective-scale, 1));   /* 56px */
  --ds-spacing-16: calc(4rem * var(--ds-density-effective-scale, 1));     /* 64px */
  --ds-spacing-20: calc(5rem * var(--ds-density-effective-scale, 1));     /* 80px */
  --ds-spacing-24: calc(6rem * var(--ds-density-effective-scale, 1));     /* 96px */
  --ds-spacing-28: calc(7rem * var(--ds-density-effective-scale, 1));     /* 112px */
  --ds-spacing-32: calc(8rem * var(--ds-density-effective-scale, 1));     /* 128px */
  --ds-spacing-36: calc(9rem * var(--ds-density-effective-scale, 1));     /* 144px */
  --ds-spacing-40: calc(10rem * var(--ds-density-effective-scale, 1));    /* 160px */
  --ds-spacing-44: calc(11rem * var(--ds-density-effective-scale, 1));    /* 176px */
  --ds-spacing-48: calc(12rem * var(--ds-density-effective-scale, 1));    /* 192px */
  --ds-spacing-52: calc(13rem * var(--ds-density-effective-scale, 1));    /* 208px */
  --ds-spacing-56: calc(14rem * var(--ds-density-effective-scale, 1));    /* 224px */
  --ds-spacing-60: calc(15rem * var(--ds-density-effective-scale, 1));    /* 240px */
  --ds-spacing-64: calc(16rem * var(--ds-density-effective-scale, 1));    /* 256px */
  --ds-spacing-72: calc(18rem * var(--ds-density-effective-scale, 1));    /* 288px */
  --ds-spacing-80: calc(20rem * var(--ds-density-effective-scale, 1));    /* 320px */
  --ds-spacing-96: calc(24rem * var(--ds-density-effective-scale, 1));    /* 384px */

  /* ========================================================================
     NAMED SPACING - Semantic Aliases
     Commonly used spacing values with semantic names
     ======================================================================== */
  --ds-spacing-xxxs: var(--ds-spacing-1);   /* 4px */
  --ds-spacing-xxs: var(--ds-spacing-2);    /* 8px */
  --ds-spacing-xs: var(--ds-spacing-3);     /* 12px */
  --ds-spacing-sm: var(--ds-spacing-4);     /* 16px */
  --ds-spacing-md: var(--ds-spacing-6);     /* 24px */
  --ds-spacing-lg: var(--ds-spacing-8);     /* 32px */
  --ds-spacing-xl: var(--ds-spacing-10);    /* 40px */
  --ds-spacing-2xl: var(--ds-spacing-12);   /* 48px */
  --ds-spacing-3xl: var(--ds-spacing-16);   /* 64px */
  --ds-spacing-4xl: var(--ds-spacing-20);   /* 80px */
  --ds-spacing-5xl: var(--ds-spacing-24);   /* 96px */

  /* ========================================================================
     LAYOUT SPACING - Page/Section Level
     Used for larger layout spacing needs
     ======================================================================== */
  --ds-spacing-gutter: var(--ds-spacing-4);        /* 16px - Base gutter */
  --ds-spacing-gutter-sm: var(--ds-spacing-2);     /* 8px - Small screens */
  --ds-spacing-gutter-md: var(--ds-spacing-6);     /* 24px - Medium screens */
  --ds-spacing-gutter-lg: var(--ds-spacing-8);     /* 32px - Large screens */
  --ds-spacing-gutter-xl: var(--ds-spacing-12);    /* 48px - Extra large screens */

  --ds-spacing-section: var(--ds-spacing-16);      /* 64px - Section spacing */
  --ds-spacing-section-sm: var(--ds-spacing-8);    /* 32px - Small sections */
  --ds-spacing-section-lg: var(--ds-spacing-24);   /* 96px - Large sections */

  --ds-spacing-container: var(--ds-spacing-6);     /* 24px - Container padding */
  --ds-spacing-container-sm: var(--ds-spacing-4);  /* 16px - Small containers */
  --ds-spacing-container-lg: var(--ds-spacing-12); /* 48px - Large containers */

  /* ========================================================================
     COMPONENT SPACING - Component-Specific
     Default spacing for common component patterns
     ======================================================================== */
  --ds-spacing-component-gap: var(--ds-spacing-4);          /* 16px - Gap between items */
  --ds-spacing-component-gap-sm: var(--ds-spacing-2);       /* 8px - Small gap */
  --ds-spacing-component-gap-lg: var(--ds-spacing-6);       /* 24px - Large gap */

  --ds-spacing-component-padding: var(--ds-spacing-4);      /* 16px - Internal padding */
  --ds-spacing-component-padding-sm: var(--ds-spacing-2);   /* 8px - Small padding */
  --ds-spacing-component-padding-lg: var(--ds-spacing-6);   /* 24px - Large padding */

  --ds-spacing-component-margin: var(--ds-spacing-4);       /* 16px - External margin */
  --ds-spacing-component-margin-sm: var(--ds-spacing-2);    /* 8px - Small margin */
  --ds-spacing-component-margin-lg: var(--ds-spacing-8);    /* 32px - Large margin */

  /* ---------------------------------------------------------------------
   * Fluid space ramp (WO-ARC-05).
   *
   * `--ds-space-fluid-N` runs from `--ds-spacing-N` to the NEXT step the static
   * ramp defines -- so `--ds-space-fluid-12` ends at `--ds-spacing-14`, because
   * 13 does not exist. Interpolated in `cqi` between 360px and 1280px, hitting
   * both bounds exactly. Opt-in; nothing consumes these by default.
   * ------------------------------------------------------------------------ */
  --ds-space-fluid-1: clamp(0.25rem, 0.1522rem + 0.4348cqi, 0.5rem);
  --ds-space-fluid-2: clamp(0.5rem, 0.4022rem + 0.4348cqi, 0.75rem);
  --ds-space-fluid-3: clamp(0.75rem, 0.6522rem + 0.4348cqi, 1rem);
  --ds-space-fluid-4: clamp(1rem, 0.9022rem + 0.4348cqi, 1.25rem);
  --ds-space-fluid-6: clamp(1.5rem, 1.4022rem + 0.4348cqi, 1.75rem);
  --ds-space-fluid-8: clamp(2rem, 1.9022rem + 0.4348cqi, 2.25rem);
  --ds-space-fluid-10: clamp(2.5rem, 2.4022rem + 0.4348cqi, 2.75rem);
  --ds-space-fluid-12: clamp(3rem, 2.8043rem + 0.8696cqi, 3.5rem);
}

/**
 * Base Density Attribute Modes - Rottay Design System
 *
 * Container-scoped density. A data-density attribute on ANY container sets a
 * local --ds-density-local-factor, inherited by descendants, so a compact rail
 * can sit beside comfortable content without overwriting either the tenant's
 * structural --ds-density-scale or its appearance --ds-density-mode-factor.
 *
 * The values mirror DENSITY_MODE_FACTORS in the canonical TypeScript density
 * module. tests/density-scale-parity.test.ts pins this CSS projection to that
 * authority; useTokens and appearance compilation import the same resolver.
 *
 * IMPORTANT CASCADE LAW: custom-property var() references are resolved on the
 * element that declares the custom property. The spacing ramp is declared on
 * :root, therefore changing only --ds-density-local-factor on a descendant does
 * NOT recompute an inherited --ds-spacing-* value. The projection block below
 * deliberately redeclares the effective public spacing ramp on each density
 * boundary. Descendants inherit that locally computed ramp; a nested boundary
 * recomputes it again from the still-independent structural scale.
 *
 * Absent attribute => --ds-density-local-factor unset => identity factor 1.
 * The variable has no :root default so an annotated container always wins for
 * its own subtree without mutating brand/tenant structural density. Fixed-size
 * accessibility floors such as --ds-touch-target-min are intentionally absent
 * from this projection and therefore never shrink with density.
 */

/*
 * Root `data-density` is the observable semantic tenant posture. Only non-root
 * boundaries contribute a LOCAL multiplier; a root local factor would apply the
 * same global preference twice (mode factor × local factor), because :root
 * already composes both channels into --ds-density-effective-scale.
 *
 * The root posture therefore writes the SEMANTIC channel it represents rather
 * than a second multiplier — see the `:root` block after the local projection.
 */
[data-density='compact']:not(:root) {
  --ds-density-local-factor: 0.85;
}

[data-density='comfortable']:not(:root) {
  --ds-density-local-factor: 1;
}

[data-density='spacious']:not(:root) {
  --ds-density-local-factor: 1.15;
}

/*
 * Local effective spacing projection.
 *
 * `:where()` keeps selector specificity at zero: an explicit component or
 * application hook on the density boundary can still win through normal
 * cascade precedence.
 * Density-aware white-label overrides should author the
 * `--ds-density-spacing-*` hooks; the numeric scale continues to use the
 * structural --ds-density-scale channel.
 */
:where(
  [data-density='compact']:not(:root),
  [data-density='comfortable']:not(:root),
  [data-density='spacious']:not(:root)
) {
  --ds-density-global-effective-scale: clamp(
    0.5,
    calc(var(--ds-density-scale, 1) * var(--ds-density-mode-factor, 1)),
    3
  );
  --ds-density-effective-scale: clamp(
    0.5,
    calc(
      var(--ds-density-global-effective-scale, 1) *
      var(--ds-density-local-factor, 1)
    ),
    3
  );
  --ds-spacing-0: 0;
  --ds-spacing-1: calc(0.25rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-2: calc(0.5rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-3: calc(0.75rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-4: calc(1rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-5: calc(1.25rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-6: calc(1.5rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-7: calc(1.75rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-8: calc(2rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-9: calc(2.25rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-10: calc(2.5rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-11: calc(2.75rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-12: calc(3rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-14: calc(3.5rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-16: calc(4rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-20: calc(5rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-24: calc(6rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-28: calc(7rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-32: calc(8rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-36: calc(9rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-40: calc(10rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-44: calc(11rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-48: calc(12rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-52: calc(13rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-56: calc(14rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-60: calc(15rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-64: calc(16rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-72: calc(18rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-80: calc(20rem * var(--ds-density-effective-scale, 1));
  --ds-spacing-96: calc(24rem * var(--ds-density-effective-scale, 1));

  /* Effective aliases after themes/default.css has authored the public map. */
  --ds-spacing-xxxs: var(--ds-density-spacing-xxxs, var(--ds-spacing-1));
  --ds-spacing-xxs: var(--ds-density-spacing-xxs, var(--ds-spacing-2));
  --ds-spacing-xs: var(--ds-density-spacing-xs, var(--ds-spacing-1));
  --ds-spacing-sm: var(--ds-density-spacing-sm, var(--ds-spacing-2));
  --ds-spacing-md: var(--ds-density-spacing-md, var(--ds-spacing-4));
  --ds-spacing-lg: var(--ds-density-spacing-lg, var(--ds-spacing-6));
  --ds-spacing-xl: var(--ds-density-spacing-xl, var(--ds-spacing-8));
  --ds-spacing-2xl: var(--ds-density-spacing-2xl, var(--ds-spacing-12));
  --ds-spacing-3xl: var(--ds-density-spacing-3xl, var(--ds-spacing-16));
  --ds-spacing-4xl: var(--ds-density-spacing-4xl, var(--ds-spacing-20));
  --ds-spacing-5xl: var(--ds-density-spacing-5xl, var(--ds-spacing-24));

  --ds-spacing-gutter: var(--ds-density-spacing-gutter, var(--ds-spacing-4));
  --ds-spacing-gutter-sm: var(--ds-density-spacing-gutter-sm, var(--ds-spacing-2));
  --ds-spacing-gutter-md: var(--ds-density-spacing-gutter-md, var(--ds-spacing-6));
  --ds-spacing-gutter-lg: var(--ds-density-spacing-gutter-lg, var(--ds-spacing-8));
  --ds-spacing-gutter-xl: var(--ds-density-spacing-gutter-xl, var(--ds-spacing-12));
  --ds-spacing-section: var(--ds-density-spacing-section, var(--ds-spacing-16));
  --ds-spacing-section-sm: var(--ds-density-spacing-section-sm, var(--ds-spacing-8));
  --ds-spacing-section-lg: var(--ds-density-spacing-section-lg, var(--ds-spacing-24));
  --ds-spacing-container: var(--ds-density-spacing-container, var(--ds-spacing-6));
  --ds-spacing-container-sm: var(--ds-density-spacing-container-sm, var(--ds-spacing-4));
  --ds-spacing-container-lg: var(--ds-density-spacing-container-lg, var(--ds-spacing-12));

  --ds-spacing-component-gap: var(--ds-density-spacing-component-gap, var(--ds-spacing-4));
  --ds-spacing-component-gap-sm: var(--ds-density-spacing-component-gap-sm, var(--ds-spacing-2));
  --ds-spacing-component-gap-lg: var(--ds-density-spacing-component-gap-lg, var(--ds-spacing-6));
  --ds-spacing-component-padding: var(--ds-density-spacing-component-padding, var(--ds-spacing-4));
  --ds-spacing-component-padding-sm: var(--ds-density-spacing-component-padding-sm, var(--ds-spacing-2));
  --ds-spacing-component-padding-lg: var(--ds-density-spacing-component-padding-lg, var(--ds-spacing-6));
  --ds-spacing-component-margin: var(--ds-density-spacing-component-margin, var(--ds-spacing-4));
  --ds-spacing-component-margin-sm: var(--ds-density-spacing-component-margin-sm, var(--ds-spacing-2));
  --ds-spacing-component-margin-lg: var(--ds-density-spacing-component-margin-lg, var(--ds-spacing-8));
}

/*
 * Root posture projection.
 *
 * A root `data-density` boundary writes the SEMANTIC tenant channel
 * (--ds-density-mode-factor), never a second local multiplier. Three
 * consequences, all deliberate:
 *
 * 1. It paints. :root declares --ds-density-global-effective-scale, the
 *    effective scale and the whole public spacing ramp on this same element,
 *    and every one of those declarations references the mode factor from the
 *    same element — so redefining the factor here recomputes the root ramp
 *    without redeclaring a single spacing step.
 * 2. Double application is structurally impossible, not merely avoided. The DB
 *    Appearance compiler resolves the identical factor from the identical
 *    `appearance.general.density` field that feeds RootDensityProvider, and
 *    publishes it as an inline custom property on this same element. Two
 *    writers of ONE channel resolve by cascade to one value; they can never
 *    multiply. The old `:not(:root)` local-factor route would have produced
 *    scale × 0.85 × 0.85 whenever both were present.
 * 3. Nested boundaries stay relative. The local projection above recomputes
 *    the global channel from the inherited scale × mode factor, so a nested
 *    `comfortable` surface still inherits a compact tenant posture instead of
 *    erasing it.
 *
 * `comfortable` is the identity factor and is intentionally NOT declared here.
 * RootDensityProvider stamps `comfortable` as its default whenever no semantic
 * preference exists, so declaring `1` at this specificity would silently erase
 * a static BrandTheme posture compiled into `html[data-tenant='…']`. Declaring
 * nothing lets the lower-specificity authority stand, which is what "no
 * semantic adjustment" means.
 */
:root[data-density='compact'] {
  --ds-density-mode-factor: 0.85;
}

:root[data-density='spacious'] {
  --ds-density-mode-factor: 1.15;
}

/**
 * Base Typography Tokens - Rottay Design System
 *
 * Typography scale including font families, sizes, weights, line heights,
 * and letter spacing for consistent text styling across the system.
 */

:root {
  /* ========================================================================
     FONT FAMILIES
     Define the typeface stacks for different text purposes
     ======================================================================== */
  /* DS-A007: "Noto Sans Arabic" precedes the generic family so Arabic copy
     never falls through to a glyph-poor default; tenant-selected families
     still win because they prepend, never replace, this bounded chain. */
  --ds-font-family-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, "Noto Sans", "Noto Sans Arabic", sans-serif,
    "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
  --ds-font-family-heading: var(--ds-font-family-base);
  --ds-font-family-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Monaco,
    Consolas, "Liberation Mono", "Courier New", monospace;
  --ds-font-family-display: var(--ds-font-family-base);

  /* Rendering/craft channels. Variable fonts consume optical sizing and
     variation settings; static fonts ignore them without changing layout. */
  --ds-type-optical-sizing: auto;
  --ds-type-font-synthesis: none;
  --ds-type-font-variation-settings: normal;
  --ds-type-rendering: optimizeLegibility;

  /* Contrast is a role, not a fixed palette value. A tenant may remap these
     aliases while preserving one component tree and WCAG-gated semantics. */
  --ds-type-color-strong: var(--ds-color-text-primary);
  --ds-type-color-default: var(--ds-color-text-primary);
  --ds-type-color-muted: var(--ds-color-text-secondary);
  --ds-type-color-subtle: var(--ds-color-text-tertiary);
  --ds-type-color-inverse: var(--ds-color-text-inverse);

  /* Fine link/reveal craft. Kept quiet by default and disabled below when the
     user requests reduced motion. */
  --ds-type-decoration-thickness: 0.08em;
  --ds-type-decoration-offset: 0.18em;
  --ds-type-motion-duration: var(--ds-motion-reveal, var(--ds-duration-normal, 200ms));
  --ds-type-motion-distance: 0.35rem;
  --ds-type-motion-easing: var(--ds-motion-ease-enter, cubic-bezier(0.22, 1, 0.36, 1));

  /* ========================================================================
     FONT SIZES
     Type scale from small to 9xl for consistent text sizing.

     Each public --ds-font-size-* is a calc() over a private -base literal times
     var(--ds-type-scale, 1). When the tenant type-scale axis is absent the
     fallback 1 makes every step resolve to its -base literal byte-for-byte;
     when a tenant emits --ds-type-scale (0.92-1.08) the whole ramp scales at
     the definition site, so every var(--ds-font-size-*) consumer scales with no
     fleet sweep. The -base tokens are private (no consumer references them).
     NOTE: themes/default.css redefines most of these steps and wins the cascade
     (later in the rottay-tokens layer); it carries the same calc wrap over its
     own -base literals so the winning value scales identically. The steps only
     defined here (md, 7xl-9xl) win from this file.
     ======================================================================== */
  --ds-font-size-xs-base: 0.75rem; /* 12px */
  --ds-font-size-sm-base: 0.875rem; /* 14px */
  --ds-font-size-base-base: 1rem; /* 16px */
  --ds-font-size-md-base: 1rem; /* 16px - Alias for base */
  --ds-font-size-lg-base: 1.125rem; /* 18px */
  --ds-font-size-xl-base: 1.25rem; /* 20px */
  --ds-font-size-2xl-base: 1.5rem; /* 24px */
  --ds-font-size-3xl-base: 1.875rem; /* 30px */
  --ds-font-size-4xl-base: 2.25rem; /* 36px */
  --ds-font-size-5xl-base: 3rem; /* 48px */
  --ds-font-size-6xl-base: 3.75rem; /* 60px */
  --ds-font-size-7xl-base: 4.5rem; /* 72px */
  --ds-font-size-8xl-base: 6rem; /* 96px */
  --ds-font-size-9xl-base: 8rem; /* 128px */

  --ds-font-size-xs: calc(
    var(--ds-font-size-xs-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-sm: calc(
    var(--ds-font-size-sm-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-base: calc(
    var(--ds-font-size-base-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-md: calc(
    var(--ds-font-size-md-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-lg: calc(
    var(--ds-font-size-lg-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-xl: calc(
    var(--ds-font-size-xl-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-2xl: calc(
    var(--ds-font-size-2xl-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-3xl: calc(
    var(--ds-font-size-3xl-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-4xl: calc(
    var(--ds-font-size-4xl-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-5xl: calc(
    var(--ds-font-size-5xl-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-6xl: calc(
    var(--ds-font-size-6xl-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-7xl: calc(
    var(--ds-font-size-7xl-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-8xl: calc(
    var(--ds-font-size-8xl-base) * var(--ds-type-scale, 1)
  );
  --ds-font-size-9xl: calc(
    var(--ds-font-size-9xl-base) * var(--ds-type-scale, 1)
  );

  /* ========================================================================
     HEADING SIZES
     Predefined sizes for heading elements
     ======================================================================== */
  --ds-font-size-h1: var(--ds-font-size-4xl); /* 36px */
  --ds-font-size-h2: var(--ds-font-size-3xl); /* 30px */
  --ds-font-size-h3: var(--ds-font-size-2xl); /* 24px */
  --ds-font-size-h4: var(--ds-font-size-xl); /* 20px */
  --ds-font-size-h5: var(--ds-font-size-lg); /* 18px */
  --ds-font-size-h6: var(--ds-font-size-base); /* 16px */

  /* ========================================================================
     FONT WEIGHTS
     Weight scale for text emphasis
     ======================================================================== */
  --ds-font-weight-thin: 100;
  --ds-font-weight-extralight: 200;
  --ds-font-weight-light: 300;
  --ds-font-weight-normal: 400;
  --ds-font-weight-medium: 500;
  --ds-font-weight-semibold: 600;
  --ds-font-weight-bold: 700;
  --ds-font-weight-extrabold: 800;
  --ds-font-weight-black: 900;

  /* Semantic aliases */
  --ds-font-weight-body: var(--ds-font-weight-normal);
  --ds-font-weight-heading: var(--ds-font-weight-semibold);
  --ds-font-weight-display: var(--ds-font-weight-bold);

  /* ========================================================================
     LINE HEIGHTS
     Vertical spacing for text readability
     ======================================================================== */
  --ds-line-height-none: 1;
  --ds-line-height-tight: 1.25;
  --ds-line-height-snug: 1.375;
  --ds-line-height-normal: 1.5;
  --ds-line-height-relaxed: 1.625;
  --ds-line-height-loose: 2;

  /* Contextual line heights */
  --ds-line-height-body: 1.6; /* Relaxed for readability */
  --ds-line-height-heading: 1.2; /* Tight for premium headings */
  --ds-line-height-label: 1.4; /* Balanced for labels/metadata */
  --ds-line-height-display: var(--ds-line-height-none); /* 1 */

  /* ========================================================================
     LETTER SPACING
     Horizontal spacing between characters
     ======================================================================== */
  --ds-letter-spacing-tighter: -0.05em;
  --ds-letter-spacing-tight: -0.025em;
  --ds-letter-spacing-snug: -0.015em;
  --ds-letter-spacing-subtle: -0.01em;
  --ds-letter-spacing-normal: 0;
  --ds-letter-spacing-subtle-wide: 0.01em;
  --ds-letter-spacing-wide: 0.025em;
  --ds-letter-spacing-wider: 0.05em;
  --ds-letter-spacing-widest: 0.1em;

  /* Heading-specific tracking: larger sizes get tighter spacing
     for the editorial, premium feel (Linear / Vercel / Stripe). */
  --ds-letter-spacing-h1: -0.025em;
  --ds-letter-spacing-h2: -0.02em;
  --ds-letter-spacing-h3: -0.015em;
  --ds-letter-spacing-h4: -0.01em;
  --ds-letter-spacing-h5: 0;
  --ds-letter-spacing-h6: 0;

  /* ========================================================================
     TEXT TRANSFORM
     Common text transformations
     ======================================================================== */
  --ds-text-transform-none: none;
  --ds-text-transform-uppercase: uppercase;
  --ds-text-transform-lowercase: lowercase;
  --ds-text-transform-capitalize: capitalize;

  /* ========================================================================
     SEMANTIC TYPOGRAPHY ROLES
     Product components consume these roles; BrandTheme can override every
     facet without changing component anatomy or application markup.
     ======================================================================== */
  --ds-type-display-font-family: var(
    --ds-font-family-display,
    var(--ds-font-family-heading)
  );
  --ds-type-display-font-size: var(--ds-font-size-fluid-5xl, calc(3rem * var(--ds-type-scale, 1)));
  --ds-type-display-font-weight: 700;
  --ds-type-display-line-height: 1.1;
  --ds-type-display-letter-spacing: var(--ds-letter-spacing-display, -0.03em);
  --ds-type-display-text-transform: none;
  --ds-type-display-font-variant-numeric: normal;

  --ds-type-page-title-font-family: var(--ds-font-family-heading);
  --ds-type-page-title-font-size: var(--ds-font-size-fluid-3xl, calc(1.875rem * var(--ds-type-scale, 1)));
  --ds-type-page-title-font-weight: 700;
  --ds-type-page-title-line-height: 1.16;
  --ds-type-page-title-letter-spacing: var(
    --ds-letter-spacing-heading,
    -0.02em
  );
  --ds-type-page-title-text-transform: none;
  --ds-type-page-title-font-variant-numeric: normal;

  --ds-type-section-title-font-family: var(--ds-font-family-heading);
  --ds-type-section-title-font-size: var(--ds-font-size-fluid-xl, calc(1.25rem * var(--ds-type-scale, 1)));
  --ds-type-section-title-font-weight: 600;
  --ds-type-section-title-line-height: 1.3;
  --ds-type-section-title-letter-spacing: var(
    --ds-letter-spacing-heading,
    -0.01em
  );
  --ds-type-section-title-text-transform: none;
  --ds-type-section-title-font-variant-numeric: normal;

  --ds-type-body-font-family: var(--ds-font-family-base);
  --ds-type-body-font-size: calc(0.875rem * var(--ds-type-scale, 1));
  --ds-type-body-font-weight: 400;
  --ds-type-body-line-height: var(--ds-line-height-body, 1.6);
  --ds-type-body-letter-spacing: var(--ds-letter-spacing-body, 0);
  --ds-type-body-text-transform: none;
  --ds-type-body-font-variant-numeric: normal;

  --ds-type-supporting-font-family: var(--ds-font-family-base);
  --ds-type-supporting-font-size: calc(0.8125rem * var(--ds-type-scale, 1));
  --ds-type-supporting-font-weight: 400;
  --ds-type-supporting-line-height: 1.5;
  --ds-type-supporting-letter-spacing: var(--ds-letter-spacing-body, 0);
  --ds-type-supporting-text-transform: none;
  --ds-type-supporting-font-variant-numeric: normal;

  --ds-type-label-font-family: var(--ds-font-family-base);
  --ds-type-label-font-size: calc(0.75rem * var(--ds-type-scale, 1));
  --ds-type-label-font-weight: 600;
  --ds-type-label-line-height: 1.3;
  --ds-type-label-letter-spacing: 0.04em;
  --ds-type-label-text-transform: none;
  --ds-type-label-font-variant-numeric: normal;

  --ds-type-caption-font-family: var(--ds-font-family-base);
  --ds-type-caption-font-size: calc(0.6875rem * var(--ds-type-scale, 1));
  --ds-type-caption-font-weight: 400;
  --ds-type-caption-line-height: 1.35;
  --ds-type-caption-letter-spacing: 0.01em;
  --ds-type-caption-text-transform: none;
  --ds-type-caption-font-variant-numeric: normal;

  --ds-type-code-font-family: var(--ds-font-family-mono);
  --ds-type-code-font-size: calc(0.8125rem * var(--ds-type-scale, 1));
  --ds-type-code-font-weight: 400;
  --ds-type-code-line-height: 1.5;
  --ds-type-code-letter-spacing: var(--ds-letter-spacing-mono, 0);
  --ds-type-code-text-transform: none;
  --ds-type-code-font-variant-numeric: tabular-nums;

  --ds-type-numeric-font-family: var(--ds-font-family-heading);
  --ds-type-numeric-font-size: calc(1rem * var(--ds-type-scale, 1));
  --ds-type-numeric-font-weight: 600;
  --ds-type-numeric-line-height: 1.2;
  --ds-type-numeric-letter-spacing: -0.01em;
  --ds-type-numeric-text-transform: none;
  --ds-type-numeric-font-variant-numeric: tabular-nums lining-nums;

  /* Dynamic shorthand aliases. They reference the facets instead of copying
     values so a DB tenant can retune one role property without leaving a
     stale composite token behind. Components may consume either the complete
     shorthand or the individual facets when they also need transform/tracking. */
  --ds-type-display: var(--ds-type-display-font-weight)
    var(--ds-type-display-font-size) / var(--ds-type-display-line-height)
    var(--ds-type-display-font-family);
  --ds-type-page-title: var(--ds-type-page-title-font-weight)
    var(--ds-type-page-title-font-size) / var(--ds-type-page-title-line-height)
    var(--ds-type-page-title-font-family);
  --ds-type-section-title: var(--ds-type-section-title-font-weight)
    var(--ds-type-section-title-font-size) / var(--ds-type-section-title-line-height)
    var(--ds-type-section-title-font-family);
  --ds-type-body: var(--ds-type-body-font-weight) var(--ds-type-body-font-size) /
    var(--ds-type-body-line-height) var(--ds-type-body-font-family);
  --ds-type-supporting: var(--ds-type-supporting-font-weight)
    var(--ds-type-supporting-font-size) / var(--ds-type-supporting-line-height)
    var(--ds-type-supporting-font-family);
  --ds-type-label: var(--ds-type-label-font-weight)
    var(--ds-type-label-font-size) / var(--ds-type-label-line-height)
    var(--ds-type-label-font-family);
  --ds-type-caption: var(--ds-type-caption-font-weight)
    var(--ds-type-caption-font-size) / var(--ds-type-caption-line-height)
    var(--ds-type-caption-font-family);
  --ds-type-code: var(--ds-type-code-font-weight) var(--ds-type-code-font-size) /
    var(--ds-type-code-line-height) var(--ds-type-code-font-family);
  --ds-type-numeric: var(--ds-type-numeric-font-weight)
    var(--ds-type-numeric-font-size) / var(--ds-type-numeric-line-height)
    var(--ds-type-numeric-font-family);

  /* ========================================================================
     TEXT DECORATION
     Common text decorations
     ======================================================================== */
  --ds-text-decoration-none: none;
  --ds-text-decoration-underline: underline;
  --ds-text-decoration-line-through: line-through;

  /* ========================================================================
     COMPOSITE TEXT STYLES
     Pre-composed text styles for common use cases
     ======================================================================== */

  /* Display styles */
  --ds-text-display-1-size: var(--ds-font-size-6xl);
  --ds-text-display-1-weight: var(--ds-font-weight-bold);
  --ds-text-display-1-line-height: var(--ds-line-height-none);
  --ds-text-display-1-letter-spacing: var(--ds-letter-spacing-tight);

  --ds-text-display-2-size: var(--ds-font-size-5xl);
  --ds-text-display-2-weight: var(--ds-font-weight-bold);
  --ds-text-display-2-line-height: var(--ds-line-height-none);
  --ds-text-display-2-letter-spacing: var(--ds-letter-spacing-tight);

  /* Heading styles - Premium typography with tighter tracking at larger sizes */
  --ds-text-heading-1-size: var(--ds-font-size-h1);
  --ds-text-heading-1-weight: var(--ds-font-weight-bold);
  --ds-text-heading-1-line-height: 1.1;
  --ds-text-heading-1-letter-spacing: var(--ds-letter-spacing-h1);

  --ds-text-heading-2-size: var(--ds-font-size-h2);
  --ds-text-heading-2-weight: var(--ds-font-weight-bold);
  --ds-text-heading-2-line-height: 1.15;
  --ds-text-heading-2-letter-spacing: var(--ds-letter-spacing-h2);

  --ds-text-heading-3-size: var(--ds-font-size-h3);
  --ds-text-heading-3-weight: var(--ds-font-weight-semibold);
  --ds-text-heading-3-line-height: 1.2;
  --ds-text-heading-3-letter-spacing: var(--ds-letter-spacing-h3);

  --ds-text-heading-4-size: var(--ds-font-size-h4);
  --ds-text-heading-4-weight: var(--ds-font-weight-semibold);
  --ds-text-heading-4-line-height: 1.25;
  --ds-text-heading-4-letter-spacing: var(--ds-letter-spacing-h4);

  --ds-text-heading-5-size: var(--ds-font-size-h5);
  --ds-text-heading-5-weight: var(--ds-font-weight-semibold);
  --ds-text-heading-5-line-height: 1.3;
  --ds-text-heading-5-letter-spacing: var(--ds-letter-spacing-h5);

  --ds-text-heading-6-size: var(--ds-font-size-h6);
  --ds-text-heading-6-weight: var(--ds-font-weight-semibold);
  --ds-text-heading-6-line-height: 1.4;
  --ds-text-heading-6-letter-spacing: var(--ds-letter-spacing-h6);

  /* Body styles */
  --ds-text-body-lg-size: var(--ds-font-size-lg);
  --ds-text-body-lg-weight: var(--ds-font-weight-normal);
  --ds-text-body-lg-line-height: var(--ds-line-height-normal);

  --ds-text-body-md-size: var(--ds-font-size-base);
  --ds-text-body-md-weight: var(--ds-font-weight-normal);
  --ds-text-body-md-line-height: var(--ds-line-height-normal);

  --ds-text-body-sm-size: var(--ds-font-size-sm);
  --ds-text-body-sm-weight: var(--ds-font-weight-normal);
  --ds-text-body-sm-line-height: var(--ds-line-height-normal);

  --ds-text-body-xs-size: var(--ds-font-size-xs);
  --ds-text-body-xs-weight: var(--ds-font-weight-normal);
  --ds-text-body-xs-line-height: var(--ds-line-height-normal);

  /* Caption styles */
  --ds-text-caption-size: var(--ds-font-size-sm);
  --ds-text-caption-weight: var(--ds-font-weight-normal);
  --ds-text-caption-line-height: var(--ds-line-height-snug);
  --ds-text-caption-color: var(--ds-color-neutral-600);

  /* Label styles */
  --ds-text-label-size: var(--ds-font-size-sm);
  --ds-text-label-weight: var(--ds-font-weight-medium);
  --ds-text-label-line-height: var(--ds-line-height-normal);
  --ds-text-label-letter-spacing: var(--ds-letter-spacing-wide);

  /* Code/Mono styles */
  --ds-text-code-size: var(--ds-font-size-sm);
  --ds-text-code-weight: var(--ds-font-weight-normal);
  --ds-text-code-line-height: var(--ds-line-height-normal);
  --ds-text-code-family: var(--ds-font-family-mono);

  /* ========================================================================
     MICRO-TYPOGRAPHY (WO-CRA-01)
     Numeric alignment, line wrapping, and optical sizing. The utility classes
     below and the TS mirror (foundation/tokens/ts/foundation/base/typography/index.ts) consume these so no
     consumer re-invents the values inline.
     ======================================================================== */
  --ds-numeric-tabular: tabular-nums;
  --ds-numeric-proportional: proportional-nums;
  --ds-font-feature-tabular: "tnum" 1, "lnum" 1;
  --ds-text-wrap-balance: balance;
  --ds-text-wrap-pretty: pretty;
  --ds-hyphens-auto: auto;

  /* ---------------------------------------------------------------------
   * Fluid type ramp (WO-ARC-05).
   *
   * Each fluid step is bounded by two ADJACENT static steps above -- no new
   * magnitudes enter the system, only the path between two that already exist.
   * The ramp interpolates linearly between 360px and 1280px, the same widths
   * the WO-ENG-12 capture law photographs, and hits each bound exactly there.
   *
   * The interpolation unit is `cqi`, not `vw`: a design system renders the same
   * component at rail width, half width and full width inside one viewport, and
   * a viewport unit cannot tell those apart. Where no ancestor declares
   * `container-type`, `cqi` resolves against the small viewport, which is the
   * behaviour a `vw` ramp would have had.
   *
   * Opt-in. A skin or surface reaches for one where a static step is cramped at
   * 360px or oversized at 1280px, and only where a `container-type` ancestor
   * exists to resolve `cqi` against -- currently the page-shell root
   * (`runtime/engines/{modern,rustic}/skin/page-shell.css`, container name
   * `ds-page`), consumed by the page-shell title
   * (`ui/patterns/shell/page-shell/engines/{modern,rustic}/index.tsx`, `--ds-font-size-fluid-2xl`).
   * Reaching for one of these outside a `container-type` ancestor silently
   * resolves against the small viewport instead -- verify the ancestor chain
   * before adopting a new consumer.
   * ------------------------------------------------------------------------ */
  --ds-font-size-fluid-sm: clamp(0.75rem, 0.7011rem + 0.2174cqi, 0.875rem);
  --ds-font-size-fluid-base: clamp(0.875rem, 0.8261rem + 0.2174cqi, 1rem);
  --ds-font-size-fluid-lg: clamp(1rem, 0.9511rem + 0.2174cqi, 1.125rem);
  --ds-font-size-fluid-xl: clamp(1.125rem, 1.0761rem + 0.2174cqi, 1.25rem);
  --ds-font-size-fluid-2xl: clamp(1.25rem, 1.1522rem + 0.4348cqi, 1.5rem);
  --ds-font-size-fluid-3xl: clamp(1.5rem, 1.3533rem + 0.6522cqi, 1.875rem);
  --ds-font-size-fluid-4xl: clamp(1.875rem, 1.7283rem + 0.6522cqi, 2.25rem);
  --ds-font-size-fluid-5xl: clamp(2.25rem, 1.9565rem + 1.3043cqi, 3rem);
}

/*
 * A nested DS surface is an explicit typography boundary. Hosts such as docs,
 * portals, embedded widgets, and micro-frontends may own a different body
 * font; once a consumer stamps `data-ds-root`, tenant typography must win by
 * declaration instead of depending on host inheritance. Keep this selector
 * deliberately low-specificity so a product can still opt into a more local
 * semantic typography role through a DS component contract.
 */
:where([data-ds-root]) {
  color: var(--ds-color-text-primary);
  font-family: var(--ds-font-family-base);
  text-rendering: optimizeLegibility;
}

/* ==========================================================================
   MICRO-TYPOGRAPHY UTILITIES (WO-CRA-01)
   Opt-in classes so data surfaces align digits and prose wraps cleanly. Every
   property degrades gracefully — it is ignored, never broken, where the engine
   or font lacks support.
   ========================================================================== */

/* Optical sizing: tenant variable/optical fonts render at their designed
   optical size. Harmless on fonts without an optical axis. :where() keeps the
   specificity at 0 so apps and tenants can still override. */
:where(html) {
  font-optical-sizing: auto;
}

/* Tabular (fixed-advance) figures so numbers align column-to-column in tables
   and metric tiles instead of jittering with proportional digits. */
.ds-nums-tabular {
  font-variant-numeric: tabular-nums;
  font-feature-settings: var(--ds-font-feature-tabular);
}

/* Balanced multi-line headings — even line lengths, no lonely last word. */
.ds-text-balance {
  text-wrap: balance;
}

/* Prettier body wrapping — avoids a single-word final line (orphan). */
.ds-text-pretty {
  text-wrap: pretty;
}

/* Automatic hyphenation for narrow measures (honors the element's lang). */
.ds-hyphenate {
  hyphens: auto;
}

/* Shared premium craft across every engine. No brand selector appears here:
   BrandTheme controls the variables while markup and interaction stay fixed. */
:where(.rottay-typography) {
  font-optical-sizing: var(--ds-type-optical-sizing, auto);
  font-synthesis: var(--ds-type-font-synthesis, none);
  font-variation-settings: var(--ds-type-font-variation-settings, normal);
  text-rendering: var(--ds-type-rendering, optimizeLegibility);
  text-decoration-thickness: var(--ds-type-decoration-thickness, 0.08em);
  text-underline-offset: var(--ds-type-decoration-offset, 0.18em);
  transition:
    color var(--ds-type-motion-duration, 180ms)
      var(--ds-type-motion-easing, ease),
    text-decoration-color var(--ds-type-motion-duration, 180ms)
      var(--ds-type-motion-easing, ease),
    opacity var(--ds-type-motion-duration, 180ms)
      var(--ds-type-motion-easing, ease);
}

:where(.rottay-typography[data-motion="enter"]) {
  animation: ds-typography-enter var(--ds-type-motion-duration, 180ms)
    var(--ds-type-motion-easing, ease) both;
}

@keyframes ds-typography-enter {
  from {
    opacity: 0;
    transform: translateY(var(--ds-type-motion-distance, 0.35rem));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  :where(.rottay-typography) {
    animation: none !important;
    transition-duration: 0.01ms !important;
  }
}

/**
 * Base Shadow Tokens - Rottay Design System
 *
 * Shadow scale for depth and elevation in the UI.
 * Includes box shadows and drop shadows for consistent layering.
 */

:root {
  /* ========================================================================
     BOX SHADOWS - aliases of the --ds-elevation-0..5 depth scale
     --ds-elevation-* is defined in themes/default.css (co-loaded with this file
     in every entrypoint). classic/rustic components and the brand compiler
     consume these --ds-shadow-* names.
     ======================================================================== */
  --ds-shadow-none: var(--ds-elevation-0);
  --ds-shadow-xs: var(--ds-elevation-1);
  --ds-shadow-sm: var(--ds-elevation-1);
  --ds-shadow-md: var(--ds-elevation-2);
  --ds-shadow-lg: var(--ds-elevation-3);
  --ds-shadow-xl: var(--ds-elevation-4);
  --ds-shadow-2xl: var(--ds-elevation-5);
  --ds-shadow-3xl: var(--ds-elevation-5), 0 48px 96px rgba(0, 0, 0, 0.1);

  /* Inner shadow for inset effects */
  --ds-shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.05);

  /* ========================================================================
     COLORED SHADOWS - Brand/Semantic Shadows
     Shadows with color tints for special emphasis
     ======================================================================== */

  /* Primary shadows */
  --ds-shadow-primary-sm: 0 1px 3px 0 rgba(0, 102, 204, 0.12),
                       0 1px 2px -1px rgba(0, 102, 204, 0.12);

  --ds-shadow-primary-md: 0 4px 6px -1px rgba(0, 102, 204, 0.12),
                       0 2px 4px -2px rgba(0, 102, 204, 0.12);

  --ds-shadow-primary-lg: 0 10px 15px -3px rgba(0, 102, 204, 0.15),
                       0 4px 6px -4px rgba(0, 102, 204, 0.15);

  /* Secondary shadows */
  --ds-shadow-secondary-sm: 0 1px 3px 0 rgba(107, 107, 212, 0.12),
                         0 1px 2px -1px rgba(107, 107, 212, 0.12);

  --ds-shadow-secondary-md: 0 4px 6px -1px rgba(107, 107, 212, 0.12),
                         0 2px 4px -2px rgba(107, 107, 212, 0.12);

  /* Success shadows */
  --ds-shadow-success-sm: 0 1px 3px 0 rgba(34, 197, 94, 0.12),
                       0 1px 2px -1px rgba(34, 197, 94, 0.12);

  --ds-shadow-success-md: 0 4px 6px -1px rgba(34, 197, 94, 0.12),
                       0 2px 4px -2px rgba(34, 197, 94, 0.12);

  /* Warning shadows */
  --ds-shadow-warning-sm: 0 1px 3px 0 rgba(245, 158, 11, 0.12),
                       0 1px 2px -1px rgba(245, 158, 11, 0.12);

  --ds-shadow-warning-md: 0 4px 6px -1px rgba(245, 158, 11, 0.12),
                       0 2px 4px -2px rgba(245, 158, 11, 0.12);

  /* Error shadows */
  --ds-shadow-error-sm: 0 1px 3px 0 rgba(239, 68, 68, 0.12),
                     0 1px 2px -1px rgba(239, 68, 68, 0.12);

  --ds-shadow-error-md: 0 4px 6px -1px rgba(239, 68, 68, 0.12),
                     0 2px 4px -2px rgba(239, 68, 68, 0.12);

  /* ========================================================================
     DROP SHADOWS - CSS Filter Shadows
     Used with the filter property for images and elements
     ======================================================================== */
  --ds-drop-shadow-none: drop-shadow(0 0 0 rgba(0, 0, 0, 0));
  --ds-drop-shadow-xs: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.05));
  --ds-drop-shadow-sm: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.1));
  --ds-drop-shadow-md: drop-shadow(0 4px 3px rgba(0, 0, 0, 0.07))
                    drop-shadow(0 2px 2px rgba(0, 0, 0, 0.06));
  --ds-drop-shadow-lg: drop-shadow(0 10px 8px rgba(0, 0, 0, 0.04))
                    drop-shadow(0 4px 3px rgba(0, 0, 0, 0.1));
  --ds-drop-shadow-xl: drop-shadow(0 20px 13px rgba(0, 0, 0, 0.03))
                    drop-shadow(0 8px 5px rgba(0, 0, 0, 0.08));
  --ds-drop-shadow-2xl: drop-shadow(0 25px 25px rgba(0, 0, 0, 0.15));

  /* ========================================================================
     COMPONENT SHADOWS - Specific Component Elevations
     Predefined shadows for common component states
     ======================================================================== */

  /* Card shadows */
  --ds-shadow-card-rest: var(--ds-shadow-sm);
  --ds-shadow-card-hover: var(--ds-shadow-md);
  --ds-shadow-card-active: var(--ds-shadow-xs);

  /* Button shadows */
  --ds-shadow-button-rest: var(--ds-shadow-xs);
  --ds-shadow-button-hover: var(--ds-shadow-sm);
  --ds-shadow-button-active: var(--ds-shadow-none);

  /* Modal/Dialog shadows */
  --ds-shadow-modal: var(--ds-shadow-2xl);
  --ds-shadow-dialog: var(--ds-shadow-xl);

  /* Dropdown/Menu shadows */
  --ds-shadow-dropdown: var(--ds-shadow-lg);
  --ds-shadow-menu: var(--ds-shadow-lg);

  /* Popover/Tooltip shadows */
  --ds-shadow-popover: var(--ds-shadow-md);
  --ds-shadow-tooltip: var(--ds-shadow-sm);

  /* Drawer shadows */
  --ds-shadow-drawer: var(--ds-shadow-xl);

  /* Navigation shadows */
  --ds-shadow-navbar: var(--ds-shadow-sm);
  --ds-shadow-sidebar: var(--ds-shadow-md);

  /* Input shadows */
  --ds-shadow-input-rest: var(--ds-shadow-none);
  --ds-shadow-input-focus: 0 0 0 3px var(--ds-color-alpha-primary-10, rgba(0, 102, 204, 0.1));
  --ds-shadow-input-error: 0 0 0 3px var(--ds-color-alpha-error-10, rgba(239, 68, 68, 0.1));

  /* ========================================================================
     FOCUS RING SHADOWS
     Accessibility-focused outlines for keyboard navigation
     ======================================================================== */
  --ds-shadow-focus-ring: 0 0 0 3px var(--ds-color-alpha-primary-20, rgba(0, 102, 204, 0.2));
  --ds-shadow-focus-ring-error: 0 0 0 3px var(--ds-color-alpha-error-20, rgba(239, 68, 68, 0.2));
  --ds-shadow-focus-ring-success: 0 0 0 3px var(--ds-color-alpha-success-20, rgba(34, 197, 94, 0.2));
  --ds-shadow-focus-ring-warning: 0 0 0 3px var(--ds-color-alpha-warning-20, rgba(245, 158, 11, 0.2));
}

/**
 * Base Border Tokens - Rottay Design System
 *
 * Border widths, radii, and styles for consistent component boundaries.
 */

:root {
  /* ========================================================================
     BORDER WIDTHS
     Standard border widths for component boundaries
     ======================================================================== */
  --ds-border-width-0: 0;
  --ds-border-width-1: 1px;
  --ds-border-width-2: 2px;
  --ds-border-width-4: 4px;
  --ds-border-width-8: 8px;

  /* Semantic aliases */
  --ds-border-width-none: var(--ds-border-width-0);
  --ds-border-width-thin: var(--ds-border-width-1);
  --ds-border-width-default: var(--ds-border-width-1);
  --ds-border-width-medium: var(--ds-border-width-2);
  --ds-border-width-thick: var(--ds-border-width-4);

  /* ========================================================================
     BORDER RADIUS - Rounding Scale
     Consistent corner rounding for components
     ======================================================================== */

  /* Component-specific radius */
  --ds-radius-button: var(--ds-radius-md);
  --ds-radius-input: var(--ds-radius-md);
  --ds-radius-card: var(--ds-radius-lg);
  --ds-radius-modal: var(--ds-radius-xl);
  --ds-radius-badge: var(--ds-radius-full);
  --ds-radius-avatar: var(--ds-radius-full);

  /* ========================================================================
     BORDER STYLES
     Line styles for borders
     ======================================================================== */
  --ds-border-style-none: none;
  --ds-border-style-solid: solid;
  --ds-border-style-dashed: dashed;
  --ds-border-style-dotted: dotted;
  --ds-border-style-double: double;

  /* ========================================================================
     BORDER COLORS
     Contextual border colors based on the color palette
     ======================================================================== */

  /* Default borders */
  --ds-border-color-default: var(--ds-color-neutral-200);
  --ds-border-color-muted: var(--ds-color-neutral-100);
  --ds-border-color-strong: var(--ds-color-neutral-300);

  /* Interactive borders */
  --ds-border-color-hover: var(--ds-color-neutral-300);
  --ds-border-color-focus: var(--ds-color-primary-500);
  --ds-border-color-active: var(--ds-color-primary-600);

  /* Semantic borders */
  --ds-border-color-primary: var(--ds-color-primary-500);
  --ds-border-color-secondary: var(--ds-color-secondary-500);
  --ds-border-color-success: var(--ds-color-success-500);
  --ds-border-color-warning: var(--ds-color-warning-500);
  --ds-border-color-error: var(--ds-color-error-500);
  --ds-border-color-info: var(--ds-color-info-500);

  /* Transparent borders for spacing */
  --ds-border-color-transparent: transparent;

  /* ========================================================================
     DIVIDER STYLES
     Styles for visual separators
     ======================================================================== */
  --ds-divider-width: var(--ds-border-width-1);
  --ds-divider-color: var(--ds-border-color-default);
  --ds-divider-style: var(--ds-border-style-solid);

  /* Divider with spacing */
  --ds-divider-spacing-sm: var(--ds-spacing-2);   /* 8px */
  --ds-divider-spacing-md: var(--ds-spacing-4);   /* 16px */
  --ds-divider-spacing-lg: var(--ds-spacing-6);   /* 24px */

  /* ========================================================================
     OUTLINE STYLES
     Styles for focus outlines and accessibility
     ======================================================================== */
  --ds-outline-width: 2px;
  --ds-outline-offset: 2px;
  --ds-outline-style: solid;
  --ds-outline-color-default: var(--ds-color-primary-500);
  --ds-outline-color-error: var(--ds-color-error-500);

  /* ========================================================================
     COMPOSITE BORDERS
     Pre-composed border combinations for common use cases
     ======================================================================== */

  /* Default component borders */
  --ds-border-default: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-default);
  --ds-border-muted: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-muted);
  --ds-border-strong: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-strong);

  /* Interactive borders */
  --ds-border-hover: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-hover);
  --ds-border-focus: var(--ds-border-width-2) var(--ds-border-style-solid) var(--ds-border-color-focus);

  /* Semantic borders */
  --ds-border-primary: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-primary);
  --ds-border-secondary: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-secondary);
  --ds-border-success: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-success);
  --ds-border-warning: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-warning);
  --ds-border-error: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-error);
  --ds-border-info: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-info);

  /* Dashed borders */
  --ds-border-dashed: var(--ds-border-width-1) var(--ds-border-style-dashed) var(--ds-border-color-default);
  --ds-border-dashed-muted: var(--ds-border-width-1) var(--ds-border-style-dashed) var(--ds-border-color-muted);

  /* Transparent placeholder borders (for maintaining layout) */
  --ds-border-transparent: var(--ds-border-width-1) var(--ds-border-style-solid) transparent;
}

/**
 * Base Z-Index Tokens - Rottay Design System
 *
 * Z-index layering system for consistent element stacking.
 * Uses a scale that leaves room for component-specific adjustments.
 */

:root {
  /* ========================================================================
     Z-INDEX SCALE - Layering System
     Organized from bottom to top of the stack
     ======================================================================== */

  /* Base layer - Normal document flow */
  --ds-z-index-base: 0;

  /* Dropdown layer - Select menus, autocomplete, etc */
  --ds-z-index-dropdown: 1000;

  /* Sticky elements - Sticky headers, footers */
  --ds-z-index-sticky: 1100;

  /* Fixed elements - Fixed navigation, banners */
  --ds-z-index-fixed: 1200;

  /* Overlay backdrop - Modal/drawer backdrops */
  --ds-z-index-overlay: 1300;

  /* Drawer - Side panels */
  --ds-z-index-drawer: 1400;

  /* Modal/Dialog - Modal windows */
  --ds-z-index-modal: 1500;

  /* Popover - Context menus, popovers */
  --ds-z-index-popover: 1600;

  /* Tooltip - Tooltips and hints */
  --ds-z-index-tooltip: 1700;

  /* Notification/Toast - Toast messages, notifications */
  --ds-z-index-notification: 1800;

  /* Maximum - Highest priority elements */
  --ds-z-index-max: 9999;

  /* ========================================================================
     COMPONENT-SPECIFIC Z-INDEX
     Specific layers for common component scenarios
     ======================================================================== */

  /* Navigation */
  --ds-z-index-navbar: var(--ds-z-index-fixed);
  --ds-z-index-sidebar: var(--ds-z-index-drawer);
  --ds-z-index-navbar-dropdown: calc(var(--ds-z-index-navbar) + 10);

  /* Menus */
  --ds-z-index-menu: var(--ds-z-index-dropdown);
  --ds-z-index-submenu: calc(var(--ds-z-index-menu) + 10);
  --ds-z-index-context-menu: var(--ds-z-index-popover);

  /* Overlays */
  --ds-z-index-modal-backdrop: var(--ds-z-index-overlay);
  --ds-z-index-modal-content: var(--ds-z-index-modal);
  --ds-z-index-drawer-backdrop: var(--ds-z-index-overlay);
  --ds-z-index-drawer-content: var(--ds-z-index-drawer);

  /* Feedback */
  --ds-z-index-toast: var(--ds-z-index-notification);
  --ds-z-index-alert: calc(var(--ds-z-index-base) + 1);
  --ds-z-index-banner: var(--ds-z-index-sticky);

  /* Forms */
  --ds-z-index-select-dropdown: var(--ds-z-index-dropdown);
  --ds-z-index-datepicker: var(--ds-z-index-dropdown);
  --ds-z-index-autocomplete: var(--ds-z-index-dropdown);

  /* Utility */
  --ds-z-index-loading-overlay: calc(var(--ds-z-index-modal) + 100);
  --ds-z-index-skip-link: var(--ds-z-index-max);

  /* ========================================================================
     RELATIVE Z-INDEX
     For elements that need layering within their stacking context
     ======================================================================== */
  --ds-z-index-relative-below: -1;
  --ds-z-index-relative-base: 0;
  --ds-z-index-relative-above: 1;
  --ds-z-index-relative-top: 10;
}


}
