  --ds-color-neutral-50: #0b1220;
  --ds-color-neutral-100: #111827;
  --ds-color-neutral-200: #1f2937;
  --ds-color-neutral-300: #334155;
  --ds-color-neutral-400: #475569;
  --ds-color-neutral-500: #64748b;
  --ds-color-neutral-600: #94a3b8;
