  /* Modal content */
  --transition-modal-content: opacity var(--duration-normal)
      var(--easing-standard),
    transform var(--duration-normal) var(--easing-emphasized);

  /* Dropdown */
  --transition-dropdown: opacity var(--duration-fast) var(--easing-decelerated),
    transform var(--duration-fast) var(--easing-decelerated);

  /* Tooltip */
  --transition-tooltip: opacity var(--duration-faster) var(--easing-standard);

  /* Drawer */
  --transition-drawer: transform var(--duration-normal) var(--easing-emphasized);

  /* Toast/Notification */
  --transition-toast: opacity var(--duration-normal) var(--easing-standard),
    transform var(--duration-normal) var(--easing-emphasized);

  /* Accordion */
  --transition-accordion: height var(--duration-normal) var(--easing-emphasized),
    opacity var(--duration-fast) var(--easing-standard);

  /* Tab */
  --transition-tab: color var(--duration-fast) var(--easing-standard),
    border-color var(--duration-fast) var(--easing-standard);

  /* Avatar */
  --transition-avatar: transform var(--duration-fast) var(--easing-standard),
    box-shadow var(--duration-fast) var(--easing-standard);

  /* Switch/Toggle */
  --transition-switch: transform var(--duration-fast) var(--easing-standard),
    background-color var(--duration-fast) var(--easing-standard);

  /* Progress bar */
  --transition-progress: width var(--duration-slower) var(--easing-standard);

  /* Skeleton loader */
  --transition-skeleton: opacity var(--duration-slow) var(--easing-standard);

  /* ========================================================================
     DELAY VALUES
     Stagger delays for sequential animations
     ======================================================================== */
  --delay-none: 0s;
  --delay-xs: 0.05s; /* 50ms */
  --delay-sm: 0.1s; /* 100ms */
  --delay-md: 0.15s; /* 150ms */
  --delay-lg: 0.2s; /* 200ms */
  --delay-xl: 0.3s; /* 300ms */

  /* Stagger increments for lists */
  --delay-stagger-increment: 0.05s; /* 50ms between items */
}

/* ========================================================================
   REDUCED MOTION
   Respect user's motion preferences
   ======================================================================== */
@media (prefers-reduced-motion: reduce) {
  :root {
    /* Minimal durations */
    --duration-instant: 0s;
    --duration-fastest: 0.01s;
    --duration-faster: 0.01s;
    --duration-fast: 0.01s;
    --duration-normal: 0.01s;
    --duration-slow: 0.01s;
    --duration-slower: 0.01s;
    --duration-slowest: 0.01s;

    /* Linear easing only */
    --easing-standard: linear;
    --easing-emphasized: linear;
    --easing-bounce: linear;

    /* Disable delays */
    --delay-xs: 0s;
    --delay-sm: 0s;
    --delay-md: 0s;
    --delay-lg: 0s;
    --delay-xl: 0s;
    --delay-stagger-increment: 0s;
  }
}

/* =========================================================================
   DS-prefixed aliases for component consumption
   Components should use these --ds-* tokens, not the unprefixed versions.
   ========================================================================= */

:root {
  /* Duration aliases */
  --ds-duration-instant: var(--duration-instant, 0s);
  --ds-duration-fast: var(--ds-motion-fast, 120ms);
  --ds-duration-normal: var(--ds-motion-normal, 200ms);
  --ds-duration-slow: var(--duration-normal, 0.3s);
  --ds-duration-gentle: var(--duration-slow, 0.4s);

  /* Easing aliases */
  --ds-ease-out: var(--ds-ease-premium, cubic-bezier(0.16, 1, 0.3, 1));
  --ds-ease-in-out: var(--easing-standard, cubic-bezier(0.4, 0, 0.2, 1));

  /* Reduced motion override */
  --ds-motion-reduce: 0;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --ds-duration-instant: 0s;
    --ds-duration-fast: 0s;
    --ds-duration-normal: 0s;
    --ds-duration-slow: 0s;
    --ds-duration-gentle: 0s;
    --ds-motion-reduce: 1;

    /* Defense-in-depth: the --ds-motion-* canon (declared above on :root) is
       also neutralized to 0s here, so this foundation file self-zeros the
       motion durations under reduced motion even in isolation -- without
       relying on the !important token zeroing below, which this file owns
       from a later unlayered import. Both declarations resolve to 0s, so the
       :root source-order tie between the two files yields 0s either way (no
       double-definition conflict). Durations only; the easing and geometry
       tokens are inert at zero duration. */
    /* Important is intentional here: compiled BrandTheme declarations are
       tenant-scoped (`html[data-tenant]`) and therefore outrank `:root` by
       specificity. Accessibility preference must win over both static and
       DB-authored brand cadence, including inline custom-property injection. */
    --ds-motion-instant: 0s !important;
    --ds-motion-calm: 0s !important;
    --ds-motion-deliberate: 0s !important;
    --ds-motion-fast: 0s !important;
    --ds-motion-normal: 0s !important;
    --ds-motion-slow: 0s !important;
    --ds-motion-glacial: 0s !important;
    --ds-motion-feedback: 0s !important;
    --ds-motion-reveal: 0s !important;
    --ds-motion-disclosure: 0s !important;
    --ds-motion-resize: 0s !important;
    --ds-motion-rearrange: 0s !important;
    --ds-motion-attention: 0s !important;
  }
}

/* =========================================================================
   VIEW TRANSITIONS + SCROLL-DRIVEN REVEAL
   Page-to-page transitions (View Transitions API) and CSS scroll-driven
   reveal, both expressed on the --ds-motion-* canon. The View Transitions
   root animation reuses --ds-page-transition-duration (defined in
   components/patterns.css as --ds-motion-normal) so page cadence stays in one
   place. Elements opt into the scroll reveal with the .ds-scroll-reveal class
   (see the ScrollReveal primitive). Both degrade to a static paint under
   reduced motion via the guarded block below.
   ========================================================================= */

@keyframes ds-view-transition-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes ds-view-transition-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

::view-transition-old(root) {
  animation: ds-view-transition-fade-out
    var(--ds-page-transition-duration, var(--ds-motion-normal))
    var(--ds-motion-ease-out) both;
}

::view-transition-new(root) {
  animation: ds-view-transition-fade-in
    var(--ds-page-transition-duration, var(--ds-motion-normal))
    var(--ds-motion-ease-out) both;
}

@keyframes ds-scroll-reveal-in {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Opt-in scroll-driven reveal. Active only where an animation can bind to the
   view() timeline; the ScrollReveal primitive uses an IntersectionObserver
   path otherwise. `animation-range` completes the reveal inside the entry
   phase and `both` holds the end state, so content reveals once as it scrolls
   into view and does not reverse on scroll-out. The duration is inert while a
   scroll timeline drives progress but is kept on the --ds-motion canon. */
@supports (animation-timeline: view()) {
  .ds-scroll-reveal {
    animation: ds-scroll-reveal-in var(--ds-motion-slow)
      var(--ds-motion-ease-out) both;
    animation-timeline: view();
    animation-range: entry 0% entry 60%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-scroll-reveal {
    animation: none;
    animation-timeline: auto;
    opacity: 1;
  }

  /* `*` matches every view-transition-name: "root" and every DS-assigned
     name (ds-vt-list-body, ds-vt-detail-body, ds-vt-record-<key>) alike, so
     a reduced-motion preference neutralizes the root crossfade and any
     element morph the same way. The group pseudo-element animates the
     transform/size interpolation between old and new geometry (the morph
     itself); old/new animate the opacity crossfade of their content.
     Without an animation, the group renders directly at the new geometry:
     an instant cut instead of motion. */
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none;
  }
}

/* =========================================================================
   VIEW TRANSITIONS V2 - PANEL + MORPH CHOREOGRAPHY
   Runtime counterpart: graphics/motion/react/runtime/view-transition
   (startDirectionalViewTransition stamps html[data-ds-vt-direction] for the
   lifetime of one transition; tabPanelTransitionStyle / recordMorphStyle
   declare the names and view-transition-classes these rules key on).

   All rules resolve on the --ds-motion-* canon and animate only opacity and
   transform (compositor-friendly). Browsers without view-transition-class
   ignore the *.class selectors and fall back to the default named-group
   crossfade; browsers without the View Transitions API never create these
   pseudo-elements at all.
   ========================================================================= */

/* Directionless fallback for in-place panel swaps (also what a `direction:
   none` transition renders): the panel crossfades as its own group instead of
   riding the root crossfade. */
::view-transition-group(*.ds-vt-tab-panel) {
  animation-duration: var(--ds-motion-normal);
  animation-timing-function: var(--ds-motion-ease-out);
}

::view-transition-old(*.ds-vt-tab-panel) {
  animation: ds-view-transition-fade-out var(--ds-motion-fast)
    var(--ds-motion-ease-out) both;
}

::view-transition-new(*.ds-vt-tab-panel) {
  animation: ds-view-transition-fade-in var(--ds-motion-normal)
    var(--ds-motion-ease-out) both;
}

/* Direction-aware slide: old exits toward, new enters from. Each keyframe set
   carries opacity + transform so the animation-name override below fully
   replaces the crossfade instead of compounding with it. */
@keyframes ds-vt-panel-exit-toward-start {
  from {
    opacity: 1;
    transform: translateX(0);
  }
  to {
    opacity: 0;
    transform: translateX(calc(-1 * var(--ds-motion-panel-offset)));
  }
}

@keyframes ds-vt-panel-exit-toward-end {
  from {
    opacity: 1;
    transform: translateX(0);
  }
  to {
    opacity: 0;
    transform: translateX(var(--ds-motion-panel-offset));
  }
}

@keyframes ds-vt-panel-enter-from-end {
  from {
    opacity: 0;
    transform: translateX(var(--ds-motion-panel-offset));
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes ds-vt-panel-enter-from-start {
  from {
    opacity: 0;
    transform: translateX(calc(-1 * var(--ds-motion-panel-offset)));
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* The :where() wrapper zeroes the html-side specificity so these tie with the
   class-selector rules above and win purely by source order -- and, critically,
   so the reduced-motion neutralization block below can out-cascade them the
   same way. Do not replace :where() with a bare attribute selector. */
:where(html[data-ds-vt-direction='forward'])::view-transition-old(*.ds-vt-tab-panel) {
  animation: ds-vt-panel-exit-toward-start var(--ds-motion-fast)
    var(--ds-motion-ease-out) both;
}

:where(html[data-ds-vt-direction='forward'])::view-transition-new(*.ds-vt-tab-panel) {
  animation: ds-vt-panel-enter-from-end var(--ds-motion-normal)
    var(--ds-motion-ease-out) both;
}

:where(html[data-ds-vt-direction='backward'])::view-transition-old(*.ds-vt-tab-panel) {
  animation: ds-vt-panel-exit-toward-end var(--ds-motion-fast)
    var(--ds-motion-ease-out) both;
}

:where(html[data-ds-vt-direction='backward'])::view-transition-new(*.ds-vt-tab-panel) {
  animation: ds-vt-panel-enter-from-start var(--ds-motion-normal)
    var(--ds-motion-ease-out) both;
}

/* Record morphs (kanban card -> detail, row -> detail): the browser's default
   group animation already interpolates geometry between the paired elements;
   these rules only put its timing on the canon. */
::view-transition-group(*.ds-vt-record) {
  animation-duration: var(--ds-motion-slow);
  animation-timing-function: var(--ds-motion-ease-out);
}

/* Modal -> full-page promote morph (named pair ds-vt-modal-promote; see
   MODAL_PROMOTE_TRANSITION_NAME in the view-transition runtime for the wiring
   contract). */
::view-transition-group(ds-vt-modal-promote),
::view-transition-old(ds-vt-modal-promote),
::view-transition-new(ds-vt-modal-promote) {
  animation-duration: var(--ds-motion-slow);
  animation-timing-function: var(--ds-motion-ease-out);
}

/* Reduced-motion neutralization for every group this section styles. The
   generic ::view-transition-*(*) block above already matches these names, but
   the directional rules tie or beat it on specificity; these selectors mirror
   the styled groups exactly and sit later in source order, so they win the
   tie. The runtime backstop is stronger still: under reduced motion
   startDsViewTransition takes the immediate path and no pseudo-elements are
   created. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*.ds-vt-tab-panel),
  ::view-transition-old(*.ds-vt-tab-panel),
  ::view-transition-new(*.ds-vt-tab-panel),
  ::view-transition-group(*.ds-vt-record),
  ::view-transition-old(*.ds-vt-record),
  ::view-transition-new(*.ds-vt-record),
  ::view-transition-group(ds-vt-modal-promote),
  ::view-transition-old(ds-vt-modal-promote),
  ::view-transition-new(ds-vt-modal-promote) {
    animation: none;
  }
}

/* Provider-owned reduce seam: MotionProvider stamps html[data-ds-motion=
   'reduced'] when reduced motion is forced without the OS media query (see
   runtime/personality.css). View transitions started by non-DS code (an app
   router) bypass the runtime gate, so the CSS neutralization must also hold
   on this seam. html + attribute out-specifies every :where()-wrapped
   directional rule above. */
html[data-ds-motion='reduced']::view-transition-group(*),
html[data-ds-motion='reduced']::view-transition-old(*),
html[data-ds-motion='reduced']::view-transition-new(*) {
  animation: none;
}

/* =========================================================================
   DATA-CHANGED PULSE (.ds-pulse-changed)
   A single, non-looping flash for live-updating cells/rows (data-table live
   cells, live-feed rows). Uses an inset box-shadow rather than
   background-color so it layers on top of whatever background the element
   already has (striped rows, hover state, selection) instead of overwriting
   it. Intensity is tunable via --ds-effect-intensity (0 collapses the flash
   to fully transparent, satisfying a zero-decoration tenant without a
   separate opt-out). `animation` with no explicit iteration-count defaults
   to 1 -- this must NEVER be changed to `infinite` or given a `-loop`
   variant; the "one subtle flash" contract depends on it staying singular.
   Pair with the `usePulseOnChange` hook (patterns/foundation/hooks), which
   remounts the flashing node on each change so the animation restarts.
   ========================================================================= */
@keyframes ds-pulse-changed-flash {
  from {
    box-shadow: inset 0 0 0 9999px
      rgba(
        var(--ds-color-primary-rgb),
        calc(0.14 * var(--ds-effect-intensity, 1))
      );
  }
  to {
    box-shadow: inset 0 0 0 9999px rgba(var(--ds-color-primary-rgb), 0);
  }
}

.ds-pulse-changed {
  animation-name: ds-pulse-changed-flash;
  animation-duration: var(--ds-motion-slow);
  animation-timing-function: var(--ds-motion-ease-out);
}

@media (prefers-reduced-motion: reduce) {
  .ds-pulse-changed {
    animation: none;
  }
}

/**
 * Keyframe Animations - Rottay Design System
 *
 * CSS @keyframes definitions for reusable animations.
 * Use with animation property or combine with transition tokens.
 */

/* ========================================================================
   FADE ANIMATIONS
   Opacity-based entrance and exit animations
   ======================================================================== */

@keyframes ds-foundation-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes ds-foundation-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes ds-foundation-fade-in-up {
  from {
    opacity: 0;
    transform: translateY(1rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes ds-foundation-fade-in-down {
  from {
    opacity: 0;
    transform: translateY(-1rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes ds-foundation-fade-in-left {
  from {
    opacity: 0;
    transform: translateX(-1rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes ds-foundation-fade-in-right {
  from {
    opacity: 0;
    transform: translateX(1rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* ========================================================================
   SCALE ANIMATIONS
   Grow and shrink effects
   ======================================================================== */

@keyframes ds-foundation-scale-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes ds-foundation-scale-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.95);
  }
}

@keyframes ds-foundation-scale-up {
  from {
    transform: scale(0);
  }
  to {
    transform: scale(1);
  }
}

@keyframes ds-foundation-scale-down {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(0);
  }
}

@keyframes ds-foundation-zoom-in {
  from {
    opacity: 0;
    transform: scale(0.3);
  }
  50% {
    opacity: 1;
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes ds-foundation-zoom-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: scale(0.3);
  }
}

/* ========================================================================
   SLIDE ANIMATIONS
   Directional sliding effects
   ======================================================================== */

@keyframes ds-foundation-slide-in-up {
  from {
    transform: translateY(100%);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes ds-foundation-slide-in-down {
  from {
    transform: translateY(-100%);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes ds-foundation-slide-in-left {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(0);
  }
}

@keyframes ds-foundation-slide-in-right {
  from {
    transform: translateX(100%);
  }
  to {
    transform: translateX(0);
  }
}

@keyframes ds-foundation-slide-out-up {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-100%);
  }
}

@keyframes ds-foundation-slide-out-down {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(100%);
  }
}

@keyframes ds-foundation-slide-out-left {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-100%);
  }
}

@keyframes ds-foundation-slide-out-right {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(100%);
  }
}

/* ========================================================================
   ROTATE ANIMATIONS
   Spinning and rotation effects
   ======================================================================== */

@keyframes ds-foundation-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes ds-foundation-spin-reverse {
  from {
    transform: rotate(360deg);
  }
  to {
    transform: rotate(0deg);
  }
}

@keyframes ds-foundation-rotate-in {
  from {
    opacity: 0;
    transform: rotate(-180deg);
  }
  to {
    opacity: 1;
    transform: rotate(0deg);
  }
}

@keyframes ds-foundation-rotate-out {
  from {
    opacity: 1;
    transform: rotate(0deg);
  }
  to {
    opacity: 0;
    transform: rotate(180deg);
  }
}

/* ========================================================================
   BOUNCE ANIMATIONS
   Playful bouncing effects
   ======================================================================== */

@keyframes ds-foundation-bounce {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-25%);
  }
}

@keyframes ds-foundation-bounce-in {
  0% {
    opacity: 0;
    transform: scale(0.3);
  }
  50% {
    opacity: 1;
    transform: scale(1.05);
  }
  70% {
    transform: scale(0.9);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes ds-foundation-bounce-out {
  0% {
    transform: scale(1);
  }
  25% {
    transform: scale(0.95);
  }
  50% {
    opacity: 1;
    transform: scale(1.1);
  }
  100% {
    opacity: 0;
    transform: scale(0.3);
  }
}

/* ========================================================================
   SHAKE ANIMATIONS
   Error indication and attention grabbers
   ======================================================================== */

@keyframes ds-foundation-shake {
  0%, 100% {
    transform: translateX(0);
  }
  10%, 30%, 50%, 70%, 90% {
    transform: translateX(-0.5rem);
  }
  20%, 40%, 60%, 80% {
    transform: translateX(0.5rem);
  }
}

@keyframes ds-foundation-shake-vertical {
  0%, 100% {
    transform: translateY(0);
  }
  10%, 30%, 50%, 70%, 90% {
    transform: translateY(-0.5rem);
  }
  20%, 40%, 60%, 80% {
    transform: translateY(0.5rem);
  }
}

/* ========================================================================
   PULSE ANIMATIONS
   Attention and loading indicators
   ======================================================================== */

@keyframes ds-foundation-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

@keyframes ds-foundation-pulse-scale {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
}

@keyframes ds-foundation-pulse-ring {
  0% {
    transform: scale(1);
    opacity: 1;
  }
  100% {
    transform: scale(1.5);
    opacity: 0;
  }
}

/* ========================================================================
   SHIMMER/LOADING ANIMATIONS
   Skeleton loaders and loading states
   ======================================================================== */

@keyframes ds-foundation-shimmer {
  0% {
    background-position: -100% 0;
  }
  100% {
    background-position: 100% 0;
  }
}

/* Canon skeleton loading set (TASK S). ONE ds- namespaced set shared by every
   engine's Skeleton skin plus the skeleton-shimmer consumers (compounds,
   stats-grid), replacing the piecemeal per-engine keyframes. Members map 1:1 to
   the skeletonStyle personality ('pulse'|'shimmer'|'wave'); a consumer selects
   one through --ds-skeleton-animation-name and rides the
   --ds-skeleton-animation-duration token. Each animates only opacity or
   background-position (compositor-friendly, no layout tokens); the global
   reduced-motion guard in runtime/personality.css neutralizes all three. */
@keyframes ds-skeleton-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

@keyframes ds-skeleton-shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

@keyframes ds-skeleton-wave {
  0% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0 50%;
  }
}

@keyframes ds-foundation-progress-indeterminate {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

/* ========================================================================
   FLIP ANIMATIONS
   Card flip and rotation effects
   ======================================================================== */

@keyframes ds-foundation-flip-horizontal {
  0% {
    transform: rotateY(0deg);
  }
  100% {
    transform: rotateY(180deg);
  }
}

@keyframes ds-foundation-flip-vertical {
  0% {
    transform: rotateX(0deg);
  }
  100% {
    transform: rotateX(180deg);
  }
}

/* ========================================================================
   SWING ANIMATIONS
   Pendulum and hanging effects
   ======================================================================== */

@keyframes ds-foundation-swing {
  0%, 100% {
    transform: rotate(0deg);
  }
  20% {
    transform: rotate(15deg);
  }
  40% {
    transform: rotate(-10deg);
  }
  60% {
    transform: rotate(5deg);
  }
  80% {
    transform: rotate(-5deg);
  }
}

/* ========================================================================
   WIGGLE ANIMATIONS
   Playful attention grabbers
   ======================================================================== */

@keyframes ds-foundation-wiggle {
  0%, 100% {
    transform: rotate(0deg);
  }
  25% {
    transform: rotate(-5deg);
  }
  75% {
    transform: rotate(5deg);
  }
}

/* ========================================================================
   HEARTBEAT ANIMATION
   Like/favorite indication
   ======================================================================== */

@keyframes ds-foundation-heartbeat {
  0%, 100% {
    transform: scale(1);
  }
  14% {
    transform: scale(1.3);
  }
  28% {
    transform: scale(1);
  }
  42% {
    transform: scale(1.3);
  }
  56% {
    transform: scale(1);
  }
}

/* ========================================================================
   BLINK ANIMATION
   Cursor and attention indication
   ======================================================================== */

@keyframes ds-foundation-blink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

/* ========================================================================
   TYPING DOTS ANIMATION
   Loading indicator with dots
   ======================================================================== */

@keyframes ds-foundation-typing-dots {
  0%, 60%, 100% {
    transform: translateY(0);
  }
  30% {
    transform: translateY(-0.5rem);
  }
}

/* ========================================================================
   RIPPLE ANIMATION
   Material-style ripple effect
   ======================================================================== */

@keyframes ds-foundation-ripple {
  0% {
    transform: scale(0);
    opacity: 1;
  }
  100% {
    transform: scale(4);
    opacity: 0;
  }
}

/* ========================================================================
   GLOW ANIMATION
   Glowing effect for emphasis
   ======================================================================== */

@keyframes ds-foundation-glow {
  0%, 100% {
    box-shadow: 0 0 0.5rem rgba(var(--ds-color-primary-rgb, 0, 102, 204), 0.5);
  }
  50% {
    box-shadow: 0 0 1.5rem rgba(var(--ds-color-primary-rgb, 0, 102, 204), 0.8),
                0 0 2rem rgba(var(--ds-color-primary-rgb, 0, 102, 204), 0.4);
  }
}

/* ========================================================================
   COMPONENT-SPECIFIC ANIMATIONS
   Keyframes used by individual DS components
   ======================================================================== */

/* Button spinner - used by Rustic and Modern engines */
@keyframes ds-button-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* Button pulse - used by Rustic engine */
@keyframes ds-button-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(var(--ds-color-primary-rgb, 59, 130, 246), 0.5);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(var(--ds-color-primary-rgb, 59, 130, 246), 0);
  }
}

/* Modal entrance - currently unreferenced (superseded by the modern engine's
   own ds-overlay-modal-enter-modern / ds-modal-panel-enter-modern keyframes). */
@keyframes ds-foundation-modal-scale-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Modal backdrop entrance - currently unreferenced (superseded by the modern
   engine's own ds-overlay-modal-backdrop-enter-modern keyframe). */
@keyframes ds-foundation-modal-backdrop-enter {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Select dropdown slide-in - currently unreferenced (superseded by the
   picker/select family's own ds-select-dropdown-in / ds-date-picker-slide-in /
   ds-time-picker-slide-in / ds-tree-select-slide-in keyframes). */
@keyframes ds-foundation-select-slide-in {
  from {
    opacity: 0;
    transform: scaleY(0.95);
    transform-origin: top;
  }
  to {
    opacity: 1;
    transform: scaleY(1);
    transform-origin: top;
  }
}

/* Tabs panel fade-in - used by Modern engine */
@keyframes ds-tabs-fade-in {
  from {
    opacity: 0;
    transform: translateY(2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ========================================================================
   MODAL & OVERLAY ANIMATIONS
   Shared keyframes for modal entrance and backdrop fade.
   ======================================================================== */

@keyframes ds-foundation-modal-enter {
  from { opacity: 0; transform: scale(0.95) translateY(8px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

@keyframes ds-foundation-backdrop-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

/**
 * Premium Effect Tokens - Rottay Design System
 *
 * The gradient / glass / glow layer for the modern engine's Quiet Premium
 * signature. Every effect below is scaled by --ds-effect-intensity so a tenant
 * collapses the whole layer to flat by setting the dial to 0 (BitHire's
 * Evidence-Ledger zero-decoration law); the DS/rottay default (1) showcases the
 * full treatment.
 *
 * Sanctioned roles (engines/modern spec section 5):
 *   surface-tint  --ds-gradient-surface  -> cards, hero surfaces, metric tiles
 *   accent        --ds-gradient-primary  -> primary buttons, selected states
 *   signal-glow   --ds-shadow-glow-*     -> live/AI moments + data-viz ONLY
 *   glass         --ds-glass-*           -> overlay backdrops ONLY (modal/palette/drawer)
 *   mesh          --ds-gradient-mesh     -> marketing/showcase ONLY (never product chrome)
 */

:root {
  /* ========================================================================
     EFFECT INTENSITY DIAL
     Tenant/vertical-tunable multiplier. 1 = full Quiet Premium (DS/rottay
     default); 0 = flat (no gradient/glass/glow). Every effect multiplies its
     alpha/length by this, so intensity 0 collapses each effect to none while
     keeping valid CSS (blur(0px), transparent stops, 0-alpha shadow).
     Emitted per tenant by infrastructure/compilers/kernel/runtime/brand-theme from surfaces.effectIntensity.
     ======================================================================== */
  --ds-effect-intensity: 1;

  /* ========================================================================
     GLASSMORPHISM (overlay backdrops ONLY: modal, command palette, drawer)
     Base palette tokens are read by the glass-card effect and exposed through
     the useTokens() catalog; blur/bg/border scale with --ds-effect-intensity so
     a zero-intensity tenant (bithire) collapses them without needing a per-token
     'none' override. The two composed backdrop tokens are the wired overlay
     values and likewise collapse to a plain scrim at intensity 0.
     ======================================================================== */
  --ds-glass-blur: calc(12px * var(--ds-effect-intensity));
  --ds-glass-blur-sm: 8px;
  --ds-glass-blur-lg: 20px;
  --ds-glass-blur-xl: 32px;
  --ds-glass-bg: rgba(255, 255, 255, calc(0.05 * var(--ds-effect-intensity)));
  --ds-glass-bg-light: var(--ds-color-alpha-white-10);
  --ds-glass-bg-heavy: var(--ds-color-alpha-white-20);
  --ds-glass-border: rgba(255, 255, 255, calc(0.10 * var(--ds-effect-intensity)));
  --ds-glass-border-light: var(--ds-color-alpha-white-5);
  --ds-glass-border-heavy: var(--ds-color-alpha-white-20);

  /* Wired overlay-backdrop values. Intensity 0 -> blur(0px) + transparent tint,
     i.e. the backdrop falls back to its plain scrim. The 12px/0.05 literals are
     inlined (not var(--ds-glass-blur)) so a tenant hard-nulling --ds-glass-blur
     cannot turn this into the invalid blur(none). */
  --ds-glass-backdrop-filter: blur(calc(12px * var(--ds-effect-intensity)));
  --ds-glass-scrim-tint: rgba(255, 255, 255, calc(0.05 * var(--ds-effect-intensity)));

  /* ========================================================================
     SIGNAL-GLOW (live/AI moments + data-viz emphasis ONLY, never static chrome)
     ======================================================================== */
  --ds-shadow-glow-primary: 0 0 calc(40px * var(--ds-effect-intensity)) rgba(var(--ds-color-primary-rgb), calc(0.18 * var(--ds-effect-intensity)));

  /* ========================================================================
     GRADIENTS
     ======================================================================== */
  /* surface-tint: barely-there ~2-3% vertical luminance tint that replaces flat
     fills on cards, hero surfaces and metric tiles. */
  --ds-gradient-surface: linear-gradient(
    180deg,
    rgba(255, 255, 255, calc(0.025 * var(--ds-effect-intensity))) 0%,
    rgba(255, 255, 255, calc(0.004 * var(--ds-effect-intensity))) 52%,
    rgba(0, 0, 0, calc(0.02 * var(--ds-effect-intensity))) 100%
  );
  /* accent: subtle top-light sheen on primary buttons and selected states. */
  --ds-gradient-primary: linear-gradient(
    180deg,
    rgba(255, 255, 255, calc(0.16 * var(--ds-effect-intensity))) 0%,
    rgba(255, 255, 255, 0) 46%,
    rgba(0, 0, 0, calc(0.06 * var(--ds-effect-intensity))) 100%
  );
  /* Catalog-only gradients (exposed via useTokens(); not wired into chrome). */
  --ds-gradient-primary-soft: linear-gradient(135deg, var(--ds-color-primary-50), var(--ds-color-secondary-50));
  --ds-gradient-dark: linear-gradient(135deg, var(--ds-color-neutral-900), var(--ds-color-neutral-800));
  /* mesh: marketing/showcase ONLY (never wired into product chrome). */
  --ds-gradient-mesh: radial-gradient(at 40% 20%, var(--ds-color-primary-100) 0px, transparent 50%),
                      radial-gradient(at 80% 0%, var(--ds-color-secondary-100) 0px, transparent 50%),
                      radial-gradient(at 0% 50%, var(--ds-color-primary-50) 0px, transparent 50%);

  /* ========================================================================
     PREMIUM EASING
     Additional cubic-bezier curves for premium animations
     ======================================================================== */
  --ds-ease-premium: cubic-bezier(0.16, 1, 0.3, 1);
  --ds-ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ds-ease-smooth: cubic-bezier(0.25, 0.1, 0.25, 1);
  --ds-ease-out-expo: cubic-bezier(0.19, 1, 0.22, 1);
  --ds-ease-in-out-expo: cubic-bezier(0.87, 0, 0.13, 1);
}

/* Reduced motion: disable the blur/glow effects that may cause discomfort. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --ds-glass-blur: 0px;
    --ds-glass-blur-sm: 0px;
    --ds-glass-blur-lg: 0px;
    --ds-glass-blur-xl: 0px;
    --ds-glass-backdrop-filter: none;
    --ds-shadow-glow-primary: none;
  }
}

/**
 * Collection insert stagger preset — Rottay Design System.
 *
 * The CSS half of the `collection.insert` motion recipe
 * (infrastructure/runtime/foundation/motion/policy/recipes: staggerStepMs 30,
 * staggerMaxMs 240, both capped by MAX_TOTAL_STAGGER_MS 320). A collection
 * surface stamps `.ds-collection-stagger` on a freshly mounted batch and sets
 * `--ds-stagger-index` on each row/card; every item reveals with a
 * compositor-only opacity+transform entrance whose start is delayed by
 * `index * step`, clamped to `max`, so a large batch never staggers longer than
 * the cap (150-300ms total by design). The `useCollectionStagger` hook
 * (ui/patterns/foundation/motion) resolves the SAME recipe through the active
 * motion policy, stamps the class only when the policy animates, and writes
 * `--ds-stagger-step`/`--ds-stagger-max` from the resolved recipe so a tenant's
 * durationScale moves the CSS and the JS in lockstep.
 *
 * Compositor-only (modern engine spec section 2, WO-CRA-06): opacity + transform
 * only, never a layout property. Under reduced motion every item resolves to its
 * final state with no delay -- the media guard below is load-bearing because the
 * step/max tokens are not zeroed by the foundation reduced-motion block (a bare
 * duration zero would still leave each item delayed and briefly hidden).
 */

:root {
  /* collection.insert recipe bounds. A stamping container overrides these inline
     from the resolved recipe; these defaults keep the class self-sufficient when
     stamped without the hook (e.g. a static server-rendered batch). */
  --ds-stagger-step: 30ms;
  --ds-stagger-max: 240ms;
}

@keyframes ds-collection-insert {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.ds-collection-stagger [data-ds-stagger-item] {
  animation-name: ds-collection-insert;
  animation-duration: var(--ds-motion-normal);
  animation-timing-function: var(--ds-motion-ease-out);
  /* `both` holds the from-state through the delay so an item stays hidden until
     its turn instead of flashing in and then animating out. */
  animation-fill-mode: both;
  animation-delay: min(
    var(--ds-stagger-index, 0) * var(--ds-stagger-step),
    var(--ds-stagger-max)
  );
}

@media (prefers-reduced-motion: reduce) {
  .ds-collection-stagger [data-ds-stagger-item] {
    animation: none;
  }
}


}

/* Layer 2: Component tokens */
@layer rottay-components {
/**
 * Avatar Component Tokens - Rottay Design System
 *
 * Design tokens specific to the Avatar component.
 * Includes sizes, shapes, variants, status indicators, and group settings.
 */

:root {
  /* ========================================================================
     SIZES - Avatar Dimensions
     Seven size variants from xs to 3xl with corresponding properties
     ======================================================================== */

  /* XS - Extra Small (24px) */
  --ds-avatar-xs-size: 1.5rem;           /* 24px */
  --ds-avatar-xs-font-size: 0.625rem;    /* 10px */
  --ds-avatar-xs-status-size: 0.375rem;  /* 6px */
  --ds-avatar-xs-border-width: 1px;

  /* SM - Small (32px) */
  --ds-avatar-sm-size: 2rem;             /* 32px */
  --ds-avatar-sm-font-size: 0.75rem;     /* 12px */
  --ds-avatar-sm-status-size: 0.5rem;    /* 8px */
  --ds-avatar-sm-border-width: 1.5px;

  /* MD - Medium (40px - Default) */
  --ds-avatar-md-size: 2.5rem;           /* 40px */
  --ds-avatar-md-font-size: 0.875rem;    /* 14px */
  --ds-avatar-md-status-size: 0.625rem;  /* 10px */
  --ds-avatar-md-border-width: 2px;

  /* LG - Large (48px) */
  --ds-avatar-lg-size: 3rem;             /* 48px */
  --ds-avatar-lg-font-size: 1rem;        /* 16px */
  --ds-avatar-lg-status-size: 0.75rem;   /* 12px */
  --ds-avatar-lg-border-width: 2px;

  /* XL - Extra Large (56px) */
  --ds-avatar-xl-size: 3.5rem;           /* 56px */
  --ds-avatar-xl-font-size: 1.125rem;    /* 18px */
  --ds-avatar-xl-status-size: 0.875rem;  /* 14px */
  --ds-avatar-xl-border-width: 2.5px;

  /* 2XL - 2x Extra Large (64px) */
  --ds-avatar-2xl-size: 4rem;            /* 64px */
  --ds-avatar-2xl-font-size: 1.25rem;    /* 20px */
  --ds-avatar-2xl-status-size: 1rem;     /* 16px */
  --ds-avatar-2xl-border-width: 3px;

  /* 3XL - 3x Extra Large (96px) */
  --ds-avatar-3xl-size: 6rem;            /* 96px */
  --ds-avatar-3xl-font-size: 1.75rem;    /* 28px */
  --ds-avatar-3xl-status-size: 1.25rem;  /* 20px */
  --ds-avatar-3xl-border-width: 4px;

  /* Default size (can be overridden) */
  --ds-avatar-default-size: var(--ds-avatar-md-size);
  --ds-avatar-default-font-size: var(--ds-avatar-md-font-size);
  --ds-avatar-default-status-size: var(--ds-avatar-md-status-size);
  --ds-avatar-default-border-width: var(--ds-avatar-md-border-width);

  /* ========================================================================
     SHAPES - Avatar Border Radius
     Three shape variants: circle, square, rounded
     ======================================================================== */
  --ds-avatar-circle-radius: 50%;                          /* Fully rounded */
  --ds-avatar-square-radius: 0;                            /* No rounding */
  --ds-avatar-rounded-radius: var(--ds-radius-md, 0.5rem);    /* 8px rounded corners */

  /* Default shape */
  --ds-avatar-default-shape: var(--ds-avatar-circle-radius);

  /* ========================================================================
     VARIANTS - Avatar Color Variants
     Different visual styles for avatars
     ======================================================================== */

  /* Default variant (neutral) */
  --ds-avatar-default-bg: var(--ds-color-neutral-100);
  --ds-avatar-default-color: var(--ds-color-neutral-600);
  --ds-avatar-default-border-color: var(--ds-color-neutral-200);
  --ds-avatar-default-shadow: none;

  /* Primary variant */
  --ds-avatar-primary-bg: var(--ds-color-primary-100);
  --ds-avatar-primary-color: var(--ds-color-primary-700);
  --ds-avatar-primary-border-color: var(--ds-color-primary-200);
  --ds-avatar-primary-shadow: 0 2px 8px rgba(0, 102, 204, 0.15);

  /* Secondary variant */
  --ds-avatar-secondary-bg: var(--ds-color-secondary-100);
  --ds-avatar-secondary-color: var(--ds-color-secondary-700);
  --ds-avatar-secondary-border-color: var(--ds-color-secondary-200);
  --ds-avatar-secondary-shadow: 0 2px 8px rgba(107, 107, 212, 0.15);

  /* Success variant */
  --ds-avatar-success-bg: var(--ds-color-success-100);
  --ds-avatar-success-color: var(--ds-color-success-700);
  --ds-avatar-success-border-color: var(--ds-color-success-200);
  --ds-avatar-success-shadow: 0 2px 8px rgba(34, 197, 94, 0.15);

  /* Warning variant */
  --ds-avatar-warning-bg: var(--ds-color-warning-100);
  --ds-avatar-warning-color: var(--ds-color-warning-700);
  --ds-avatar-warning-border-color: var(--ds-color-warning-200);
  --ds-avatar-warning-shadow: 0 2px 8px rgba(245, 158, 11, 0.15);

  /* Error variant */
  --ds-avatar-error-bg: var(--ds-color-error-100);
  --ds-avatar-error-color: var(--ds-color-error-700);
  --ds-avatar-error-border-color: var(--ds-color-error-200);
  --ds-avatar-error-shadow: 0 2px 8px rgba(239, 68, 68, 0.15);

  /* Gradient variant */
  --ds-avatar-gradient-bg: linear-gradient(135deg, var(--ds-color-primary-400) 0%, var(--ds-color-secondary-500) 100%);
  --ds-avatar-gradient-color: var(--ds-color-white);
  --ds-avatar-gradient-border-color: transparent;
  --ds-avatar-gradient-shadow: 0 4px 12px rgba(0, 102, 204, 0.2);

  /* ========================================================================
     STATUS INDICATORS
     Color indicators for online/offline/away/busy states
     ======================================================================== */
  --ds-avatar-status-online-color: var(--ds-color-success-500);
  --ds-avatar-status-offline-color: var(--ds-color-neutral-400);
  --ds-avatar-status-away-color: var(--ds-color-warning-500);
  --ds-avatar-status-busy-color: var(--ds-color-error-500);

  /* Status indicator position and sizing */
  --ds-avatar-status-offset: 0;          /* Distance from edge */
  --ds-avatar-status-border-width: 2px;  /* White border around status */
  --ds-avatar-status-border-color: var(--ds-color-white);

  /* ========================================================================
     AVATAR GROUP
     Settings for overlapping avatar groups
     ======================================================================== */
  --ds-avatar-group-compact-spacing: -0.5rem;   /* -8px overlap */
  --ds-avatar-group-normal-spacing: -0.25rem;   /* -4px overlap */
  --ds-avatar-group-loose-spacing: 0.25rem;     /* 4px gap */

  /* Default group spacing */
  --ds-avatar-group-default-spacing: var(--ds-avatar-group-normal-spacing);

  /* Group max count settings */
  --ds-avatar-group-max-count: 5;                /* Max avatars before showing +N */
  --ds-avatar-group-overflow-bg: var(--ds-color-neutral-200);
  --ds-avatar-group-overflow-color: var(--ds-color-neutral-700);
  --ds-avatar-group-overflow-font-weight: var(--ds-font-weight-medium);

  /* ========================================================================
     INTERACTIONS
     Hover, focus, and active states
     ======================================================================== */
  --ds-avatar-hover-scale: 1.05;
  --ds-avatar-hover-shadow: 0 4px 12px rgba(0, 0, 0, 0.1);
  --ds-avatar-hover-border-color: var(--ds-color-primary-300);

  --ds-avatar-focus-ring-width: 2px;
  --ds-avatar-focus-ring-color: var(--ds-color-primary-500);
  --ds-avatar-focus-ring-offset: 2px;

  --ds-avatar-active-scale: 0.98;

  /* ========================================================================
     BADGE/NOTIFICATION
     For notification badges on avatars
     ======================================================================== */
  --ds-avatar-badge-size: 1rem;                  /* 16px */
  --ds-avatar-badge-font-size: 0.625rem;         /* 10px */
  --ds-avatar-badge-bg: var(--ds-color-error-500);
  --ds-avatar-badge-color: var(--ds-color-white);
  --ds-avatar-badge-border-width: 2px;
  --ds-avatar-badge-border-color: var(--ds-color-white);
  --ds-avatar-badge-offset-top: 0;
  --ds-avatar-badge-offset-right: 0;

  /* ========================================================================
     LOADING STATE
     Skeleton/loading appearance
     ======================================================================== */
  --ds-avatar-loading-bg: var(--ds-color-neutral-100);
  --ds-avatar-loading-animation: ds-foundation-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;

  /* ========================================================================
     TOUCH TARGETS
     Minimum touch target size for accessibility
     ======================================================================== */
  --ds-avatar-touch-target-min: 2.75rem;  /* 44px - WCAG AAA minimum */

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */
  --ds-avatar-transition-duration: 0.2s;
  --ds-avatar-transition-timing: ease-in-out;
  --ds-avatar-transition: all var(--ds-avatar-transition-duration) var(--ds-avatar-transition-timing);

  /* ========================================================================
     IMAGE SETTINGS
     Settings for image rendering within avatars
     ======================================================================== */
  --ds-avatar-image-object-fit: cover;
  --ds-avatar-image-object-position: center;

  /* ========================================================================
     FALLBACK ICON
     Settings for icon fallback when no image is provided
     ======================================================================== */
  --ds-avatar-fallback-icon-size: 60%;  /* Icon size relative to avatar */
  --ds-avatar-fallback-icon-color: currentColor;
}

}
@layer rottay-components {
/**
 * Badge Component Tokens - Rottay Design System
 *
 * Design tokens specific to the Badge component.
 * Includes sizes, dot sizes, variants, and styling properties.
 */

:root {
  /* ========================================================================
     SIZES - Badge Dimensions
     Five size variants from xs to xl with corresponding properties
     ======================================================================== */

  /* XS - Extra Small */
  --ds-badge-xs-min-width: 0.875rem;       /* 14px */
  --ds-badge-xs-height: 0.875rem;          /* 14px */
  --ds-badge-xs-font-size: 0.5625rem;      /* 9px */
  --ds-badge-xs-padding-x: 0.375rem;

  /* SM - Small */
  --ds-badge-sm-min-width: 1rem;           /* 16px */
  --ds-badge-sm-height: 1rem;              /* 16px */
  --ds-badge-sm-font-size: 0.625rem;       /* 10px */
  --ds-badge-sm-padding-x: 0.5rem;

  /* MD - Medium (Default) */
  --ds-badge-md-min-width: 1.25rem;        /* 20px */
  --ds-badge-md-height: 1.25rem;           /* 20px */
  --ds-badge-md-font-size: 0.75rem;        /* 12px */
  --ds-badge-md-padding-x: 0.625rem;

  /* LG - Large */
  --ds-badge-lg-min-width: 1.5rem;         /* 24px */
  --ds-badge-lg-height: 1.5rem;            /* 24px */
  --ds-badge-lg-font-size: 0.875rem;       /* 14px */
  --ds-badge-lg-padding-x: 0.75rem;

  /* XL - Extra Large */
  --ds-badge-xl-min-width: 1.75rem;        /* 28px */
  --ds-badge-xl-height: 1.75rem;           /* 28px */
  --ds-badge-xl-font-size: 1rem;           /* 16px */
  --ds-badge-xl-padding-x: 0.875rem;

  /* Default size (can be overridden) */
  --ds-badge-default-min-width: var(--ds-badge-md-min-width);
  --ds-badge-default-height: var(--ds-badge-md-height);
