  color: var(--_surface-foreground-muted, var(--ds-color-text-secondary, inherit));
}

@media (hover: hover) {
  .ds-semantic-surface[data-interactive="true"]:hover {
    background: var(--_surface-texture, none),
      var(--_surface-background-hover, var(--_surface-background));
    border-color: var(--_surface-border-hover, var(--_surface-border));
    box-shadow: var(--_surface-shadow-hover, var(--_surface-shadow));
  }
}

.ds-semantic-surface[data-interactive="true"]:active {
  background: var(--_surface-texture, none),
    var(--_surface-background-active, var(--_surface-background));
  border-color: var(--_surface-border-active, var(--_surface-border));
  box-shadow: var(--_surface-shadow-active, var(--_surface-shadow));
}

.ds-semantic-surface[data-interactive="true"]:focus-visible {
  outline: none;
}

.ds-semantic-surface[data-interactive="true"]:focus-visible::after {
  opacity: 1;
}

.ds-semantic-surface[data-selected="true"] {
  background: var(--_surface-texture, none),
    var(--_surface-background-selected, var(--_surface-background));
  border-color: var(--_surface-border-selected, var(--_surface-border-strong));
  box-shadow: var(--_surface-shadow-selected, var(--_surface-shadow));
}

.ds-semantic-surface[data-dragging="true"] {
  border-color: var(--_surface-border-active, var(--_surface-border-strong));
  box-shadow: var(--_surface-shadow-active, var(--_surface-shadow-hover));
  cursor: grabbing;
}

.ds-semantic-surface[data-loading="true"] {
  color: var(--_surface-foreground-muted, var(--_surface-foreground));
  cursor: progress;
}

.ds-semantic-surface[data-disabled="true"] {
  background: var(--_surface-texture, none),
    var(--_surface-background-disabled, var(--_surface-background));
  color: var(--_surface-foreground-disabled, var(--_surface-foreground-muted));
  border-color: var(--_surface-border-disabled, var(--_surface-border));
  box-shadow: var(--_surface-shadow, none);
  cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
  .ds-semantic-surface,
  .ds-semantic-surface::after {
    transition-duration: 0.01ms;
  }
}

@media (forced-colors: active) {
  .ds-semantic-surface {
    background: Canvas;
    color: CanvasText;
    border-color: CanvasText;
    box-shadow: none;
  }

  .ds-semantic-surface::before,
  .ds-semantic-surface::after {
    box-shadow: none;
  }

  .ds-semantic-surface[data-selected="true"] {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }

  .ds-semantic-surface[data-interactive="true"]:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }

  .ds-semantic-surface[data-disabled="true"] {
    color: GrayText;
    border-color: GrayText;
  }
}

