  --ds-button-spinner-track-opacity: 0.2;
  --ds-button-spinner-stroke-width: 2.5;
  --ds-button-spinner-duration: var(--ds-motion-attention);
}

}
@layer rottay-components {
/**
 * Input Component Tokens - Rottay Design System
 *
 * Design tokens specific to Input components (text inputs, textareas, etc).
 * Includes sizes, variants, states, and interactive properties.
 */

:root {
  /* ========================================================================
     SIZES - Input Dimensions
     Five size variants from xs to xl with corresponding properties
     ======================================================================== */

  /* XS - Extra Small */
  --ds-input-xs-height: 1.5rem;            /* 24px */
  --ds-input-xs-padding-x: 0.5rem;         /* 8px */
  --ds-input-xs-padding-y: 0.125rem;       /* 2px */
  --ds-input-xs-font-size: 0.75rem;        /* 12px */
  --ds-input-xs-line-height: 1.25rem;      /* 20px */
  --ds-input-xs-icon-size: 0.875rem;       /* 14px */
  --ds-input-xs-border-radius: var(--ds-radius-sm);

  /* SM - Small */
  --ds-input-sm-height: 2rem;              /* 32px */
  --ds-input-sm-padding-x: 0.625rem;       /* 10px */
  --ds-input-sm-padding-y: 0.25rem;        /* 4px */
  --ds-input-sm-font-size: 0.8125rem;      /* 13px */
  --ds-input-sm-line-height: 1.5rem;       /* 24px */
  --ds-input-sm-icon-size: 1rem;           /* 16px */
  --ds-input-sm-border-radius: var(--ds-radius-md);

  /* MD - Medium (Default) */
  --ds-input-md-height: 2.5rem;            /* 40px */
  --ds-input-md-padding-x: 0.75rem;        /* 12px */
  --ds-input-md-padding-y: 0.5rem;         /* 8px */
  --ds-input-md-font-size: 0.875rem;       /* 14px */
  --ds-input-md-line-height: 1.5rem;       /* 24px */
  --ds-input-md-icon-size: 1.25rem;        /* 20px */
  --ds-input-md-border-radius: var(--ds-radius-md);

  /* LG - Large */
  --ds-input-lg-height: 3rem;              /* 48px */
  --ds-input-lg-padding-x: 0.875rem;       /* 14px */
  --ds-input-lg-padding-y: 0.75rem;        /* 12px */
  --ds-input-lg-font-size: 1rem;           /* 16px */
  --ds-input-lg-line-height: 1.75rem;      /* 28px */
  --ds-input-lg-icon-size: 1.5rem;         /* 24px */
  --ds-input-lg-border-radius: var(--ds-radius-lg);

  /* XL - Extra Large */
  --ds-input-xl-height: 3.5rem;            /* 56px */
  --ds-input-xl-padding-x: 1rem;           /* 16px */
  --ds-input-xl-padding-y: 1rem;           /* 16px */
  --ds-input-xl-font-size: 1.125rem;       /* 18px */
  --ds-input-xl-line-height: 2rem;         /* 32px */
  --ds-input-xl-icon-size: 1.75rem;        /* 28px */
  --ds-input-xl-border-radius: var(--ds-radius-lg);

  /* Default size */
  --ds-input-default-height: var(--ds-input-md-height);
  --ds-input-default-padding-x: var(--ds-input-md-padding-x);
  --ds-input-default-padding-y: var(--ds-input-md-padding-y);
  --ds-input-default-font-size: var(--ds-input-md-font-size);

  /* Textarea specific */
  --ds-textarea-min-height: 6rem;       /* 96px */
  --ds-textarea-max-height: 24rem;      /* 384px */
  --textarea-min-height: var(--ds-textarea-min-height);
  --textarea-max-height: var(--ds-textarea-max-height);

  /* ========================================================================
     DEFAULT STATE - Base Appearance
     Default input styling
     ======================================================================== */
  --ds-input-bg: var(--ds-color-white);
  --ds-input-bg-hover: var(--ds-color-white);
  --ds-input-bg-focus: var(--ds-color-white);
  --ds-input-bg-disabled: var(--ds-color-neutral-50);

  --ds-input-color: var(--ds-color-neutral-900);
  --ds-input-color-placeholder: var(--ds-color-neutral-400);
  --ds-input-color-disabled: var(--ds-color-neutral-400);

  --ds-input-border-color: var(--ds-color-neutral-300);
  --ds-input-border-color-hover: var(--ds-color-neutral-400);
  --ds-input-border-color-focus: var(--ds-color-primary-500);
  --ds-input-border-color-disabled: var(--ds-color-neutral-200);

  /* Canonical runtime aliases. Kept separate from the legacy `*-color`
     names so BrandTheme/TenantTheme can override the complete control without
     an application selector. */
  --ds-input-border: var(--ds-input-border-color);
  --ds-input-border-hover: var(--ds-input-border-color-hover);
  --ds-input-border-focus: var(--ds-input-border-color-focus);
  --ds-input-border-disabled: var(--ds-input-border-color-disabled);

  --ds-input-border-width: 1px;
  --ds-input-border-width-focus: 2px;
  --ds-input-border-style: solid;
  --ds-input-radius: var(--ds-radius-input, var(--ds-radius-md));
  --ds-input-gap: var(--ds-input-affix-gap, var(--ds-spacing-2));
  --ds-input-message-gap: var(--ds-spacing-1);
  --ds-input-caret-color: var(--ds-input-border-focus);
  --ds-input-selection-bg: color-mix(in srgb, var(--ds-input-border-focus) 20%, transparent);
  --ds-input-selection-color: var(--ds-input-color);
  --ds-input-placeholder-opacity: 1;

  /* ========================================================================
     VARIANTS - Semantic States
     Success, warning, error variants
     ======================================================================== */

  /* Success variant */
  --ds-input-success-border-color: var(--ds-color-success-500);
  --ds-input-success-border-color-focus: var(--ds-color-success-600);
  --ds-input-success-shadow-focus: var(--ds-shadow-focus-ring-success);
  --ds-input-success-icon-color: var(--ds-color-success-500);
  --ds-input-success-border: var(--ds-input-success-border-color);
  --ds-input-success-bg: color-mix(in srgb, var(--ds-input-success-border) 4%, var(--ds-input-bg));

  /* Warning variant */
  --ds-input-warning-border-color: var(--ds-color-warning-500);
  --ds-input-warning-border-color-focus: var(--ds-color-warning-600);
  --ds-input-warning-shadow-focus: var(--ds-shadow-focus-ring-warning);
  --ds-input-warning-icon-color: var(--ds-color-warning-500);
  --ds-input-warning-border: var(--ds-input-warning-border-color);
  --ds-input-warning-bg: color-mix(in srgb, var(--ds-input-warning-border) 4%, var(--ds-input-bg));

  /* Error variant */
  --ds-input-error-border-color: var(--ds-color-error-500);
  --ds-input-error-border-color-focus: var(--ds-color-error-600);
  --ds-input-error-shadow-focus: var(--ds-shadow-focus-ring-error);
  --ds-input-error-icon-color: var(--ds-color-error-500);
  --ds-input-error-border: var(--ds-input-error-border-color);
  --ds-input-error-color: var(--ds-input-color);
  --ds-input-error-bg: color-mix(in srgb, var(--ds-input-error-border) 4%, var(--ds-input-bg));

  /* ========================================================================
     SHADOWS
     Focus and state shadows
     ======================================================================== */
  --ds-input-shadow-rest: var(--ds-shadow-input-rest);
  --ds-input-shadow-hover: var(--ds-input-shadow-rest);
  --ds-input-shadow-focus: var(--ds-shadow-input-focus);
  --ds-input-shadow-error-focus: var(--ds-shadow-input-error);

  /* ========================================================================
     ADDONS - Prefix/Suffix
     Settings for input addons and affixes
     ======================================================================== */
  --ds-input-addon-bg: var(--ds-color-neutral-50);
  --ds-input-addon-color: var(--ds-color-neutral-600);
  --ds-input-addon-border-color: var(--ds-color-neutral-300);
  --ds-input-addon-border: var(--ds-input-addon-border-color);
  --ds-input-addon-padding-x: 0.75rem;

  --ds-input-affix-gap: 0.5rem;            /* Gap between affix and input text */
  --ds-input-affix-color: var(--ds-color-neutral-500);
  --ds-input-affix-size: var(--ds-input-md-icon-size);
  --ds-input-affix-size-compact: var(--ds-input-sm-icon-size);
  --ds-input-affix-padding-x: 0;
  --ds-input-affix-bg: transparent;
  --ds-input-affix-border: 0 solid transparent;
  --ds-input-affix-radius: var(--ds-radius-sm);

  /* ========================================================================
     ICONS - Prefix/Suffix Icons
     Settings for icons inside inputs
     ======================================================================== */
  --ds-input-icon-color: var(--ds-color-neutral-500);
  --ds-input-icon-color-hover: var(--ds-color-neutral-600);
  --ds-input-icon-gap: 0.5rem;

  /* ========================================================================
     CLEAR BUTTON
     Settings for the clear button (x icon)
     ======================================================================== */
  --ds-input-clear-size: 1rem;
  --ds-input-clear-color: var(--ds-color-neutral-400);
  --ds-input-clear-color-hover: var(--ds-color-neutral-600);
  --ds-input-clear-bg-hover: var(--ds-color-neutral-100);
  --ds-input-clear-bg: transparent;
  --ds-input-clear-border: 1px solid transparent;
  --ds-input-clear-border-hover: var(--ds-input-border);
  --ds-input-action-shadow-hover: none;
  --ds-input-action-focus-ring: var(--ds-focus-ring);
  --ds-input-clear-radius: var(--ds-radius-full);
  --ds-input-action-size: var(--ds-input-md-icon-size);
  --ds-input-action-radius: var(--ds-input-clear-radius);
  --ds-input-action-active-transform: scale(0.94);
  --ds-input-touch-target-min: 2.75rem;

  /* Loading */
  --ds-input-loading-size: var(--ds-input-md-icon-size);
  --ds-input-loading-stroke: 2;
  --ds-input-loading-color: var(--ds-input-border-focus);
  --ds-input-loading-duration: 720ms;

  /* ========================================================================
     PASSWORD TOGGLE
     Settings for password visibility toggle
     ======================================================================== */
  --ds-input-password-toggle-size: 1.25rem;
  --ds-input-password-toggle-color: var(--ds-color-neutral-500);
  --ds-input-password-toggle-color-hover: var(--ds-color-neutral-700);

  /* ========================================================================
     CHARACTER COUNT
     Settings for character counter
     ======================================================================== */
  --ds-input-count-color: var(--ds-color-neutral-500);
  --ds-input-count-color-warning: var(--ds-color-warning-600);
  --ds-input-count-color-error: var(--ds-color-error-600);
  --ds-input-count-font-size: var(--ds-font-size-sm);
  --ds-input-count-margin-top: 0.25rem;

  /* ========================================================================
     LABEL
     Settings for input labels
     ======================================================================== */
  --ds-input-label-color: var(--ds-color-neutral-700);
  --ds-input-label-color-disabled: var(--ds-color-neutral-400);
  --ds-input-label-font-size: var(--ds-font-size-sm);
  --ds-input-label-font-weight: var(--ds-font-weight-medium);
  --ds-input-label-margin-bottom: 0.375rem;
  --ds-input-label-required-color: var(--ds-color-error-500);

  /* ========================================================================
     HELPER TEXT
     Settings for helper/description text
     ======================================================================== */
  --ds-input-helper-color: var(--ds-color-neutral-600);
  --ds-input-helper-font-size: var(--ds-font-size-sm);
  --ds-input-helper-margin-top: 0.25rem;
  --ds-input-helper-line-height: var(--ds-line-height-snug);

  /* ========================================================================
     ERROR MESSAGE
     Settings for error message text
     ======================================================================== */
  --ds-input-error-message-color: var(--ds-color-error-600);
  --ds-input-error-message-font-size: var(--ds-font-size-sm);
  --ds-input-error-message-margin-top: 0.25rem;
  --ds-input-error-message-icon-size: 1rem;
  --ds-input-error-message-font-weight: var(--ds-font-weight-medium);

  /* ========================================================================
     SUCCESS MESSAGE
     Settings for success message text
     ======================================================================== */
  --ds-input-success-message-color: var(--ds-color-success-600);
  --ds-input-success-message-font-size: var(--ds-font-size-sm);
  --ds-input-success-message-margin-top: 0.25rem;

  /* ========================================================================
     GROUP/COMPACT
     Settings for input groups
     ======================================================================== */
  --ds-input-group-gap: 0;
  --ds-input-group-gap-separated: var(--ds-spacing-2);
  --ds-input-group-overlap: -1px;
  --ds-input-group-min-item-width: 12rem;
  --ds-input-group-border-radius-first: var(--ds-radius-md) 0 0 var(--ds-radius-md);
  --ds-input-group-border-radius-last: 0 var(--ds-radius-md) var(--ds-radius-md) 0;
  --ds-input-group-border-radius-middle: 0;

  /* ========================================================================
     SEARCH INPUT
     Specific settings for search inputs
     ======================================================================== */
  --ds-input-search-icon-color: var(--ds-color-neutral-500);
  --ds-input-search-clear-color: var(--ds-color-neutral-400);

  /* ========================================================================
     NUMBER INPUT
     Specific settings for number inputs
     ======================================================================== */
  --ds-input-number-controls-width: 1.5rem;
  --ds-input-number-controls-bg: var(--ds-color-neutral-50);
  --ds-input-number-controls-bg-hover: var(--ds-color-neutral-100);
  --ds-input-number-controls-color: var(--ds-color-neutral-600);
  --ds-input-number-controls-border-color: var(--ds-color-neutral-300);

  /* ========================================================================
     FILE INPUT
     Specific settings for file inputs
     ======================================================================== */
  --ds-input-file-button-bg: var(--ds-color-neutral-100);
  --ds-input-file-button-bg-hover: var(--ds-color-neutral-200);
  --ds-input-file-button-color: var(--ds-color-neutral-700);
  --ds-input-file-button-padding: 0.5rem 1rem;

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */
  --ds-input-transition-duration: 0.2s;
  --ds-input-transition-timing: ease-in-out;
  --ds-input-transition: all var(--ds-input-transition-duration) var(--ds-input-transition-timing);

  /* FormField composition */
  --ds-form-field-gap: var(--ds-input-label-margin-bottom);
  --ds-form-field-horizontal-gap: var(--ds-spacing-4);
  --ds-form-field-label-offset-y: 0;
  --ds-form-field-required-gap: 0.25em;
  --ds-form-field-disabled-opacity: var(--ds-input-disabled-opacity);

  /* Textarea composition */
  --ds-textarea-padding-x: var(--ds-input-md-padding-x);
  --ds-textarea-padding-y: var(--ds-input-md-padding-y);
  --ds-textarea-radius: var(--ds-radius-input);
  --ds-textarea-resize: vertical;

  /* ========================================================================
     TYPOGRAPHY
     Font settings for input text
     ======================================================================== */
  --ds-input-font-family: var(--ds-font-family-base);
  --ds-input-font-weight: var(--ds-font-weight-normal);
  --ds-input-letter-spacing: normal;

  /* ========================================================================
     DISABLED STATE
     Appearance when disabled
     ======================================================================== */
  --ds-input-disabled-opacity: 0.6;
  --ds-input-disabled-cursor: not-allowed;

  /* ========================================================================
     READ-ONLY STATE
     Appearance when read-only
     ======================================================================== */
  --ds-input-readonly-bg: var(--ds-color-neutral-50);
  --ds-input-readonly-color: var(--ds-input-color);
  --ds-input-readonly-border: var(--ds-input-border);
  --ds-input-readonly-cursor: default;
  --ds-input-readonly-border-style: dashed;

  /* ========================================================================
     AUTOFILL
     Browser autofill appearance
     ======================================================================== */
  --ds-input-autofill-bg: var(--ds-color-primary-50);
  --ds-input-autofill-color: var(--ds-color-neutral-900);
  --ds-input-autofill-caret: var(--ds-input-caret-color);
}

}
@layer rottay-components {
/**
 * Card Component Tokens - Rottay Design System
 *
 * Design tokens specific to the Card component.
 * Includes sizes, variants, states, and compositional properties.
 */

:root {
  /* ========================================================================
     SIZES - Card Padding Variants
     Three size variants for different card densities
     ======================================================================== */
  --ds-card-sm-padding: 0.75rem; /* 12px */
  --ds-card-md-padding: 1rem; /* 16px - Default */
  --ds-card-lg-padding: 1.5rem; /* 24px */
  --ds-card-xl-padding: 2rem; /* 32px */

  --ds-card-default-padding: var(--ds-card-md-padding);

  /* ========================================================================
     BACKGROUND & COLORS
     Base appearance for cards
     ======================================================================== */
  --ds-card-bg: var(--ds-color-white);
  --ds-card-bg-hover: var(--ds-color-neutral-50);
  --ds-card-bg-active: var(--ds-color-neutral-100);
  --ds-card-bg-selected: color-mix(
    in srgb,
    var(--ds-color-primary) 8%,
    var(--ds-card-bg)
  );
  --ds-card-bg-disabled: var(--ds-color-neutral-50);

  --ds-card-color: var(--ds-color-neutral-900);
  --ds-card-color-hover: var(--ds-card-color);
  --ds-card-color-active: var(--ds-card-color);
  --ds-card-color-selected: var(--ds-card-color);
  --ds-card-color-disabled: var(--ds-color-text-disabled);
  --ds-card-color-muted: var(--ds-color-neutral-600);

  /* ========================================================================
     BORDERS
     Border styling for cards
     ======================================================================== */
  --ds-card-border-width: 1px;
  --ds-card-border-color: var(--ds-color-neutral-200);
  --ds-card-border-color-hover: var(--ds-color-neutral-300);
  --ds-card-border-color-active: var(--ds-card-border-color-hover);
  --ds-card-border-color-selected: color-mix(
    in srgb,
    var(--ds-color-primary) 52%,
    var(--ds-card-border-color)
  );
  --ds-card-border-color-disabled: color-mix(
    in srgb,
    var(--ds-card-border-color) 58%,
    transparent
  );
  --ds-card-border-active: var(--ds-card-border-color-active);
  --ds-card-border-selected: var(--ds-card-border-color-selected);
  --ds-card-border-disabled: var(--ds-card-border-color-disabled);
  --ds-card-border-style: solid;
  --ds-card-border-radius: var(--ds-radius-lg);
  --ds-card-radius: var(--ds-card-border-radius);
  --ds-card-radius-sm: var(--ds-radius-sm);
  --ds-card-radius-lg: var(--ds-radius-xl);
  --ds-card-radius-xl: var(--ds-radius-2xl);

  /* Borderless variant */
  --ds-card-borderless-border-width: 0;

  /* ========================================================================
     SHADOWS
     Elevation levels for cards
     ======================================================================== */
  --ds-card-shadow-none: none;
  --ds-card-shadow-sm: var(--ds-shadow-sm);
  --ds-card-shadow-md: var(--ds-shadow-md);
  --ds-card-shadow-lg: var(--ds-shadow-lg);
  --ds-card-shadow-xl: var(--ds-shadow-xl);

  /* Interactive shadows */
  --ds-card-shadow-hover: var(--ds-shadow-card-hover);
  --ds-card-shadow-active: var(--ds-shadow-card-active);
  --ds-card-shadow-selected: var(--ds-shadow-focus-ring);

  /* Default shadow */
  --ds-card-shadow-default: var(--ds-card-shadow-sm);

  /* ========================================================================
     HEADER
     Card header section styling
     ======================================================================== */
  --ds-card-header-padding: var(--ds-card-default-padding);
  --ds-card-header-padding-sm: var(--ds-spacing-3, 12px)
    var(--ds-spacing-4, 16px);
  --ds-card-header-padding-lg: var(--ds-spacing-5, 20px)
    var(--ds-spacing-6, 24px);
  --ds-card-header-gap: var(--ds-spacing-3, 12px);
  --ds-card-header-padding-bottom: calc(var(--ds-card-default-padding) * 0.75);
  --ds-card-header-border-width: 1px;
  --ds-card-header-border-color: var(--ds-color-neutral-200);
  --ds-card-header-bg: transparent;
  --ds-card-header-min-height: 4rem;
  --ds-card-header-copy-max-width: 68ch;
  --ds-card-header-eyebrow-size: 0.625rem;
  --ds-card-header-eyebrow-tracking: 0.11em;
  --ds-card-header-icon-size: 2.25rem;
  --ds-card-header-icon-radius: var(--ds-radius-lg);
  --ds-card-header-icon-bg: var(
    --ds-surface-icon-bg,
    color-mix(in srgb, var(--ds-color-primary) 9%, var(--ds-card-bg))
  );
  --ds-card-header-icon-border: color-mix(
    in srgb,
    var(--ds-color-primary) 20%,
    var(--ds-card-border-color)
  );
  --ds-card-header-icon-color: var(--ds-color-primary);
  --ds-card-header-extra-bg: color-mix(
    in srgb,
    var(--ds-card-bg) 94%,
    var(--ds-color-primary)
  );
  --ds-card-header-extra-border: var(--ds-card-header-border-color);
  --ds-card-header-extra-radius: var(--ds-radius-lg);
  --ds-card-header-extra-padding: 3px;

  /* Header title */
  --ds-card-title-font-size: var(--ds-font-size-lg);
  --ds-card-title-font-weight: var(--ds-font-weight-semibold);
  --ds-card-title-line-height: var(--ds-line-height-tight);
  --ds-card-title-letter-spacing: var(--ds-letter-spacing-heading);
  --ds-card-title-color: var(--ds-color-neutral-900);

  /* Header subtitle */
  --ds-card-subtitle-font-size: var(--ds-font-size-sm);
  --ds-card-subtitle-color: var(--ds-color-neutral-600);
  --ds-card-subtitle-margin-top: 0.25rem;

  /* Header actions */
  --ds-card-header-actions-gap: 0.5rem;

  /* ========================================================================
     BODY
     Card content area styling
     ======================================================================== */
  --ds-card-body-padding: var(--ds-card-default-padding);
  --ds-card-body-padding-sm: var(--ds-spacing-3, 12px)
    var(--ds-spacing-4, 16px);
  --ds-card-body-padding-lg: var(--ds-spacing-5, 20px)
    var(--ds-spacing-6, 24px);
  --ds-card-body-color: var(--ds-color-neutral-700);
  --ds-card-body-font-size: var(--ds-font-size-base);
  --ds-card-body-line-height: var(--ds-line-height-normal);

  /* ========================================================================
     FOOTER
     Card footer section styling
     ======================================================================== */
  --ds-card-footer-padding: var(--ds-card-default-padding);
  --ds-card-footer-padding-sm: var(--ds-spacing-3, 12px)
    var(--ds-spacing-4, 16px);
  --ds-card-footer-padding-lg: var(--ds-spacing-5, 20px)
    var(--ds-spacing-6, 24px);
  --ds-card-footer-padding-top: calc(var(--ds-card-default-padding) * 0.75);
  --ds-card-footer-border-width: 1px;
  --ds-card-footer-border-color: var(--ds-color-neutral-200);
  --ds-card-footer-bg: transparent;
  --ds-card-footer-color: var(--ds-color-neutral-600);

  /* Footer actions */
  --ds-card-footer-actions-gap: 0.5rem;
  --ds-card-footer-actions-justify: flex-end;
  --ds-card-actions-gap: var(--ds-spacing-2, 8px);
  --ds-card-actions-margin-top: var(--ds-spacing-4, 16px);
  --ds-card-actions-padding-top: var(--ds-spacing-4, 16px);

  /* ========================================================================
     MEDIA/IMAGE
     Card image and media styling
     ======================================================================== */
  --ds-card-media-border-radius-top: var(--ds-card-border-radius);
  --ds-card-media-border-radius-bottom: 0;
  --ds-card-media-aspect-ratio: 16 / 9;
  --ds-card-media-object-fit: cover;
  --ds-card-image-height: 12.5rem;

  /* Cover variant (full background image) */
  --ds-card-cover-min-height: 12rem; /* 192px */
  --ds-card-cover-overlay-bg: linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0) 0%,
    rgba(0, 0, 0, 0.6) 100%
  );
  --ds-card-cover-content-color: var(--ds-color-white);
  --ds-card-cover-inline-size: 12rem;
  --ds-card-cover-inline-min-size: 9rem;
  --ds-card-cover-block-min-size: 10rem;
  --ds-card-cover-aspect-ratio: var(--ds-card-media-aspect-ratio);
  --ds-card-cover-object-position: center;
  --ds-card-cover-object-fit: cover;
  --ds-card-body-inline-min-size: 16rem;

  /* Image loading/error anatomy */
  --ds-card-image-loading-track: var(--ds-color-neutral-200);
  --ds-card-image-loading-active: var(--ds-color-primary);
  --ds-card-image-loading-size: 2.5rem;
  --ds-card-image-loading-stroke: 3px;
  --ds-card-image-loading-duration: var(--ds-motion-glacial);
  --ds-card-image-error-icon-size: 3rem;

  /* Root loading anatomy */
  --ds-card-spinner-size: 1.5rem;
  --ds-card-spinner-stroke: 2px;
  --ds-card-spinner-track: var(--ds-color-border);
  --ds-card-spinner-color: var(--ds-color-primary);
  --ds-card-spinner-duration: var(--ds-motion-glacial);

  /* ========================================================================
     VARIANTS
     Different card visual styles
     ======================================================================== */

  /* Default variant */
  --ds-card-default-bg: var(--ds-card-bg);
  --ds-card-default-border-color: var(--ds-card-border-color);
  --ds-card-default-shadow: var(--ds-card-shadow-default);

  /* Bordered variant (emphasized border, no shadow) */
  --ds-card-bordered-bg: var(--ds-card-bg);
  --ds-card-bordered-border-width: var(--ds-card-border-width);
  --ds-card-bordered-border-color: var(--ds-card-border, var(--ds-card-border-color));
  --ds-card-bordered-shadow: none;

  /* Flat variant (no border, no shadow) */
  --ds-card-flat-bg: var(--ds-surface-panel, var(--ds-card-bg));
  --ds-card-flat-border-width: 0;
  --ds-card-flat-shadow: none;

  /* Elevated variant (strong shadow, no border) */
  --ds-card-elevated-bg: var(--ds-card-bg);
  --ds-card-elevated-border-width: 0;
  --ds-card-elevated-shadow: var(--ds-card-shadow, var(--ds-card-shadow-md));
  --ds-card-elevated-shadow-hover: var(--ds-card-shadow-hover, var(--ds-card-shadow-lg));

  /* Ghost variant (transparent background) */
  --ds-card-ghost-bg: transparent;
  --ds-card-ghost-border-color: var(--ds-color-neutral-200);
  --ds-card-ghost-shadow: none;

  /* ========================================================================
     INTERACTIVE STATES
     Clickable/hoverable cards
     ======================================================================== */
  --ds-card-interactive-cursor: pointer;
  --ds-card-interactive-transform-hover: translateY(-1px);
  --ds-card-active-transform: translateY(0) scale(0.995);
  --ds-card-interactive-transition: var(--ds-transition-card);
  --ds-card-surface-gradient: var(--ds-gradient-surface, none);
  --ds-card-texture: var(--ds-premium-card-grid-bg);
  --ds-card-texture-size: var(--ds-premium-card-grid-size)
    var(--ds-premium-card-grid-size);
  --ds-card-texture-opacity: calc(var(--ds-effect-intensity, 1) * 0.1);
  --ds-card-overlay: var(--ds-premium-card-overlay);
  --ds-card-state-overlay: linear-gradient(
    118deg,
    color-mix(in srgb, var(--ds-color-primary) 10%, transparent),
    transparent 42%,
    color-mix(in srgb, var(--ds-color-bg-elevated) 58%, transparent)
  );
  --ds-card-state-overlay-hover-opacity: 0.42;
  --ds-card-state-overlay-active-opacity: 0.68;
  --ds-card-state-overlay-selected-opacity: 0.3;

  /* ========================================================================
     PREMIUM WHITE-LABEL CARD FOUNDATION
     Shared contract for signal, workspace, compact, tall, and collection cards
     ======================================================================== */
  --ds-premium-card-radius: var(--ds-card-radius, var(--ds-radius-lg));
  --ds-premium-card-padding: var(--ds-card-md-padding);
  --ds-premium-card-gap: var(--ds-spacing-3, 12px);
  --ds-premium-card-min-height: auto;
  --ds-premium-card-grid-size: 22px;
  --ds-premium-card-grid-line: color-mix(
    in srgb,
    var(--ds-color-primary) 7%,
    transparent
  );
  --ds-premium-card-grid-bg: linear-gradient(
      var(--ds-premium-card-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      var(--ds-premium-card-grid-line) 1px,
      transparent 1px
    );
  --ds-premium-card-bg: var(--ds-material-card-background, var(--ds-card-bg));
  --ds-premium-card-bg-hover: var(
    --ds-material-card-background-hover,
    color-mix(
      in srgb,
      var(--ds-color-primary) 4%,
      var(--ds-material-card-background, var(--ds-card-bg-hover))
    )
  );
  --ds-premium-card-bg-active: var(
    --ds-material-card-background-active,
    color-mix(
      in srgb,
      var(--ds-color-primary) 7%,
      var(--ds-material-card-background, var(--ds-card-bg))
    )
  );
  --ds-premium-card-bg-selected: var(
    --ds-material-card-background-selected,
    color-mix(
      in srgb,
      var(--ds-color-primary) 9%,
      var(--ds-material-card-background, var(--ds-card-bg))
    )
  );
  --ds-premium-card-bg-disabled: var(
    --ds-material-card-background-disabled,
    color-mix(
      in srgb,
      var(--ds-material-card-background, var(--ds-card-bg)) 82%,
      var(--ds-surface-panel-bg)
    )
  );
  --ds-premium-card-glass-bg: color-mix(
    in srgb,
    var(--ds-material-card-background, var(--ds-card-bg)) 86%,
    transparent
  );
  --ds-premium-card-overlay: linear-gradient(
    180deg,
    color-mix(in srgb, var(--ds-color-primary) 4%, transparent),
    transparent 48%
  );
  --ds-premium-card-border: var(
    --ds-material-card-border,
    color-mix(in srgb, var(--ds-color-primary) 10%, var(--ds-card-border-color))
  );
  --ds-premium-card-border-hover: var(
    --ds-material-card-border-hover,
    color-mix(
      in srgb,
      var(--ds-color-primary) 24%,
      var(--ds-material-card-border-strong, var(--ds-card-border-color))
    )
  );
  --ds-premium-card-active-border: var(
    --ds-material-card-border-active,
    var(--ds-premium-card-border-hover)
  );
  --ds-premium-card-selected-border: var(
    --ds-material-card-border-selected,
    color-mix(
      in srgb,
      var(--ds-color-primary) 46%,
      var(--ds-material-card-border-strong, var(--ds-card-border-color))
    )
  );
  --ds-premium-card-disabled-border: var(
    --ds-material-card-border-disabled,
    color-mix(
      in srgb,
      var(--ds-material-card-border, var(--ds-card-border-color)) 58%,
      transparent
    )
  );
  --ds-premium-card-selected-ring: var(
    --ds-material-card-focus-ring,
    0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 12%, transparent)
  );
  --ds-premium-card-shadow: var(
    --ds-material-card-shadow,
    var(--ds-card-shadow-sm)
  );
  --ds-premium-card-shadow-hover: var(
    --ds-material-card-shadow-hover,
    var(--ds-card-shadow-hover)
  );
  --ds-premium-card-shadow-active: var(
    --ds-material-card-shadow-active,
    var(--ds-material-card-shadow, var(--ds-card-shadow-sm))
  );
  --ds-premium-card-shadow-selected: var(
    --ds-material-card-shadow-selected,
    var(
      --ds-material-card-focus-ring,
      0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 12%, transparent)
    )
  );
  --ds-premium-card-depth: 0 1px 2px
      color-mix(in srgb, var(--ds-card-color) 4%, transparent),
    0 12px 28px color-mix(in srgb, var(--ds-color-primary) 6%, transparent),
    var(
      --ds-material-card-highlight,
      inset 0 1px 0 color-mix(in srgb, var(--ds-card-bg) 72%, transparent)
    );
  --ds-premium-card-texture: var(--ds-material-card-texture, none);
  --ds-premium-card-sheen: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--ds-card-bg) 42%, transparent),
    transparent
  );
  --ds-premium-card-hover-transform: translateY(-2px) scale(1);
  --ds-premium-card-transition: background var(--ds-motion-feedback)
      var(--ds-motion-ease-enter),
    border-color var(--ds-motion-feedback) var(--ds-motion-ease-enter),
    box-shadow var(--ds-motion-feedback) var(--ds-motion-ease-enter),
    transform var(--ds-motion-feedback) var(--ds-motion-ease-enter);

  --ds-premium-card-icon-bg: var(
    --ds-surface-icon-bg,
    color-mix(in srgb, var(--ds-color-primary) 10%, var(--ds-card-bg))
  );
  --ds-premium-card-icon-border: var(
    --ds-surface-icon-border,
    color-mix(in srgb, var(--ds-color-primary) 20%, var(--ds-card-border-color))
  );
  --ds-premium-card-icon-color: var(--ds-color-primary);
  --ds-premium-card-title-color: var(--ds-card-title-color);
  --ds-premium-card-body-color: var(--ds-card-body-color);
  --ds-premium-card-label-color: var(--ds-card-color-muted);
  --ds-premium-card-value-color: var(--ds-card-color);
  --ds-premium-card-value-color-hover: var(--ds-color-primary);
  --ds-premium-card-number-min-width: 4ch;
  --ds-premium-card-number-font-variant: tabular-nums;
  --ds-premium-card-footer-bg: color-mix(
    in srgb,
    var(--ds-color-bg-secondary) 72%,
    var(--ds-card-bg)
  );
  --ds-premium-card-footer-border: color-mix(
    in srgb,
    var(--ds-card-border-color) 72%,
    transparent
  );
  --ds-premium-card-footer-color: var(--ds-card-footer-color);
  --ds-premium-card-status-bg: color-mix(
    in srgb,
    var(--ds-color-primary) 8%,
    var(--ds-card-bg)
  );
  --ds-premium-card-status-border: color-mix(
    in srgb,
    var(--ds-color-primary) 22%,
    var(--ds-card-border-color)
  );
  --ds-premium-card-status-color: var(--ds-color-primary);
  --ds-premium-card-action-bg: color-mix(
    in srgb,
    var(--ds-card-bg) 84%,
    transparent
  );
  --ds-premium-card-action-border: color-mix(
    in srgb,
    var(--ds-card-border-color) 82%,
    transparent
  );
  --ds-premium-card-action-color: var(--ds-color-primary);
  --ds-premium-card-meter-track: color-mix(
    in srgb,
    var(--ds-card-border-color) 48%,
    var(--ds-color-bg-secondary)
  );
  --ds-premium-card-meter-track-border: color-mix(
    in srgb,
    var(--ds-card-border-color) 82%,
    transparent
  );
  --ds-premium-card-meter-fill: linear-gradient(
    90deg,
    var(--ds-color-primary),
    var(--ds-color-secondary)
  );

  /* ========================================================================
     LOADING STATE
     Skeleton/loading appearance
     ======================================================================== */
  --ds-card-loading-bg: var(--ds-color-neutral-100);
  --ds-card-loading-shimmer: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.5) 50%,
    transparent 100%
  );
  --ds-card-loading-animation: ds-foundation-shimmer 2s infinite;
  --ds-card-loading-overlay-bg: color-mix(
    in srgb,
    var(--ds-surface-card) 62%,
    transparent
  );
  --ds-card-loading-backdrop-blur: 4px;
  --ds-card-loading-cover-opacity: 0.6;
  --ds-card-loading-skeleton-opacity: 0.52;
  --ds-card-skeleton-bg: var(--ds-surface-inset);
  --ds-card-skeleton-highlight: color-mix(
    in srgb,
    var(--ds-color-bg-elevated) 82%,
    transparent
  );
  --ds-card-skeleton-radius: var(--ds-radius-sm, 6px);
  --ds-card-skeleton-duration: var(--ds-motion-glacial);

  /* ========================================================================
     DIVIDER
     Internal card dividers
     ======================================================================== */
  --ds-card-divider-width: 1px;
  --ds-card-divider-color: var(--ds-color-neutral-200);
  --ds-card-divider-margin-y: 0.75rem;

  /* ========================================================================
     META/BADGE
     Small metadata and badges
     ======================================================================== */
  --ds-card-meta-font-size: var(--ds-font-size-sm);
  --ds-card-meta-color: var(--ds-color-neutral-500);
  --ds-card-meta-gap: 0.5rem;

  --ds-card-badge-margin-top: 0.5rem;

  /* ========================================================================
     GRID/LAYOUT
     Settings for card grids
     ======================================================================== */
  --ds-card-grid-gap: 1rem; /* 16px */
  --ds-card-grid-gap-sm: 0.75rem; /* 12px */
  --ds-card-grid-gap-lg: 1.5rem; /* 24px */

  /* Responsive columns */
  --ds-card-grid-columns-mobile: 1;
  --ds-card-grid-columns-tablet: 2;
  --ds-card-grid-columns-desktop: 3;
  --ds-card-grid-columns-wide: 4;

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */
  --ds-card-transition-duration: var(--ds-motion-feedback);
  --ds-card-transition-timing: var(--ds-motion-ease-enter);
  --ds-card-transition: background-color var(--ds-card-transition-duration)
      var(--ds-card-transition-timing),
    border-color var(--ds-card-transition-duration)
      var(--ds-card-transition-timing),
    color var(--ds-card-transition-duration) var(--ds-card-transition-timing),
    box-shadow var(--ds-card-transition-duration)
      var(--ds-card-transition-timing),
    transform var(--ds-card-transition-duration)
      var(--ds-card-transition-timing);

  /* ========================================================================
     SEMANTIC VARIANTS
     Colored cards for different contexts
     ======================================================================== */

  /* Primary card */
  --ds-card-primary-bg: var(--ds-color-primary-50);
  --ds-card-primary-border-color: var(--ds-color-primary-200);
  --ds-card-primary-title-color: var(--ds-color-primary-900);

  /* Success card */
  --ds-card-success-bg: var(--ds-color-success-50);
  --ds-card-success-border-color: var(--ds-color-success-200);
  --ds-card-success-title-color: var(--ds-color-success-900);

  /* Warning card */
  --ds-card-warning-bg: var(--ds-color-warning-50);
  --ds-card-warning-border-color: var(--ds-color-warning-200);
  --ds-card-warning-title-color: var(--ds-color-warning-900);

  /* Error card */
  --ds-card-error-bg: var(--ds-color-error-50);
  --ds-card-error-border-color: var(--ds-color-error-200);
  --ds-card-error-title-color: var(--ds-color-error-900);

  /* Info card */
  --ds-card-info-bg: var(--ds-color-info-50);
  --ds-card-info-border-color: var(--ds-color-info-200);
  --ds-card-info-title-color: var(--ds-color-info-900);

  /* ========================================================================
     ACCESSIBILITY
     Focus states and keyboard navigation
     ======================================================================== */
  --ds-card-focus-ring: var(--ds-shadow-focus-ring);
  --ds-card-focus-ring-color: var(--ds-focus-ring-color);
  --ds-card-focus-ring-width: var(--ds-focus-ring-width, 2px);
  --ds-card-focus-ring-offset: 2px;
  --ds-card-selected-outline-width: var(--ds-card-border-width);
  --ds-card-focus-outline: none;

  /* ========================================================================
     DISABLED STATE
     Appearance when disabled
     ======================================================================== */
  --ds-card-disabled-opacity: 0.5;
  --ds-card-disabled-cursor: not-allowed;
  --ds-card-disabled-bg: var(--ds-card-bg-disabled);
}

.ds-card {
  position: relative;
  isolation: isolate;
}

.ds-card.ds-card--modern::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
  background-image: var(--ds-card-texture), var(--ds-card-overlay);
  background-size: var(--ds-card-texture-size), auto;
  opacity: var(--ds-card-texture-opacity);
  mask-image: linear-gradient(
    180deg,
    var(--ds-color-text-primary),
    transparent 86%
  );
}

.ds-card.ds-card--modern[data-variant='ghost']::before,
[data-anatomy-card='ghost'] .ds-card.ds-card--modern::before {
  opacity: 0;
}

@media (forced-colors: active) {
  .ds-card.ds-card--modern::before {
    display: none;
  }
}

.ds-card > * {
  position: relative;
  z-index: 1;
}

.ds-card--interactive {
  transition: var(--ds-premium-card-transition);
}

}
@layer rottay-components {
/**
 * Modal Component Tokens - Rottay Design System
 *
 * Design tokens specific to Modal/Dialog components.
 * Includes sizes, variants, animations, and overlay properties.
 */

:root {
  /* ========================================================================
     SIZES - Modal Width Variants
     Ten size variants for different content amounts
     ======================================================================== */
  --ds-modal-xs-width: 320px;              /* Extra small */
  --ds-modal-sm-width: 400px;              /* Small */
  --ds-modal-md-width: 500px;              /* Medium - Default */
  --ds-modal-lg-width: 640px;              /* Large */
  --ds-modal-xl-width: 800px;              /* Extra large */
  --ds-modal-2xl-width: 960px;             /* 2X large */
  --ds-modal-3xl-width: 1120px;            /* 3X large */
  --ds-modal-4xl-width: 1280px;            /* 4X large */
  --ds-modal-5xl-width: 1440px;            /* 5X large */
  --ds-modal-full-width: 100%;             /* Full width */

  /* Height variants per size */
  --ds-modal-xs-max-height: 90vh;
  --ds-modal-sm-max-height: 90vh;
  --ds-modal-md-max-height: 85vh;
  --ds-modal-lg-max-height: 85vh;
  --ds-modal-xl-max-height: 80vh;
  --ds-modal-2xl-max-height: 80vh;
  --ds-modal-3xl-max-height: 80vh;
  --ds-modal-4xl-max-height: 80vh;
  --ds-modal-5xl-max-height: 80vh;
  --ds-modal-full-max-height: 100vh;

  /* Legacy height variants */
  --ds-modal-max-height: calc(100vh - 4rem); /* Max height with margins */
  --ds-modal-full-height: calc(100vh - 2rem);

  /* Default size */
  --ds-modal-default-width: var(--ds-modal-md-width);

  /* ========================================================================
     OVERLAY/BACKDROP
     Background overlay behind the modal
     ======================================================================== */
  --ds-modal-overlay-bg: var(--ds-color-alpha-black-50);
  --ds-modal-overlay-backdrop-filter: blur(4px);
  --ds-modal-overlay-z-index: var(--ds-z-index-modal-backdrop);

  /* ========================================================================
     CONTAINER
     Modal container positioning and appearance
     ======================================================================== */
  --ds-modal-z-index: var(--ds-z-index-modal-content);
  --ds-modal-margin: 2rem;                 /* Margin from viewport edges */
  --ds-modal-margin-mobile: 1rem;

  /* ========================================================================
     CONTENT
     Main modal content area
     ======================================================================== */
  --ds-modal-bg: var(--ds-color-white);
  --ds-modal-color: var(--ds-color-neutral-900);
  --ds-modal-border-radius: var(--ds-radius-xl);
  --ds-modal-border-width: 0;
  --ds-modal-border-color: transparent;
  --ds-modal-shadow: var(--ds-shadow-modal);

  /* Padding variants */
  --ds-modal-padding: 1.5rem;              /* 24px - Default */
  --ds-modal-padding-none: 0;              /* No padding */
  --ds-modal-padding-sm: 12px;             /* Small: 12px */
  --ds-modal-padding-md: 16px;             /* Medium: 16px */
  --ds-modal-padding-lg: 24px;             /* Large: 24px */

  /* Border radius variants */
  --ds-modal-radius-none: 0;               /* No border radius */
  --ds-modal-radius-sm: 4px;               /* Small: 4px */
  --ds-modal-radius-md: 8px;               /* Medium: 8px */
  --ds-modal-radius-lg: 12px;              /* Large: 12px */
  --ds-modal-radius-xl: 16px;              /* Extra large: 16px */

  /* ========================================================================
     HEADER
     Modal header section
     ======================================================================== */
  --ds-modal-header-padding: var(--ds-modal-padding);
  --ds-modal-header-padding-bottom: 1rem;
  --ds-modal-header-border-width: 1px;
  --ds-modal-header-border-color: var(--ds-color-neutral-200);
  --ds-modal-header-bg: transparent;

  /* Title */
  --ds-modal-title-font-size: var(--ds-font-size-xl);
  --ds-modal-title-font-weight: var(--ds-font-weight-semibold);
  --ds-modal-title-line-height: var(--ds-line-height-tight);
  --ds-modal-title-color: var(--ds-color-neutral-900);

  /* Subtitle */
  --ds-modal-subtitle-font-size: var(--ds-font-size-sm);
  --ds-modal-subtitle-color: var(--ds-color-neutral-600);
  --ds-modal-subtitle-margin-top: 0.25rem;

  /* ========================================================================
     BODY
     Modal content area
     ======================================================================== */
  --ds-modal-body-padding: var(--ds-modal-padding);
  --ds-modal-body-padding-y: 1.5rem;
  --ds-modal-body-color: var(--ds-color-neutral-700);
  --ds-modal-body-font-size: var(--ds-font-size-base);
  --ds-modal-body-line-height: var(--ds-line-height-normal);
  --ds-modal-body-max-height: calc(100vh - 12rem); /* Scrollable body */

  /* ========================================================================
     FOOTER
     Modal footer with actions
     ======================================================================== */
  --ds-modal-footer-padding: var(--ds-modal-padding);
  --ds-modal-footer-padding-top: 1rem;
  --ds-modal-footer-border-width: 1px;
  --ds-modal-footer-border-color: var(--ds-color-neutral-200);
  --ds-modal-footer-bg: var(--ds-color-neutral-50);
  --ds-modal-footer-justify: flex-end;
  --ds-modal-footer-gap: 0.75rem;

  /* ========================================================================
     CLOSE BUTTON
     X button to close modal
     ======================================================================== */
  --ds-modal-close-size: 2rem;             /* 32px */
  --ds-modal-close-icon-size: 1.25rem;     /* 20px */
  --ds-modal-close-color: var(--ds-color-neutral-500);
  --ds-modal-close-color-hover: var(--ds-color-neutral-700);
  --ds-modal-close-bg-hover: var(--ds-color-neutral-100);
  --ds-modal-close-border-radius: var(--ds-radius-md);
  --ds-modal-close-position-top: 1rem;
  --ds-modal-close-position-right: 1rem;

  /* ========================================================================
     ANIMATIONS - Entry/Exit
     Modal open/close animations
     ======================================================================== */

  /* Fade animation */
  --ds-modal-fade-duration: 0.3s;
  --ds-modal-fade-timing: ease-out;

  /* Scale animation */
  --ds-modal-scale-from: 0.95;
  --ds-modal-scale-to: 1;
  --ds-modal-scale-duration: 0.3s;
  --ds-modal-scale-timing: cubic-bezier(0.16, 1, 0.3, 1);

  /* Slide from top */
  --ds-modal-slide-top-from: -2rem;
  --ds-modal-slide-top-to: 0;
  --ds-modal-slide-duration: 0.3s;
  --ds-modal-slide-timing: cubic-bezier(0.16, 1, 0.3, 1);

  /* Slide from bottom (mobile) */
  --ds-modal-slide-bottom-from: 100%;
  --ds-modal-slide-bottom-to: 0;

  /* Combined transition */
  --ds-modal-transition: all var(--ds-modal-fade-duration) var(--ds-modal-fade-timing);

  /* ========================================================================
     VARIANTS - Modal Types
     Different modal styles for various use cases
     ======================================================================== */

  /* Centered modal (default) */
  --ds-modal-centered-align: center;
  --ds-modal-centered-justify: center;

  /* Top modal */
  --ds-modal-top-align: flex-start;
  --ds-modal-top-justify: center;
  --ds-modal-top-margin-top: 4rem;

  /* Drawer/Side modal */
  --ds-modal-drawer-width: 24rem;          /* 384px */
  --ds-modal-drawer-max-width: 90vw;
  --ds-modal-drawer-height: 100vh;
  --ds-modal-drawer-border-radius: 0;

  /* Bottom sheet (mobile) */
  --ds-modal-bottom-sheet-width: 100%;
  --ds-modal-bottom-sheet-max-height: 90vh;
  --ds-modal-bottom-sheet-border-radius-top: var(--ds-radius-2xl);
  --ds-modal-bottom-sheet-border-radius-bottom: 0;

  /* ========================================================================
     SEMANTIC VARIANTS
     Colored modals for different contexts
     ======================================================================== */

  /* Confirmation modal */
  --ds-modal-confirm-icon-color: var(--ds-color-primary-500);
  --ds-modal-confirm-icon-bg: var(--ds-color-primary-100);

  /* Success modal */
  --ds-modal-success-icon-color: var(--ds-color-success-500);
  --ds-modal-success-icon-bg: var(--ds-color-success-100);

  /* Warning modal */
  --ds-modal-warning-icon-color: var(--ds-color-warning-500);
  --ds-modal-warning-icon-bg: var(--ds-color-warning-100);

  /* Error/Destructive modal */
  --ds-modal-error-icon-color: var(--ds-color-error-500);
  --ds-modal-error-icon-bg: var(--ds-color-error-100);

  /* Info modal */
  --ds-modal-info-icon-color: var(--ds-color-info-500);
  --ds-modal-info-icon-bg: var(--ds-color-info-100);

  /* ========================================================================
     ICON
     Icon in header or content
     ======================================================================== */
  --ds-modal-icon-size: 3rem;              /* 48px */
  --ds-modal-icon-size-sm: 2rem;           /* 32px */
  --ds-modal-icon-size-lg: 4rem;           /* 64px */
  --ds-modal-icon-margin-bottom: 1rem;

  /* ========================================================================
     SCROLLABLE CONTENT
     Settings for scrolling modal body
     ======================================================================== */
  --ds-modal-scroll-padding: 0.5rem;
  --ds-modal-scroll-shadow-top: inset 0 8px 8px -8px rgba(0, 0, 0, 0.1);
  --ds-modal-scroll-shadow-bottom: inset 0 -8px 8px -8px rgba(0, 0, 0, 0.1);

  /* ========================================================================
     LOADING STATE
     Modal loading indicator
     ======================================================================== */
  --ds-modal-loading-overlay-bg: var(--ds-color-alpha-white-80);
  --ds-modal-loading-spinner-color: var(--ds-color-primary-500);
  --ds-modal-loading-spinner-size: 2rem;

  /* ========================================================================
     NESTED MODALS
     Stacking multiple modals
     ======================================================================== */
  --ds-modal-nested-z-index-offset: 10;
  --ds-modal-nested-overlay-bg: var(--ds-color-alpha-black-30);

  /* ========================================================================
     ACCESSIBILITY
     Focus trap and keyboard navigation
     ======================================================================== */
  --ds-modal-focus-ring: var(--ds-shadow-focus-ring);
  --ds-modal-focus-ring-offset: 2px;
  --ds-modal-focus-outline: none;

  /* ========================================================================
     RESPONSIVE
     Mobile-specific adjustments
     ======================================================================== */
  --ds-modal-mobile-width: calc(100vw - 2rem);
  --ds-modal-mobile-max-height: calc(100vh - 2rem);
  --ds-modal-mobile-padding: 1rem;
  --ds-modal-mobile-border-radius: var(--ds-radius-lg);

  /* ========================================================================
     DIVIDER
     Internal modal dividers
     ======================================================================== */
  --ds-modal-divider-width: 1px;
  --ds-modal-divider-color: var(--ds-color-neutral-200);
  --ds-modal-divider-margin-y: 1rem;

  /* ========================================================================
     BACKDROP BLUR
     Glassmorphism effect
     ======================================================================== */
  --ds-modal-glass-bg: rgba(255, 255, 255, 0.9);
  --ds-modal-glass-backdrop-filter: blur(12px) saturate(180%);
  --ds-modal-glass-border: 1px solid rgba(255, 255, 255, 0.3);
}

