  --ds-select-xs-border-radius: var(--ds-radius-sm);

  /* SM - Small */
  --ds-select-sm-height: 2rem;              /* 32px */
  --ds-select-sm-font-size: 0.875rem;       /* 14px */
  --ds-select-sm-padding: 0 0.625rem;       /* 0 10px */
  --ds-select-sm-padding-x: 0.625rem;       /* 10px */
  --ds-select-sm-icon-size: 0.875rem;       /* 14px */
