  /* MD - Medium (Default) */
  --ds-select-md-height: 2.5rem;            /* 40px */
  --ds-select-md-font-size: 0.875rem;       /* 14px */
  --ds-select-md-padding: 0 0.75rem;        /* 0 12px */
  --ds-select-md-padding-x: 0.75rem;        /* 12px */
  --ds-select-md-icon-size: 1rem;           /* 16px */
  --ds-select-md-border-radius: var(--ds-radius-md);

  /* LG - Large */
  --ds-select-lg-height: 3rem;              /* 48px */
  --ds-select-lg-font-size: 1rem;           /* 16px */
  --ds-select-lg-padding: 0 0.875rem;       /* 0 14px */
  --ds-select-lg-padding-x: 0.875rem;       /* 14px */
  --ds-select-lg-icon-size: 1.25rem;        /* 20px */
  --ds-select-lg-border-radius: var(--ds-radius-lg);

  /* XL - Extra Large */
  --ds-select-xl-height: 3.5rem;            /* 56px */
  --ds-select-xl-font-size: 1.125rem;       /* 18px */
  --ds-select-xl-padding: 0 1rem;           /* 0 16px */
  --ds-select-xl-padding-x: 1rem;           /* 16px */
  --ds-select-xl-icon-size: 1.5rem;         /* 24px */
  --ds-select-xl-border-radius: var(--ds-radius-lg);

  /* Default size */
  --ds-select-default-height: var(--ds-select-md-height);
  --ds-select-default-font-size: var(--ds-select-md-font-size);
  --ds-select-default-padding: var(--ds-select-md-padding);
  --ds-select-default-padding-x: var(--ds-select-md-padding-x);

  /* ========================================================================
     DEFAULT STATE - Base Appearance
     Default select styling
     ======================================================================== */
  /* Derived, not white. `--ds-surface-control` is declared on the same element
     by the tenant scope, and a var() reference resolves against the computed
     value regardless of rule order, so this follows the tenant. A literal here
     outranked the tenant for every customer that did not hand-write a select
     colour into its artifact, which is all of them. */
  --ds-select-bg: var(--ds-surface-control, var(--ds-color-bg-input, var(--ds-color-white)));
  --ds-select-bg-hover: var(--ds-surface-control, var(--ds-color-bg-input, var(--ds-color-white)));
  --ds-select-bg-focus: var(--ds-surface-control, var(--ds-color-bg-input, var(--ds-color-white)));
  --ds-select-bg-disabled: var(--ds-color-neutral-50);

  --ds-select-color: var(--ds-color-neutral-900);
  --ds-select-color-placeholder: var(--ds-color-neutral-400);
  --ds-select-color-disabled: var(--ds-color-neutral-400);

  --ds-select-border-color: var(--ds-color-neutral-300);
  --ds-select-border-color-hover: var(--ds-color-neutral-400);
  --ds-select-border-color-focus: var(--ds-color-primary-500);
  --ds-select-border-color-disabled: var(--ds-color-neutral-200);

