  --ds-signal-card-shadow-hover: var(--ds-premium-card-shadow-hover);
  --ds-signal-card-radius: var(--ds-premium-card-radius);
  --ds-signal-card-padding: var(--ds-premium-card-padding);
  --ds-signal-card-grid-bg: var(--ds-premium-card-grid-bg);
  --ds-signal-card-icon-bg: var(--ds-premium-card-icon-bg);
  --ds-signal-card-icon-border: var(--ds-premium-card-icon-border);
  --ds-signal-card-title-color: var(--ds-premium-card-title-color);
  --ds-signal-card-body-color: var(--ds-premium-card-body-color);
