  );
  --ds-command-home-control-hover-bg: var(
    --ds-button-default-bg-hover,
    color-mix(in srgb, var(--ds-color-primary) 6%, var(--ds-surface-card-bg))
  );
  --ds-command-home-control-hover-border: var(
    --ds-button-secondary-border,
    var(--ds-color-border-focus)
  );
  --ds-command-home-card-tone: var(--ds-color-primary);
  --ds-command-home-card-bg: linear-gradient(
      90deg,
      color-mix(in srgb, var(--ds-command-home-card-tone) 6%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--ds-command-home-card-tone) 4%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      180deg,
      var(--ds-surface-card-bg),
      var(--ds-surface-panel-bg)
    );
  --ds-command-home-card-shadow: var(
    --ds-surface-card-shadow,
    var(
      --ds-card-shadow,
      0 1px 2px color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent)
    )
  );
  --ds-command-home-card-shadow-hover: var(
    --ds-surface-card-shadow-hover,
    var(
      --ds-card-shadow-hover,
      0 2px 6px color-mix(in srgb, var(--ds-color-text-primary) 8%, transparent)
    )
  );
  --ds-command-home-meter-bg: var(
    --ds-meter-track,
    color-mix(in srgb, var(--ds-color-border-primary) 72%, transparent)
  );
  --ds-command-home-meter-fill: var(
    --ds-meter-fill,
