  --ds-home-grid-line: var(--ds-command-home-grid-line);
  --ds-home-panel-border: var(--ds-command-home-panel-border);
  --ds-home-panel-shadow: var(--ds-command-home-panel-shadow);
  --ds-home-compact-action-height: var(--ds-command-home-compact-action-height);
