/*
 * Data-table column-priority collapse (spec §10 -- component-owned layout).
 *
 * Named-container query: an unnamed `@container` resolves the nearest
 * ancestor container, which breaks the moment a table renders inside another
 * container (a rail, a card). `ds-table` is declared by the modern and
 * rustic engine roots (`container-type: inline-size; container-name:
 * ds-table`); classic (antd) declares neither and is unaffected by this rule.
 *
 * 640px is a documented component constant, not a breakpoint token: it is
 * the width below which a table built from the design-language's column
 * widths no longer has room for every column (roughly a half-split of the
 * 1280 layout). Only columns the consumer marked `priority: 'low'`
 * (`ColumnDef.priority`) are hidden here -- every other column is unaffected
 * at any container width.
 */
@container ds-table (max-width: 640px) {
  :where(.ds-pattern-data-table [data-col-priority="low"]) {
    display: none;
  }
}

}
@layer rottay-components {
/**
 * DecisionComparison — aligned, evidence-led comparison instrument.
 *
 * This pattern owns its complete shared chrome. Products provide decision data,
 * copy, permissions and DS-composed actions; they must not repaint descendants.
 * Every visual channel below is a documented custom property so a vertical or
 * DB-owned tenant can change the personality without changing this anatomy.
 */

.ds-pattern-decision-comparison[data-part="root"][data-part="root"] {
  --ds-decision-comparison-pad: var(--ds-spacing-4, 1rem);
  --ds-decision-comparison-row-height: 3rem;
  --ds-decision-comparison-radius: var(--ds-radius-xl, 1rem);
  --ds-decision-comparison-border: var(
    --ds-surface-card-border-strong,
    var(--ds-color-border-secondary)
  );
  --ds-decision-comparison-section-border: color-mix(
    in srgb,
    var(--ds-surface-card-border, var(--ds-color-border-primary)) 88%,
    var(--ds-color-text-primary) 12%
  );
  --ds-decision-comparison-body-font-size: var(
    --ds-font-size-sm,
    0.875rem
  );
  --ds-decision-comparison-detail-font-size: var(
    --ds-font-size-xs,
    0.75rem
  );
  --ds-decision-comparison-title-font-size: var(
    --ds-font-size-lg,
    1rem
  );
  --ds-decision-comparison-bg: linear-gradient(
      180deg,
      color-mix(
          in srgb,
          var(--ds-surface-card-bg, var(--ds-color-bg-elevated)) 97%,
          var(--ds-color-primary) 3%
        )
        0,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated)) 16rem
    );
  --ds-decision-comparison-shadow: inset 0 1px 0
      color-mix(in srgb, var(--ds-color-bg-elevated) 82%, transparent),
    0 1px 2px
      color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent),
    0 1.125rem 2.75rem -1.75rem
      color-mix(in srgb, var(--ds-color-text-primary) 20%, transparent);
  --ds-decision-comparison-toolbar-min-height: 4.25rem;
  --ds-decision-comparison-toolbar-bg: linear-gradient(
    100deg,
    color-mix(
      in srgb,
      var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 88%,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
    ),
    color-mix(
      in srgb,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated)) 94%,
      var(--ds-color-primary) 6%
    )
  );
  --ds-decision-comparison-verdict-bg: linear-gradient(
    112deg,
    color-mix(
      in srgb,
      var(--ds-color-primary) 9%,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
    ),
    color-mix(
      in srgb,
      var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 52%,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
    )
  );
  --ds-decision-comparison-subject-bg: linear-gradient(
    180deg,
    color-mix(
        in srgb,
        var(--ds-color-primary) 3%,
        var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
      )
      0,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated)) 13.125rem
  );
  --ds-decision-comparison-subject-leading-bg: radial-gradient(
      circle at 100% 0%,
      color-mix(in srgb, var(--ds-color-primary) 9%, transparent),
      transparent 34%
    ),
    var(--ds-decision-comparison-subject-bg);
  --ds-decision-comparison-leading-accent: linear-gradient(
    90deg,
    color-mix(
      in srgb,
      var(--ds-color-primary) 62%,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
    ),
    var(--ds-color-primary)
  );
  --ds-decision-comparison-identity-min-height: 5.75rem;
  --ds-decision-comparison-badges-min-height: 3.375rem;
  --ds-decision-comparison-visual-min-height: 13.625rem;
  --ds-decision-comparison-visual-grid-size: 1.75rem;
  --ds-decision-comparison-visual-grid-color: color-mix(
    in srgb,
    var(--ds-surface-card-border, var(--ds-color-border-primary)) 9%,
    transparent
  );
  --ds-decision-comparison-footer-bg: color-mix(
    in srgb,
    var(--ds-surface-panel-bg, var(--ds-color-bg-secondary)) 56%,
    var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
  );
  --ds-decision-comparison-insight-bg: linear-gradient(
    100deg,
    color-mix(
      in srgb,
      var(--ds-color-primary) 7%,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated))
    ),
    color-mix(
      in srgb,
      var(--ds-surface-card-bg, var(--ds-color-bg-elevated)) 97%,
      var(--ds-color-primary)
    )
  );
  --ds-decision-comparison-motion-duration: var(
    --ds-motion-reveal,
    280ms
  );
  --ds-decision-comparison-motion-easing: var(
    --ds-motion-ease-enter,
    cubic-bezier(0.22, 1, 0.36, 1)
  );

  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  container-name: ds-decision-comparison;
  container-type: inline-size;
  border: 1px solid var(--ds-decision-comparison-border);
  border-radius: var(--ds-decision-comparison-radius);
  background: var(--ds-decision-comparison-bg);
  box-shadow: var(--ds-decision-comparison-shadow);
  color: var(--ds-color-text-primary);
  animation: ds-decision-comparison-enter
    var(--ds-decision-comparison-motion-duration)
    var(--ds-decision-comparison-motion-easing) both;
}

.ds-pattern-decision-comparison[data-density="comfortable"] {
  --ds-decision-comparison-pad: var(--ds-spacing-5, 1.25rem);
  --ds-decision-comparison-row-height: 3.25rem;
