/* Two-column widgets remain useful well below a 1024px board. Collapsing them
   earlier made the resize control report a half-width state while rendering a
   full-width card and produced the dead vertical space this pattern exists to
   prevent. */
@container ds-widget-board (max-width: 839px) {
  .ds-pattern-widget-board .ds-widget-board__cell[data-size="sm"],
  .ds-pattern-widget-board .ds-widget-board__cell[data-size="md"] {
    grid-column: span 6 !important;
  }
  .ds-pattern-widget-board .ds-widget-board__cell[data-size="lg"],
  .ds-pattern-widget-board .ds-widget-board__cell[data-size="wide"] {
    grid-column: 1 / -1 !important;
  }

  .ds-pattern-widget-board .ds-widget-board__resize-tooltip,
  .ds-pattern-widget-board .ds-widget-board__resize-handle {
    display: none;
  }
}

@container ds-widget-board (max-width: 639px) {
  .ds-pattern-widget-board .ds-widget-board__toolbar {
    align-items: stretch;
    flex-direction: column;
  }
  .ds-pattern-widget-board .ds-widget-board__toolbar-actions > * {
    flex: 1 1 auto;
  }
  .ds-pattern-widget-board .ds-widget-board__toolbar-heading {
    flex: 0 1 auto;
    width: 100%;
  }
  .ds-pattern-widget-board .ds-widget-board__grid {
    grid-template-columns: minmax(0, 1fr) !important;
    gap: var(--ds-spacing-3, 12px);
  }
  .ds-pattern-widget-board .ds-widget-board__cell[data-size] {
    grid-column: 1 / -1 !important;
  }

  .ds-pattern-widget-board .ds-widget-board__item-header {
    align-items: stretch;
    flex-direction: column;
    min-height: 0;
    padding: var(--ds-spacing-3, 12px) var(--ds-spacing-4, 16px);
  }

  .ds-pattern-widget-board .ds-widget-board__item-heading {
    width: 100%;
  }

  .ds-pattern-widget-board .ds-widget-board__item-accessory {
    align-self: flex-start;
    justify-content: flex-start;
    padding-inline-start: calc(32px + var(--ds-spacing-3, 12px));
  }

  .ds-pattern-widget-board .ds-widget-board__resize-tooltip,
  .ds-pattern-widget-board .ds-widget-board__resize-handle {
    display: none;
  }

  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog-shortcut {
    display: none;
  }

  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog {
    gap: var(--ds-spacing-3, 12px);
  }

  .ds-widget-board__catalog-body {
    padding: var(--ds-spacing-4, 16px) !important;
  }

  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  :is(.ds-pattern-widget-board, .ds-widget-board__catalog-surface)
    .ds-widget-board__catalog-item {
    min-height: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-pattern-widget-board .ds-widget-board__cell,
  .ds-pattern-widget-board .ds-widget-board__toolbar,
  .ds-pattern-widget-board .ds-widget-board__toolbar-icon,
  .ds-pattern-widget-board .ds-widget-board__item-header,
  .ds-pattern-widget-board .ds-widget-board__item-icon {
    animation: none;
    transition: none;
  }
}

