   ============================================================================= */

html[data-tenant] .ant-btn {
  font-family: var(--ds-font-family-base);
  font-weight: var(--ds-button-font-weight);
  border-radius: var(--ds-button-md-radius);
  transition: var(--ds-button-transition);
  height: var(--ds-button-md-height);
