}
[data-tenant] .gap-4 {
  gap: 16px;
}
[data-tenant] .grid-cols-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
[data-tenant] .grid-cols-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

/* Responsive grid - Default columns based on data attributes */
[data-tenant] .rottay-grid[data-cols-xs="1"] {
  grid-template-columns: repeat(1, minmax(0, 1fr));
}
[data-tenant] .rottay-grid[data-cols-xs="2"] {
