  background-color: var(--ds-card-info-bg, color-mix(in srgb, var(--ds-color-info) 8%, var(--ds-card-bg)));
  background-image: none;
}

/* Explicit frame suppression remains authoritative after semantic tones. */
.ds-card.ds-card--modern[data-part='root'][data-bordered='false'] {
  border-color: transparent;
}

/* Selection stays legible on semantic materials without becoming a side rail. */
.ds-card.ds-card--modern[data-part='root'][data-selectable='true'][data-selected='true'][data-tone]:not([data-disabled='true']) {
  outline: var(--ds-card-selected-outline-width, var(--ds-card-border-width)) solid var(--ds-card-border-selected, var(--ds-color-primary));
  outline-offset: calc(-1 * var(--ds-card-selected-outline-width, var(--ds-card-border-width)));
}
.ds-card.ds-card--modern[data-part='root'][data-selectable='true'][data-selected='true'][data-tone]:not([data-disabled='true']):not([data-shadowed='false']) {
  box-shadow: var(--ds-card-shadow-selected, var(--ds-card-focus-ring));
}

/* ===========================================================================
 * WO-SKIN-05 checkpoint D1 — everything the ARC-07 migration left inline: the
 * loading state, and the header/body/actions text and rules.
 *
 * Loading shares the exact same root contract as the ready state. `data-loading`
 * distinguishes the placeholder cover from the real cover wrapper, keeping
 * radius, tenant material and accessibility state stable while content resolves.
 *
 * The `:not(.rottay-card-header)` guard on the header is equally load-bearing.
 * `Card.Header` is a compound a caller can drop into `children`, where it lands as
 * a direct child of `[data-part='body']` — exactly where this engine renders its
 * OWN header. Both stamp `data-part='header'` and `data-part='title'`, and their
 * token fallback chains differ, so without the guard this rule would repaint the
 * compound. The compound has its own file: components/skin/card-compounds.css.
 *
 * SPECIFICITY (P-48): the header and actions rules carry a border colour and must
 * clear the tenant's unlayered `*` border-color floor at (0,3,1); their selector
 * chains are far past it. They stay SHORTHANDS because preflight zeroes
 * `border-width` on every element.
 * ======================================================================== */

/* ---- loading: the cover placeholder (a fill the real cover wrapper never has) ---- */
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] > [data-part='cover'] {
  height: var(--ds-card-cover-height, var(--ds-card-cover-min-height));
  opacity: var(--ds-card-loading-cover-opacity, 0.6);
  background-color: var(--ds-surface-inset);
}

/* ---- loading: the four skeleton bars share one fill and one radius; only their
        widths and heights differ, and those stay inline ---- */
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='skeleton'] [data-part='skeleton-bar'] {
  background-color: var(--ds-card-skeleton-bg, var(--ds-surface-inset));
  background-image: linear-gradient(
    100deg,
    transparent 18%,
    var(--ds-card-skeleton-highlight, transparent) 48%,
    transparent 78%
  );
  background-size: 220% 100%;
  border-radius: var(--ds-card-skeleton-radius, var(--ds-radius-sm, 6px));
  animation: ds-card-skeleton-sweep var(--ds-card-skeleton-duration, var(--ds-motion-glacial)) var(--ds-card-transition-timing) infinite;
}
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='skeleton'] {
  opacity: var(--ds-card-loading-skeleton-opacity, 0.52);
}

/* ---- loading: the frosted spinner scrim ---- */
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='loading-overlay'] {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
  backdrop-filter: blur(var(--ds-card-loading-backdrop-blur, 4px));
  -webkit-backdrop-filter: blur(var(--ds-card-loading-backdrop-blur, 4px));
  background-color: var(--ds-card-loading-overlay-bg, color-mix(in srgb, var(--ds-surface-card) 60%, transparent));
  border-radius: inherit;
  transition: opacity var(--ds-motion-feedback) var(--ds-motion-ease-enter);
}
.ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='spinner'] {
  display: block;
  width: var(--ds-card-spinner-size, 24px);
  height: var(--ds-card-spinner-size, 24px);
  border: var(--ds-card-spinner-stroke, 2px) solid var(--ds-card-spinner-track, var(--ds-color-border));
  border-block-start-color: var(--ds-card-spinner-color, var(--ds-color-primary));
  border-radius: 50%;
  animation: ds-card-spinner-rotate var(--ds-card-spinner-duration, var(--ds-motion-glacial)) linear infinite;
}

/* ---- body ---- */
.ds-card.ds-card--modern[data-part='root'] {
  --ds-card-padding-current: var(--ds-card-padding-md, var(--ds-card-md-padding, 16px));
}
.ds-card.ds-card--modern[data-part='root'][data-padding='none'] {
