}
.ds-card.ds-card--modern[data-part='root'][data-padding='lg'] {
  --ds-card-padding-current: var(--ds-card-padding-lg, var(--ds-card-lg-padding, 24px));
}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] {
  min-inline-size: 0;
  padding: var(--ds-card-instance-padding, var(--ds-card-padding-current));
  color: var(--ds-card-body-color, inherit);
  font-size: var(--ds-card-body-font-size, inherit);
  line-height: var(--ds-card-body-line-height, inherit);
