}
.ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='actions'] > * {
  max-inline-size: 100%;
}

@container (max-width: 28rem) {
  .ds-card.ds-card--modern[data-part='root'] {
    --ds-card-actions-justify: stretch;
  }

  .ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) {
    flex-direction: column;
  }

  .ds-card.ds-card--modern[data-part='root'] > [data-part='body'] > [data-part='header']:not(.rottay-card-header) > [data-part='extra'] {
    inline-size: 100%;
    margin-inline-start: 0;
  }

  .ds-card.ds-card--modern[data-part='root'][data-cover-position='start'] > [data-part='cover'],
  .ds-card.ds-card--modern[data-part='root'][data-cover-position='end'] > [data-part='cover'] {
    flex-basis: 100%;
    min-block-size: 0;
    aspect-ratio: var(--ds-card-cover-aspect-ratio, var(--ds-card-media-aspect-ratio, 16 / 9));
