/* ===========================================================================
 * Anatomy variants (W4-A). `cardComponent.anatomy` in the tenant chrome compiles
 * to a `data-anatomy-card` attribute on the DS root; the closed vocabulary lives
 * in TENANT_THEME_ANATOMY_VARIANTS and is enforced by anatomy-variant-gate.mjs.
 * `default`/absent selects the base rendering above and needs no rule here.
 *
 * Each block prefixes the anatomy attribute onto the base root chain and REPEATS
 * `[data-part='root']`, reaching (0,5,0): one attribute over the (0,4,0)
 * variant/tone/radius rules it governs, so it wins in the same unlayered origin
 * without `!important`. Anatomy is a cross-variant frame treatment; the
 * per-instance variant still colours within the frame the anatomy defines. State
 * rules (hover/focus at (0,6,0)+) intentionally still react on top of the frame.
 * ======================================================================== */

/* framed: an explicit full border + surface shadow, uniform across variants. The
   shadow/radius reach every framed card; the neutral border is added only to an
   untoned card, so a toned card keeps its tone frame. */
[data-anatomy-card='framed'] .ds-card.ds-card--modern[data-part='root'][data-part='root'] {
  border-radius: var(--ds-card-radius, 12px);
  box-shadow: var(--ds-card-shadow, var(--ds-elevation-1));
}
[data-anatomy-card='framed'] .ds-card.ds-card--modern[data-part='root'][data-part='root']:not([data-tone]) {
  border: var(--ds-card-border-width, 1px) solid var(--ds-card-border, var(--ds-color-border-subtle));
}

/* underline: no side/top borders, one bottom hairline, tighter radius, no lift. */
[data-anatomy-card='underline'] .ds-card.ds-card--modern[data-part='root'][data-part='root'] {
  border: 0;
  border-bottom: var(--ds-card-underline-border-width, 1px) solid var(--ds-card-border, var(--ds-color-border-subtle));
  border-radius: var(--ds-card-radius-sm, 4px);
  box-shadow: none;
}

/* ghost: no frame at rest; an interactive ghost card tints only on hover. */
[data-anatomy-card='ghost'] .ds-card.ds-card--modern[data-part='root'][data-part='root'] {
  border: 0;
  box-shadow: none;
  background-color: transparent;
  background-image: none;
}
[data-anatomy-card='ghost'] .ds-card.ds-card--modern[data-part='root'][data-part='root'][data-interactive='true'][data-state~='hovered']:not([data-disabled='true']) {
  background-color: var(--ds-card-bg-hover, color-mix(in srgb, var(--ds-color-text-primary) 5%, transparent));
}

/* Instance-level suppression and unavailable state are terminal even when a
   tenant selects a stronger anatomy recipe. */
.ds-card.ds-card--modern[data-part='root'][data-bordered='false'] {
  border-color: transparent;
}
.ds-card.ds-card--modern[data-part='root'][data-shadowed='false'] {
  box-shadow: none;
}
.ds-card.ds-card--modern[data-part='root'][data-disabled='true'] {
  cursor: var(--ds-card-disabled-cursor, not-allowed);
  opacity: var(--ds-card-disabled-opacity, var(--ds-state-disabled-opacity, 0.6));
  color: var(--ds-card-color-disabled, var(--ds-color-text-disabled));
  background-color: var(--ds-card-bg-disabled, var(--ds-material-card-background-disabled));
  border-color: var(--ds-card-border-disabled, var(--ds-material-card-border-disabled));
  outline: none;
  box-shadow: none;
  transform: none;
  pointer-events: none;
}
.ds-card.ds-card--modern[data-part='root'][data-disabled='true']::after {
  opacity: 0;
}

@keyframes ds-card-spinner-rotate {
  to { transform: rotate(1turn); }
}

@keyframes ds-card-skeleton-sweep {
  from { background-position: 120% 0; }
  to { background-position: -120% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .ds-card.ds-card--modern[data-part='root'],
  .ds-card.ds-card--modern[data-part='root'] *,
  .ds-card.ds-card--modern[data-part='root']::after {
    scroll-behavior: auto;
    transition-duration: 0.01ms;
  }

  .ds-card.ds-card--modern[data-part='root'] {
    transform: none;
  }

  .ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='spinner'] {
    animation: none;
  }

  .ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='skeleton-bar'] {
    animation: none;
    background-image: none;
  }
}

@media (forced-colors: active) {
  .ds-card.ds-card--modern[data-part='root'] {
    border: 1px solid CanvasText;
    background: Canvas;
    color: CanvasText;
    box-shadow: none;
  }

  .ds-card.ds-card--modern[data-part='root'][data-actionable='true'][data-state~='focus-visible'] {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }

  .ds-card.ds-card--modern[data-part='root'][data-selectable='true'][data-selected='true'] {
    border-color: Highlight;
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }

  .ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='loading-overlay'] {
    background: Canvas;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }

  .ds-card.ds-card--modern[data-part='root'][data-loading='true'] [data-part='spinner'] {
    border-color: CanvasText;
    border-block-start-color: Highlight;
  }

  .ds-card.ds-card--modern[data-part='root']::after {
    display: none;
  }
}

}
@layer rottay-engines {
/**
 * Rustic Card skin (WO-ARC-07).
 *
 * DELIBERATELY UNLAYERED, at (0,4,0): no `rottay-*` cascade layer can paint a
 * component (Tailwind's `@layer base` sorts after all seven; P-47), and each
 * tenant's unlayered `*` border floor sits at (0,3,1) (P-48).
 *
 * Two of the object's conditions are named here rather than implied by order:
 *
 *   - hover is gated on `hoverable`, not on `clickable`. A clickable card that is
 *     not hoverable paints a pointer and does not lift.
 *   - a toned card does not take the hover background or the hover border,
 *     because its tone already decides both. The object said this by testing
 *     `!hasColorVariant`; the sheet says `:not([data-tone])`.
 *
 * The `backgroundColor` PROP stays inline. It is a caller's value, like `style`,
 * and it outranked the variant map before this file existed.
 */

/* base */
.rottay-card.rottay-card--rustic[data-part='root'] {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0) scale(1);
  /* references a DS variable so tenants can customize easing */
  transition: var(--ds-card-transition, box-shadow 0.3s, transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.2s);
}

.rottay-card.rottay-card--rustic[data-part='root'][data-clickable='true'] {
  cursor: pointer;
}

/* radius */
.rottay-card.rottay-card--rustic[data-part='root'][data-radius='none'] { border-radius: 0; }
.rottay-card.rottay-card--rustic[data-part='root'][data-radius='sm'] { border-radius: var(--ds-card-radius-sm, 4px); }
.rottay-card.rottay-card--rustic[data-part='root'][data-radius='md'] { border-radius: var(--ds-card-radius, 12px); }
.rottay-card.rottay-card--rustic[data-part='root'][data-radius='lg'] { border-radius: var(--ds-card-radius-lg, 12px); }
.rottay-card.rottay-card--rustic[data-part='root'][data-radius='xl'] { border-radius: var(--ds-card-radius-xl, 16px); }

/* variant, at rest */
.rottay-card.rottay-card--rustic[data-part='root'][data-variant='elevated'] {
  background-color: var(--ds-card-bg, #fff);
  border: 0 solid transparent;
  box-shadow: var(--ds-card-shadow, 0 4px 6px -1px rgba(0, 0, 0, 0.1));
}
.rottay-card.rottay-card--rustic[data-part='root'][data-variant='outlined'] {
  background-color: var(--ds-card-bg, #fff);
  border: 1px solid var(--ds-card-border, #e5e5e5);
  box-shadow: none;
}
.rottay-card.rottay-card--rustic[data-part='root'][data-variant='filled'] {
  background-color: var(--ds-color-neutral-100, #f5f5f5);
  border: 0 solid transparent;
  box-shadow: none;
}
.rottay-card.rottay-card--rustic[data-part='root'][data-variant='ghost'] {
  background-color: transparent;
  border: 0 solid transparent;
  box-shadow: none;
}

/* an elevated card rises a step while hovered */
.rottay-card.rottay-card--rustic[data-part='root'][data-hoverable='true'][data-variant='elevated'][data-state~='hovered'] {
  box-shadow: var(--ds-card-shadow-lg, 0 10px 15px -3px rgba(0, 0, 0, 0.1));
}

/* colour tone: it decides the frame, so hover leaves it alone */
.rottay-card.rottay-card--rustic[data-part='root'][data-tone='primary'] {
  border-color: var(--ds-color-primary-500, #3b82f6);
  background-color: var(--ds-color-primary-50, rgba(59, 130, 246, 0.05));
}
.rottay-card.rottay-card--rustic[data-part='root'][data-tone='success'] {
  border-color: var(--ds-color-success-500, #22c55e);
  background-color: var(--ds-color-success-50, rgba(34, 197, 94, 0.05));
}
.rottay-card.rottay-card--rustic[data-part='root'][data-tone='warning'] {
  border-color: var(--ds-color-warning-500, #f59e0b);
  background-color: var(--ds-color-warning-50, rgba(245, 158, 11, 0.05));
}
.rottay-card.rottay-card--rustic[data-part='root'][data-tone='error'] {
  border-color: var(--ds-color-error-500, #ef4444);
  background-color: var(--ds-color-error-50, rgba(239, 68, 68, 0.05));
}
.rottay-card.rottay-card--rustic[data-part='root'][data-tone='info'] {
  border-color: var(--ds-color-info-500, #3b82f6);
  background-color: var(--ds-color-info-50, rgba(59, 130, 246, 0.05));
}

/* hover: the lift, and the surface shift an untoned card takes */
.rottay-card.rottay-card--rustic[data-part='root'][data-hoverable='true'][data-state~='hovered'] {
  transform: var(--ds-card-hover-transform, translateY(-2px) scale(1.005));
}
.rottay-card.rottay-card--rustic[data-part='root'][data-hoverable='true'][data-state~='hovered']:not([data-tone]) {
  background-color: var(--ds-card-bg-hover, inherit);
  border-color: var(--ds-card-border-hover, var(--ds-card-border, transparent));
}

/* loading dims the card and refuses the pointer */
.rottay-card.rottay-card--rustic[data-part='root'][data-loading='true'] {
  opacity: 0.7;
  pointer-events: none;
}

/* ===========================================================================
 * WO-SKIN-05 checkpoint D1 — everything the ARC-07 migration left inline: the
 * header and actions rules, the description ink, and the loading scrim.
