.rottay-upload.rottay-upload--rustic [data-part='preview-close-button'],
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='preview-close-button'] {
  border: none;
  border-radius: 50%;
  background: var(--ds-upload-preview-close-bg);
  color: var(--ds-upload-preview-close-color);
