.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='progress-track'] {
  background: var(--ds-upload-progress-track);
  border-radius: 4px;
}
.rottay-upload.rottay-upload--rustic [data-part='progress-bar'],
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='progress-bar'] {
  background: var(--ds-upload-progress-fill);
  border-radius: 4px;
