.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='file-item'] > [data-part='file-item-action'] {
  border: none;
  background: transparent;
  color: var(--ds-upload-file-remove-color);
}
.rottay-upload.rottay-upload--rustic [data-part='file-item-overlay'] [data-part='file-item-action'],
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='file-item-overlay'] [data-part='file-item-action'] {
  border: none;
  background: transparent;
  color: var(--ds-upload-overlay-action-color);
  border-radius: 50%;
