.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='file-item-overlay'] {
  background: var(--ds-upload-preview-overlay);
  border-radius: 0;
}
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-circle [data-part='file-item-overlay'],
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-circle [data-part='file-item-overlay'] {
  border-radius: 50%;
}

/* ---- file-item: card + circle share background/border (cardContainer),
        radius differs; error status doubles the border width, both
        variants. ---- */
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-card [data-part='file-item'],
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-circle [data-part='file-item'],
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-card [data-part='file-item'],
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-circle [data-part='file-item'] {
  background: var(--ds-upload-card-bg);
  border: 1px solid var(--ds-upload-card-border);
}
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-card [data-part='file-item'][data-status='error'],
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-circle [data-part='file-item'][data-status='error'],
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-card [data-part='file-item'][data-status='error'],
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-circle [data-part='file-item'][data-status='error'] {
  border: 2px solid var(--ds-upload-error-border);
}
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-card [data-part='file-item'],
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-card [data-part='file-item'] {
  border-radius: var(--ds-upload-file-radius);
}
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-circle [data-part='file-item'],
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-circle [data-part='file-item'] {
  border-radius: 50%;
}

/* ---- file-item: picture + text share background/radius (NOT card/circle);
        error status ADDS a 1px border neither variant has by default. ---- */
.rottay-upload.rottay-upload--rustic:not(.rottay-upload--picture-card):not(.rottay-upload--picture-circle) [data-part='file-item'],
.rottay-upload-dragger.rottay-upload-dragger--rustic:not(.rottay-upload-dragger--picture-card):not(.rottay-upload-dragger--picture-circle) [data-part='file-item'] {
  background: var(--ds-upload-file-bg);
  border-radius: var(--ds-upload-file-radius);
}
.rottay-upload.rottay-upload--rustic:not(.rottay-upload--picture-card):not(.rottay-upload--picture-circle) [data-part='file-item'][data-status='error'],
.rottay-upload-dragger.rottay-upload-dragger--rustic:not(.rottay-upload-dragger--picture-card):not(.rottay-upload-dragger--picture-circle) [data-part='file-item'][data-status='error'] {
  border: 1px solid var(--ds-upload-error-border);
}

/* ---- filename text: identical `--ds-upload-file-color` token across all
        four variants -- card/circle's fallback span is a direct child of
        file-item; picture/text's filename span is nested one level deeper
        (inside the flex-1 wrapper div). Both selectors folded into one rule
        since the value never differs by variant. ---- */
.rottay-upload.rottay-upload--rustic [data-part='file-item'] > span,
.rottay-upload.rottay-upload--rustic [data-part='file-item'] > div > span,
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='file-item'] > span,
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='file-item'] > div > span {
  color: var(--ds-upload-file-color);
}

/* ---- thumbnail img: a direct child of file-item in all three image-capable
        variants (card, circle, picture); radius differs per variant. ---- */
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-card [data-part='file-item'] > img,
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-card [data-part='file-item'] > img {
  border-radius: 0;
}
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-circle [data-part='file-item'] > img,
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture-circle [data-part='file-item'] > img {
  border-radius: 50%;
}
.rottay-upload.rottay-upload--rustic.rottay-upload--picture [data-part='file-item'] > img,
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture [data-part='file-item'] > img {
  border-radius: var(--ds-upload-file-radius);
}

/* ---- picture-row fallback icon (no thumb): the wrapper div has no
        data-part; it :has() the FileIcon svg the img alternative never
        renders alongside. ---- */
.rottay-upload.rottay-upload--rustic.rottay-upload--picture [data-part='file-item'] > div:has(svg),
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture [data-part='file-item'] > div:has(svg) {
  border-radius: var(--ds-upload-file-radius);
  background: var(--ds-upload-file-bg);
}
.rottay-upload.rottay-upload--rustic.rottay-upload--picture [data-part='file-item'] svg,
.rottay-upload-dragger.rottay-upload-dragger--rustic.rottay-upload-dragger--picture [data-part='file-item'] svg {
  color: var(--ds-upload-dragger-icon-color);
}

/* ---- add-button (picture-card/circle "add" tile): Upload only, Dragger has
        no add-button. Border color repeats the data-part to reach (0,4,0). ---- */
.rottay-upload.rottay-upload--rustic [data-part='add-button'][data-part='add-button'] {
  border: 2px dashed var(--ds-upload-card-border);
  background: transparent;
  border-radius: var(--ds-upload-file-radius);
}
.rottay-upload.rottay-upload--rustic.rottay-upload--picture-circle [data-part='add-button'] {
  border-radius: 50%;
}
.rottay-upload.rottay-upload--rustic [data-part='add-button'] svg {
  color: var(--ds-upload-dragger-icon-color);
}

/* ---- trigger (text/picture default button): Upload only. ---- */
.rottay-upload.rottay-upload--rustic [data-part='trigger'][data-part='trigger'] button {
  border: 1px solid var(--ds-upload-button-border);
  border-radius: var(--ds-upload-button-radius);
  background: var(--ds-upload-button-bg);
  color: var(--ds-upload-button-color);
}

/* ---- dropzone (Dragger only): the pre-existing `dropzoneStyle` ternary was
        already a single inline-style source of truth (unlike modern's split
        class+style hybrid), so both drag states fold cleanly into CSS keyed
        on the pre-existing `data-state='dragging'|'idle'` attribute. ---- */
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='dropzone'][data-part='dropzone'] {
  border: 2px dashed var(--ds-upload-dragger-border);
  border-radius: var(--ds-upload-dragger-radius);
  background: var(--ds-upload-dragger-bg);
}
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='dropzone'][data-state='dragging'] {
  border-color: var(--ds-upload-dragger-border-active);
  background: var(--ds-upload-dragger-bg-hover);
}
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='dropzone'] svg {
  color: var(--ds-upload-dragger-icon-color);
}
.rottay-upload-dragger.rottay-upload-dragger--rustic [data-part='dropzone'] p {
  color: var(--ds-upload-dragger-text-color);
}

}
