      145deg,
      color-mix(in srgb, var(--ds-color-primary) 5%, transparent),
      transparent 44%
    ),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--ds-surface-card) 98%, white 2%),
      color-mix(in srgb, var(--ds-surface-card) 96%, var(--ds-color-primary) 4%)
    );
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, white 62%, transparent),
    var(--ds-dropdown-shadow, var(--ds-elevation-3, 0 16px 40px rgb(15 23 42 / 0.14)));
  backdrop-filter: blur(var(--ds-dropdown-backdrop-blur, 16px)) saturate(1.08);
  transform-origin: center top;
