.rottay-dropdown__surface.rottay-dropdown__surface[data-part='surface'][data-part='surface'] {
  border: var(--ds-dropdown-border-width, 1px) solid
    var(--ds-dropdown-border-color, color-mix(in srgb, var(--ds-color-border) 86%, var(--ds-color-primary) 14%));
}

.rottay-dropdown__surface[data-part='surface'][data-placement^='top'] {
  transform-origin: center bottom;
}

.rottay-dropdown__surface[data-part='surface'] > [data-part='menu'] {
