  inline-size: 100%;
  min-block-size: var(--ds-dropdown-item-height, 2.4rem);
  padding: var(--ds-dropdown-item-padding-y, 0.45rem) var(--ds-dropdown-item-padding-x, 0.55rem);
  align-items: center;
  overflow: hidden;
