  .rottay-dropdown__surface[data-part='surface'] [data-part='item'],
  .rottay-dropdown__surface[data-part='surface'] [data-part='item']::after,
  .rottay-dropdown__surface[data-part='surface'] [data-part='icon'],
  .rottay-dropdown__surface[data-part='surface'] [data-part='selection-indicator'],
  .rottay-dropdown__surface[data-part='surface'] [data-part='submenu'] {
    animation: none;
    transition-duration: 0.01ms;
  }
