  color: var(--ds-color-text-primary);
}
.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-part='root'][data-variant='primary']:not([data-outlined]) {
  background: var(--ds-tag-custom-bg, var(--ds-tag-primary-solid-bg, var(--ds-color-primary)));
  color: var(--ds-tag-primary-ink, var(--ds-color-text-on-primary, var(--ds-color-white, #fff)));
}
.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-part='root'][data-variant='secondary']:not([data-outlined]) {
  background: var(--ds-tag-custom-bg, var(--ds-tag-secondary-solid-bg, color-mix(in srgb, var(--ds-color-secondary) 82%, var(--ds-color-black, #000) 18%)));
  color: var(--ds-tag-secondary-ink, var(--ds-color-white, #fff));
}
.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-part='root'][data-variant='success']:not([data-outlined]) {
  background: var(--ds-tag-custom-bg, var(--ds-tag-success-solid-bg, color-mix(in srgb, var(--ds-color-success) 62%, var(--ds-color-black, #000) 38%)));
  color: var(--ds-tag-success-ink, var(--ds-color-white, #fff));
}
.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-part='root'][data-variant='warning']:not([data-outlined]) {
  background: var(--ds-tag-custom-bg, var(--ds-tag-warning-solid-bg, color-mix(in srgb, var(--ds-color-warning) 55%, var(--ds-color-black, #000) 45%)));
  color: var(--ds-tag-warning-ink, var(--ds-color-white, #fff));
}
.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-part='root'][data-variant='error']:not([data-outlined]) {
  background: var(--ds-tag-custom-bg, var(--ds-tag-error-solid-bg, color-mix(in srgb, var(--ds-color-error) 78%, var(--ds-color-black, #000) 22%)));
  color: var(--ds-tag-error-ink, var(--ds-color-white, #fff));
