.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-part='root'][data-variant='primary'][data-outlined='true'] {
  border: 1px solid var(--ds-color-primary);
  color: var(--ds-tag-primary-outlined-ink, var(--ds-color-primary));
