.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-part='root'][data-bordered='true'] {
  box-shadow:
    inset 0 0 0 var(--ds-tag-border-width, 1px) var(--ds-color-border),
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 20%, transparent),
    var(--ds-tag-shadow, 0 2px 7px color-mix(in srgb, currentColor 8%, transparent));
