.rottay-tag-shell.rottay-tag-shell--modern > [data-part='close'][data-part='close'] {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  inline-size: var(--ds-tag-close-size, 1rem);
  block-size: var(--ds-tag-close-size, 1rem);
  margin-inline-start: var(--ds-tag-close-gap, 0.125rem);
  padding: 0;
  border: 1px solid color-mix(in srgb, currentColor 17%, transparent);
