    transform var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    filter var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
