  filter: saturate(1.06);
}

.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-clickable='true']:hover > [data-part='icon'] {
  transform: translateY(-1px);
}

.rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-clickable='true']:focus-visible {
  box-shadow: var(
    --ds-tag-focus-ring,
    0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 22%, transparent)
