@media (prefers-reduced-motion: reduce) {
  .rottay-tag-shell.rottay-tag-shell--modern[data-part='root'],
  .rottay-tag-shell.rottay-tag-shell--modern > [data-part='icon'],
  .rottay-tag-shell.rottay-tag-shell--modern > [data-part='close'] {
    transition: none;
  }
  .rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-clickable='true']:hover,
  .rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-clickable='true']:active,
  .rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-clickable='true']:hover > [data-part='icon'],
  .rottay-tag-shell.rottay-tag-shell--modern > [data-part='close']:hover {
    transform: none;
  }
}

@media (forced-colors: active) {
  .rottay-tag-shell.rottay-tag-shell--modern[data-part='root'] {
    border: 1px solid ButtonText;
    background: Canvas;
    color: ButtonText;
    box-shadow: none;
    forced-color-adjust: auto;
  }
  .rottay-tag-shell.rottay-tag-shell--modern[data-part='root'][data-clickable='true']:focus-visible,
  .rottay-tag-shell.rottay-tag-shell--modern > [data-part='close']:focus-visible {
