  width: var(--ds-tree-checkbox-size, 16px);
  height: var(--ds-tree-checkbox-size, 16px);
  margin-inline-end: var(--ds-tree-checkbox-margin, 8px);
  flex-shrink: 0;
  cursor: pointer;
  accent-color: var(--ds-color-primary);
