.ds-structure.ds-edit-fields[data-part='editor'] > [data-part='editor-header'] [data-part='editor-title'] {
  color: var(--ds-color-text-primary);
}

.ds-structure.ds-edit-fields[data-part='editor'] > [data-part='editor-header'] [data-part='editor-description'] {
  color: var(--ds-color-text-secondary);
}

/* --- InlineEditGrid -------------------------------------------------------- */

.ds-structure.ds-edit-fields[data-part='grid'][data-part='grid'] {
