}

/* --- InlineEditSection ----------------------------------------------------- */

.ds-structure.ds-edit-fields[data-part='section'] > [data-part='section-header'] [data-part='section-icon'],
.ds-structure.ds-edit-fields[data-part='section'] > [data-part='section-header'] [data-part='section-number'],
.ds-structure.ds-edit-fields[data-part='section'] > [data-part='section-header'] [data-part='section-description'] {
  color: var(--ds-color-text-muted);
}

.ds-structure.ds-edit-fields[data-part='section'] > [data-part='section-header'] [data-part='section-title'] {
  color: var(--ds-color-text-primary);
}

/* --- InlineEditField ------------------------------------------------------- */

/* `field-label-row` carries no consumer slot: every node under it is rendered by
