}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'][data-tone='governance'] {
  --ds-form-sections-surface: color-mix(in srgb, var(--ds-surface-card, var(--ds-color-bg-elevated)) 95%, var(--ds-color-bg-primary) 5%);
  --ds-form-sections-muted-surface: color-mix(in srgb, var(--ds-surface-card, var(--ds-color-bg-elevated)) 90%, var(--ds-color-bg-primary) 10%);
  --ds-form-sections-border: color-mix(in srgb, var(--ds-color-border-secondary) 82%, var(--ds-color-bg-primary) 18%);
  --ds-form-sections-active-border: color-mix(in srgb, var(--ds-color-border) 74%, var(--ds-color-bg-primary) 26%);
  --ds-form-sections-divider: color-mix(in srgb, var(--ds-color-border-secondary) 72%, var(--ds-color-bg-primary) 28%);
  --ds-form-sections-badge-bg: color-mix(in srgb, var(--ds-color-bg-primary) 44%, transparent);
  --ds-form-sections-badge-border: color-mix(in srgb, var(--ds-color-border) 62%, var(--ds-color-bg-primary) 38%);
  --ds-form-sections-accent: color-mix(in srgb, var(--ds-color-text-primary) 14%, transparent);
  --ds-form-sections-accent-secondary: color-mix(in srgb, var(--ds-color-text-secondary) 8%, transparent);
  --ds-form-sections-grid-color: color-mix(in srgb, var(--ds-color-text-muted) 26%, transparent);
  --ds-form-sections-grid-size: 24px;
}

/* --- Section shell --------------------------------------------------------- */

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'] {
  color: var(--ds-color-text-primary);
}

/* card (default): the open section lifts -- brighter surface, firmer border, and
   the only box-shadow in the family. */
.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'][data-appearance='card'] {
  border-radius: 18px;
  border: 1px solid var(--ds-form-sections-border);
  background: var(--ds-form-sections-muted-surface);
  box-shadow: none;
}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'][data-appearance='card'][data-open='true'] {
  border-color: var(--ds-form-sections-active-border);
  background: var(--ds-form-sections-surface);
  box-shadow: var(--ds-form-sections-shadow);
}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'][data-appearance='soft'] {
  border-radius: 18px;
  border: 1px solid var(--ds-form-sections-border);
  background: var(--ds-form-sections-muted-surface);
  box-shadow: none;
}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'][data-appearance='divided'] {
  border-radius: 0;
  border: none;
  background: transparent;
  box-shadow: none;
}

