  border-bottom: 1px solid var(--ds-form-sections-divider);
}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'] > button[data-part='section-header'] {
  border: none;
}

/* --- Section index --------------------------------------------------------- */

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'] > [data-part='section-header'] [data-part='section-index'][data-part='section-index'] {
  border-radius: 9px;
  border: 1px solid var(--ds-form-sections-border);
  background: transparent;
  color: var(--ds-color-text-tertiary);
}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'][data-open='true']:not([data-appearance='divided']) > [data-part='section-header'] [data-part='section-index'][data-part='section-index'] {
  border-color: var(--ds-form-sections-active-border);
  background: var(--ds-form-sections-muted-surface);
}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'][data-appearance='divided'] > [data-part='section-header'] [data-part='section-index'][data-part='section-index'] {
  border-color: var(--ds-form-sections-divider);
  background: transparent;
}

/* --- Section title / description ------------------------------------------- */

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'] > [data-part='section-header'] [data-part='section-title'] {
  color: var(--ds-color-text-primary);
}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'] > [data-part='section-header'] [data-part='section-description'] {
  color: var(--ds-color-text-secondary);
}

/* --- Section summary badge -------------------------------------------------- */

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'] > [data-part='section-header'] [data-part='section-summary'][data-part='section-summary'] {
  border-radius: 999px;
  border: 1px solid var(--ds-form-sections-badge-border);
  background: var(--ds-form-sections-badge-bg);
}

.ds-structure.ds-form-sections[data-part='root'] > [data-part='section'] > [data-part='section-header'] [data-part='section-summary-text'] {
  color: var(--ds-color-text-primary);
