@layer rottay-components {
/** Domain-free stress fixture. Composition is local; paint comes from public theme variables. */

.ds-visual-excellence {
  width: 100%;
  min-width: 0;
  overflow: clip;
  border: 1px solid var(--ds-surface-card-border-strong, var(--ds-color-border-secondary));
  border-radius: var(--ds-radius-2xl);
  background: radial-gradient(
      circle at 72% -10%,
      color-mix(in srgb, var(--ds-color-primary) 12%, transparent),
      transparent 34%
    ),
    var(--ds-shell-bg, var(--ds-layout-bg, var(--ds-color-bg-primary)));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 90%, transparent),
    var(--ds-shadow-lg, 0 26px 70px color-mix(in srgb, var(--ds-color-text-primary) 12%, transparent));
  container-type: inline-size;
  animation: ds-visual-excellence-arrive var(--ds-motion-slow, 320ms)
    var(--ds-motion-ease-out, ease-out) both;
}

.ds-visual-excellence__command-bar {
  display: grid;
  grid-template-columns: minmax(210px, 1fr) minmax(320px, 1.4fr) minmax(210px, 1fr);
  gap: var(--ds-spacing-4, 16px);
  align-items: center;
  min-height: 64px;
  padding: var(--ds-spacing-3, 12px) var(--ds-spacing-5, 20px);
  border-bottom: 1px solid
    var(--ds-surface-card-border, var(--ds-color-border-primary));
  background: linear-gradient(
    112deg,
    color-mix(in srgb, var(--ds-surface-card-bg, white) 96%, var(--ds-color-primary)) 0%,
    var(--ds-glass-background, var(--ds-surface-card-bg, white)) 46%,
    color-mix(in srgb, var(--ds-surface-card-bg, white) 90%, var(--ds-color-primary)) 100%
  );
  background-size: 180% 180%;
  backdrop-filter: blur(var(--ds-glass-blur, 12px));
  box-shadow: 0 6px 24px -18px color-mix(in srgb, var(--ds-color-text-primary) 34%, transparent);
  animation: ds-visual-excellence-header-shift 12s ease-in-out infinite alternate;
}

.ds-visual-excellence__command-context,
.ds-visual-excellence__command-account,
.ds-visual-excellence__navigation-copy,
.ds-visual-excellence__hero-actions {
  min-width: 0;
}

.ds-visual-excellence__command-context,
.ds-visual-excellence__command-account,
.ds-visual-excellence__evidence-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ds-spacing-2, 8px);
}

.ds-visual-excellence__command-context > span[aria-hidden='true'] {
  width: 1px;
  height: 20px;
  background: var(--ds-surface-card-border, var(--ds-color-border-primary));
}

.ds-visual-excellence__command-account {
  justify-content: flex-end;
}

.ds-visual-excellence__command-search {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: var(--ds-spacing-2, 8px);
  align-items: center;
  min-width: 0;
  min-height: 38px;
  padding: 0 var(--ds-spacing-3, 12px);
  overflow: hidden;
  border: 1px solid var(--ds-surface-card-border, var(--ds-color-border-primary));
  border-radius: var(--ds-radius-lg, 12px);
  background: var(--ds-surface-card-bg, var(--ds-color-bg-elevated));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 84%, transparent),
    var(--ds-shadow-sm, 0 1px 3px color-mix(in srgb, var(--ds-color-text-primary) 8%, transparent));
  color: var(--ds-color-text-muted);
  cursor: pointer;
  font: inherit;
  text-align: start;
  transition:
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out, ease-out);
}

.ds-visual-excellence__command-search:hover,
.ds-visual-excellence__command-search:focus-visible {
  border-color: color-mix(in srgb, var(--ds-color-primary) 46%, var(--ds-color-border-primary));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--ds-color-primary) 9%, transparent);
  outline: none;
}

.ds-visual-excellence__command-search > span:nth-child(2) {
