  color: var(--ds-color-primary);
  border-color: var(--ds-tint-24);
}
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--success,
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-success,
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-green {
  background: var(--ds-tint-success-8);
  color: var(--ds-color-success);
  border-color: var(--ds-tint-success-24);
}
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--warning,
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-warning,
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-gold,
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-orange {
  background: var(--ds-tint-warning-8);
  color: var(--ds-color-warning);
  border-color: var(--ds-tint-warning-24);
}
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--error,
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-error,
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-red {
